const ENGLISH_DICTIONARY_INDEX = Object.freeze([{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Hello / Hi","secondary":"/həˈloʊ / haɪ/","desc":"Olá / Oi","context":"Saudação universal usada em qualquer momento do dia.","audio":"Hello / Hi","level":"A1","module":"Greetings & Basic Courtesy"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Good morning","secondary":"/ɡʊd ˈmɔːrnɪŋ/","desc":"Bom dia","context":"Usado do amanhecer até as 12:00 (meio-dia).","audio":"Good morning","level":"A1","module":"Greetings & Basic Courtesy"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Good afternoon","secondary":"/ɡʊd ˌæftərˈnuːn/","desc":"Boa tarde","context":"Usado entre 12:00 e o pôr do sol (~18:00).","audio":"Good afternoon","level":"A1","module":"Greetings & Basic Courtesy"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Good evening","secondary":"/ɡʊd ˈiːvnɪŋ/","desc":"Boa noite (chegada)","context":"Usado ao encontrar alguém à noite.","audio":"Good evening","level":"A1","module":"Greetings & Basic Courtesy"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Good night","secondary":"/ɡʊd naɪt/","desc":"Boa noite (despedida)","context":"Usado exclusivamente ao se despedir ou ir dormir.","audio":"Good night","level":"A1","module":"Greetings & Basic Courtesy"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Cortesia Básica: Please & Thank you","secondary":"[Pedido] + please / Thank you + very much","desc":"Adicione 'Please' para fazer pedidos educados e 'Thank you' (ou 'Thanks') para agradecer. Para dizer 'De nada', use 'You are welcome'.","context":"Water, please. ➔ (Água, por favor). Thank you very much! ➔ (Muito obrigado!).","audio":"Cortesia Básica: Please & Thank you","level":"A1","module":"Greetings & Basic Courtesy"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Diferença: Good evening vs. Good night","secondary":"Chegada ➔ Good evening | Saída ➔ Good night","desc":"'Good evening' é a saudação de entrada/chegada à noite. 'Good night' é a despedida de saída ou quando se vai dormir.","context":"Good evening, welcome! (Ao chegar). Good night, see you tomorrow! (Ao sair).","audio":"Diferença: Good evening vs. Good night","level":"A1","module":"Greetings & Basic Courtesy"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"My name is...","secondary":"/maɪ neɪm ɪz/","desc":"Meu nome é...","context":"Fórmula clássica para se apresentar.","audio":"My name is...","level":"A1","module":"Introducing Yourself & Verb 'To Be'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I am... (I'm)","secondary":"/aɪ æm / aɪm/","desc":"Eu sou / Eu estou","context":"Usado com nomes, profissões e estados.","audio":"I am... (I'm)","level":"A1","module":"Introducing Yourself & Verb 'To Be'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Nice to meet you","secondary":"/naɪs tuː miːt juː/","desc":"Prazer em conhecê-lo(a)","context":"Expressão essencial ao conhecer alguém.","audio":"Nice to meet you","level":"A1","module":"Introducing Yourself & Verb 'To Be'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbo 'To Be' Afirmativo (Am / Is / Are)","secondary":"I + am | He/She/It + is | You/We/They + are","desc":"O verbo 'To Be' significa 'ser' ou 'estar'. Use 'Am' para I, 'Is' para He/She/It, e 'Are' para You/We/They.","context":"I am Carlos. She is Maria. We are happy.","audio":"Verbo 'To Be' Afirmativo (Am / Is / Are)","level":"A1","module":"Introducing Yourself & Verb 'To Be'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Contrações do Verbo 'To Be'","secondary":"I am = I'm | You are = You're | She is = She's","desc":"No inglês falado cotidiano, é muito comum contrair o verbo: I'm, You're, He's, She's, It's, We're, They're.","context":"I'm a student. She's happy. They're here.","audio":"Contrações do Verbo 'To Be'","level":"A1","module":"Introducing Yourself & Verb 'To Be'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Where are you from?","secondary":"/weər ɑːr juː frɒm/","desc":"De onde você é?","context":"Pergunta chave para saber a origem de alguém.","audio":"Where are you from?","level":"A1","module":"Personal Pronouns & Countries"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I am from Brazil / USA / Japan","secondary":"/frɒm brəˈzɪl/","desc":"Eu sou do Brasil / EUA / Japão","context":"Estrutura para indicar seu país.","audio":"I am from Brazil / USA / Japan","level":"A1","module":"Personal Pronouns & Countries"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Country vs. Nationality","secondary":"/ˈkʌntri / ˌnæʃəˈnæləti/","desc":"País vs. Nacionalidade","context":"Ex: Brazil ➔ Brazilian | Japan ➔ Japanese.","audio":"Country vs. Nationality","level":"A1","module":"Personal Pronouns & Countries"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pronomes Pessoais Sujeitos (Subject Pronouns)","secondary":"[Pronome] + [To Be] + from + [País]","desc":"Substituem o nome da pessoa/coisa que faz a ação: I (Eu), You (Você/Vocês), He (Ele - homem), She (Ela - mulher), It (Objeto/Animal/Tempo), We (Nós), They (Eles/Elas).","context":"He is from Canada. They are from Italy.","audio":"Pronomes Pessoais Sujeitos (Subject Pronouns)","level":"A1","module":"Personal Pronouns & Countries"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Uso da preposição 'From'","secondary":"Subject + To Be + from + Country","desc":"'From' indica origem/procedência. Sempre use 'from' antes do nome do país para responder de onde você vem.","context":"She is from France. We are from Brazil.","audio":"Uso da preposição 'From'","level":"A1","module":"Personal Pronouns & Countries"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Doctor / Nurse / Teacher","secondary":"/ˈdɒktər / nɜːrs / ˈtiːtʃər/","desc":"Médico(a) / Enfermeiro(a) / Professor(a)","context":"Profissões comuns.","audio":"Doctor / Nurse / Teacher","level":"A1","module":"Jobs & Professions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Engineer / Architect / Student","secondary":"/ˌendʒɪˈnɪər / ˈɑːrkɪtekt / ˈstjuːdənt/","desc":"Engenheiro(a) / Arquiteto(a) / Estudante","context":"Profissões com vogal e consoante.","audio":"Engineer / Architect / Student","level":"A1","module":"Jobs & Professions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"What do you do?","secondary":"/wɒt duː juː duː/","desc":"O que você faz? / Qual sua profissão?","context":"Pergunta padrão sobre trabalho.","audio":"What do you do?","level":"A1","module":"Jobs & Professions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra dos Artigos Indefinidos: A vs. AN","secondary":"A + som consoante (a doctor, a teacher) | AN + som vogal (an engineer, an actor)","desc":"Em inglês, SEMPRE usamos o artigo 'a' ou 'an' antes de profissões no singular! Use 'A' antes de som de consoante e 'AN' antes de som de vogal.","context":"I am a doctor. She is an engineer.","audio":"Regra dos Artigos Indefinidos: A vs. AN","level":"A1","module":"Jobs & Professions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Plural de Profissões (Sem A/AN)","secondary":"Plural ➔ Substantivo + S (sem A/AN)","desc":"No plural, NUNCA usamos 'a' ou 'an'!","context":"They are doctors. (Eles são médicos). We are students.","audio":"Plural de Profissões (Sem A/AN)","level":"A1","module":"Jobs & Professions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"How do you spell that?","secondary":"/haʊ duː juː spel ðæt/","desc":"Como se soletra isso?","context":"Pergunta usada para pedir a soletração de um nome.","audio":"How do you spell that?","level":"A1","module":"Alphabet, Spelling & Phone Numbers"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Double (L / O / S)","secondary":"/ˈdʌbəl/","desc":"Duplo (ex: L-L ➔ Double L)","context":"Usado ao soletrar letras repetidas.","audio":"Double (L / O / S)","level":"A1","module":"Alphabet, Spelling & Phone Numbers"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"What is your phone number?","secondary":"/wɒt ɪz jɔːr fəʊn ˈnʌmbər/","desc":"Qual é o seu número de telefone?","context":"Pergunta para dados de contato.","audio":"What is your phone number?","level":"A1","module":"Alphabet, Spelling & Phone Numbers"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pronúncia do Dígito Zero em Números de Telefone","secondary":"0 em telefone ➔ 'Oh' ou 'Zero'","desc":"Em números de telefone em inglês, o dígito 0 é frequentemente pronunciado como a letra 'Oh' (/oʊ/) em vez de 'Zero'.","context":"555-0192 ➔ 'Five-five-five, oh-one-nine-two'.","audio":"Pronúncia do Dígito Zero em Números de Telefone","level":"A1","module":"Alphabet, Spelling & Phone Numbers"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Símbolos de E-mail em Inglês","secondary":"@ ➔ 'at' | . ➔ 'dot'","desc":"O símbolo '@' diz-se 'at' e o ponto '.' diz-se 'dot'.","context":"carlos@gmail.com ➔ 'carlos at gmail dot com'.","audio":"Símbolos de E-mail em Inglês","level":"A1","module":"Alphabet, Spelling & Phone Numbers"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Father / Mother / Parents","secondary":"/ˈfɑːðər / ˈmʌðər / ˈpeərənts/","desc":"Pai / Mãe / Pais","context":"Núcleo familiar principal.","audio":"Father / Mother / Parents","level":"A1","module":"Family Members & Possessive 's"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Brother / Sister / Siblings","secondary":"/ˈbrʌðər / ˈsɪstər / ˈsɪblɪŋz/","desc":"Irmão / Irmã / Irmãos (geral)","context":"Irmãos e irmãs.","audio":"Brother / Sister / Siblings","level":"A1","module":"Family Members & Possessive 's"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Son / Daughter / Children","secondary":"/sʌn / ˈdɔːtər / ˈtʃɪldrən/","desc":"Filho / Filha / Filhos","context":"Descendentes.","audio":"Son / Daughter / Children","level":"A1","module":"Family Members & Possessive 's"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Caso Possessivo ('s)","secondary":"[Possuidor] + 's + [Objeto/Pessoa]","desc":"Para indicar que algo pertence a uma pessoa, adicionamos apóstrofo + S ('s) ao nome do possuidor. O possuidor vem SEMPRE antes da coisa possuída!","context":"John's car ➔ (O carro do John). Maria's mother ➔ (A mãe da Maria).","audio":"Caso Possessivo ('s)","level":"A1","module":"Family Members & Possessive 's"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Possessivo no Plural terminado em S","secondary":"[Plural com S] + '","desc":"Se o nome/substantivo plural já termina em S, adicionamos apenas o apóstrofo (').","context":"My parents' house ➔ (A casa dos meus pais).","audio":"Possessivo no Plural terminado em S","level":"A1","module":"Family Members & Possessive 's"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Numbers 1-10","secondary":"one, two, three, four, five, six, seven, eight, nine, ten","desc":"1 ao 10","context":"Contagem básica.","audio":"Numbers 1-10","level":"A1","module":"Numbers & Age (1 to 100)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Teens (13-19)","secondary":"thirteen, fourteen, fifteen... nineteen","desc":"13 ao 19 (-teen)","context":"Terminam com som forte em 'TEEN'.","audio":"Teens (13-19)","level":"A1","module":"Numbers & Age (1 to 100)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Tens (20, 30, 40...)","secondary":"twenty, thirty, forty, fifty, sixty, seventy, eighty, ninety","desc":"20, 30, 40...","context":"Terminam em 'TY'.","audio":"Tens (20, 30, 40...)","level":"A1","module":"Numbers & Age (1 to 100)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Como Falar a Idade em Inglês (VERBO TO BE)","secondary":"Subject + To Be + [Número] + (years old)","desc":"EM INGLÊS NUNCA USAMOS O VERBO 'HAVE' PARA IDADE! Usamos SEMPRE o verbo 'To Be' (Am/Is/Are). Você 'é' sua idade!","context":"I am 25 years old (NÃO 'I have 25'). She is 30 years old.","audio":"Como Falar a Idade em Inglês (VERBO TO BE)","level":"A1","module":"Numbers & Age (1 to 100)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pergunta Padrão de Idade: How old are you?","secondary":"How old are you? | How old is he/she?","desc":"Para perguntar a idade de alguém, usamos a estrutura 'How old + To Be + Subject?'.","context":"How old are you? ➔ I am 20. How old is your brother? ➔ He is 15.","audio":"Pergunta Padrão de Idade: How old are you?","level":"A1","module":"Numbers & Age (1 to 100)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"My / Your","secondary":"/maɪ / jɔːr/","desc":"Meu(s), Minha(s) / Seu(s), Sua(s)","context":"Refere-se a 'I' e 'You'.","audio":"My / Your","level":"A1","module":"Possessive Adjectives"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"His / Her / Its","secondary":"/hɪz / hɜːr / ɪts/","desc":"Dele / Dela / Dele, Dela (objetos/animais)","context":"Refere-se a 'He', 'She' e 'It'.","audio":"His / Her / Its","level":"A1","module":"Possessive Adjectives"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Our / Their","secondary":"/ˈaʊər / ðeər/","desc":"Nosso(a/s) / Dele(a)s","context":"Refere-se a 'We' e 'They'.","audio":"Our / Their","level":"A1","module":"Possessive Adjectives"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Tabela de Adjetivos Possessivos","secondary":"I➔My | You➔Your | He➔His | She➔Her | It➔Its | We➔Our | They➔Their","desc":"Adjetivos possessivos concordam com o POSSUIDOR, e NUNCA mudam no plural! Ex: 'My book' (meu livro) e 'My books' (meus livros) usam o mesmo 'My'.","context":"His car (O carro dele). Her car (O carro dela). Their house (A casa deles).","audio":"Tabela de Adjetivos Possessivos","level":"A1","module":"Possessive Adjectives"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Atenção: His vs. Her","secondary":"Homem possuidor ➔ His | Mulher possuidora ➔ Her","desc":"'His' significa DELE (homem). 'Her' significa DELA (mulher). A escolha depende do gênero da pessoa que POSSUI, não do objeto!","context":"John and his sister. Maria and her brother.","audio":"Atenção: His vs. Her","level":"A1","module":"Possessive Adjectives"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Tall / Short","secondary":"/tɔːl / ʃɔːrt/","desc":"Alto(a) / Baixo(a)","context":"Estatura física.","audio":"Tall / Short","level":"A1","module":"Describing People (Adjectives)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Friendly / Kind / Smart","secondary":"/ˈfrendli / kaɪnd / smɑːrt/","desc":"Amigável / Gentil / Inteligente","context":"Qualidades de personalidade.","audio":"Friendly / Kind / Smart","level":"A1","module":"Describing People (Adjectives)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Funny / Quiet / Shy","secondary":"/ˈfʌni / ˈkwaɪət / ʃaɪ/","desc":"Engraçado(a) / Calmo(a) / Tímido(a)","context":"Traços de comportamento.","audio":"Funny / Quiet / Shy","level":"A1","module":"Describing People (Adjectives)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Posição do Adjetivo no Inglês","secondary":"To Be + Adjetivo | Adjetivo + Substantivo","desc":"Adjetivos em inglês vêm SEMPRE ANTES do substantivo que descrevem, ou logo APÓS o verbo To Be! Além disso, adjetivos NUNCA vão para o plural!","context":"He is tall. (Ele é alto). He is a tall man. (Ele é um homem alto).","audio":"Posição do Adjetivo no Inglês","level":"A1","module":"Describing People (Adjectives)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Invariabilidade dos Adjetivos","secondary":"Tall = alto, alta, altos, altas","desc":"Não existe adjetivo feminino ou plural em inglês. A mesma palavra serve para homem, mulher, singular ou plural!","context":"He is tall. She is tall. They are tall.","audio":"Invariabilidade dos Adjetivos","level":"A1","module":"Describing People (Adjectives)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Happy / Sad","secondary":"/ˈhæpi / sæd/","desc":"Feliz / Triste","context":"Emoções básicas.","audio":"Happy / Sad","level":"A1","module":"Feelings & Emotions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Tired / Sleepy","secondary":"/ˈtaɪərd / ˈsliːpi/","desc":"Cansado(a) / Com sono","context":"Estados físicos.","audio":"Tired / Sleepy","level":"A1","module":"Feelings & Emotions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Hungry / Thirsty","secondary":"/ˈhʌŋɡri / ˈθɜːrsti/","desc":"Com fome / Com sede","context":"Necessidades de alimentação e hidratação.","audio":"Hungry / Thirsty","level":"A1","module":"Feelings & Emotions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Fome e Sede em Inglês (VERBO TO BE)","secondary":"I am hungry | She is thirsty (NÃO 'I have hunger')","desc":"EM INGLÊS NÃO DIZEMOS 'EU TENHO FOME'! Usamos o verbo To Be com os adjetivos 'hungry' (faminto) e 'thirsty' (sedento).","context":"I am hungry ➔ (Estou com fome). He is thirsty ➔ (Ele está com sede).","audio":"Expressando Fome e Sede em Inglês (VERBO TO BE)","level":"A1","module":"Feelings & Emotions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pergunta de Estado: How are you?","secondary":"How are you? ➔ I am + [Sentimento/Estado]","desc":"Para perguntar como alguém está se sentindo no momento, usamos 'How are you?' ou 'How is he/she?'.","context":"How are you? ➔ I am tired today.","audio":"Pergunta de Estado: How are you?","level":"A1","module":"Feelings & Emotions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"This / That","secondary":"/ðɪs / ðæt/","desc":"Este(a) (perto) / Aquele(a) (longe)","context":"Demonstrativos no Singular.","audio":"This / That","level":"A1","module":"Demonstratives (This, That, These, Those)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"These / Those","secondary":"/ðiːz / ðoʊz/","desc":"Estes(as) (perto) / Aqueles(as) (longe)","context":"Demonstrativos no Plural.","audio":"These / Those","level":"A1","module":"Demonstratives (This, That, These, Those)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"What is this?","secondary":"/wɒt ɪz ðɪs/","desc":"O que é isto?","context":"Pergunta para identificar objeto perto no singular.","audio":"What is this?","level":"A1","module":"Demonstratives (This, That, These, Those)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Matriz dos Pronomes Demonstrativos","secondary":"THIS/THAT + IS (singular) | THESE/THOSE + ARE (plural)","desc":"Perto + Singular ➔ THIS | Longe + Singular ➔ THAT | Perto + Plural ➔ THESE | Longe + Plural ➔ THOSE.","context":"This is a key. That is a car. These are keys. Those are cars.","audio":"Matriz dos Pronomes Demonstrativos","level":"A1","module":"Demonstratives (This, That, These, Those)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Concordância do Verbo To Be com Demonstrativos","secondary":"This is... / That is... vs. These are... / Those are...","desc":"Use 'IS' com THIS e THAT. Use 'ARE' com THESE e THOSE.","context":"This is my pen. Those are my books.","audio":"Concordância do Verbo To Be com Demonstrativos","level":"A1","module":"Demonstratives (This, That, These, Those)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Key / Wallet / Purse","secondary":"/kiː / ˈwɒlɪt / pɜːrs/","desc":"Chave / Carteira (masc/geral) / Bolsa","context":"Pertences diários.","audio":"Key / Wallet / Purse","level":"A1","module":"Everyday Objects & Belongings"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Phone / Laptop / Backpack","secondary":"/fəʊn / ˈlæptɒp / ˈbækpæk/","desc":"Telefone / Notebook / Mochila","context":"Eletrônicos e acessórios.","audio":"Phone / Laptop / Backpack","level":"A1","module":"Everyday Objects & Belongings"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Glasses / Watch / Passport","secondary":"/ˈɡlɑːsɪz / wɒtʃ / ˈpɑːspɔːt/","desc":"Óculos / Relógio de pulso / Passaporte","context":"Documentos e utilitários.","audio":"Glasses / Watch / Passport","level":"A1","module":"Everyday Objects & Belongings"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Plural dos Substantivos Regulares","secondary":"Singular + S / ES","desc":"A maioria dos substantivos em inglês forma o plural adicionando 'S'. Se terminar em s, ch, sh, x, z, adiciona-se 'ES'.","context":"Key ➔ Keys | Watch ➔ Watches | Wallet ➔ Wallets","audio":"Plural dos Substantivos Regulares","level":"A1","module":"Everyday Objects & Belongings"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Palavras Sempre no Plural (Glasses, Clothes)","secondary":"Glasses + ARE | Pants + ARE","desc":"Algumas palavras como 'glasses' (óculos) ou 'pants' (calças) são consideradas plurais e exigem verbo no plural ('are').","context":"Where are my glasses? (NÃO 'Where is my glasses?').","audio":"Palavras Sempre no Plural (Glasses, Clothes)","level":"A1","module":"Everyday Objects & Belongings"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"There is...","secondary":"/ðeər ɪz/","desc":"Há / Existe (singular)","context":"Usado para 1 objeto ou pessoa.","audio":"There is...","level":"A1","module":"There is / There are (Existence)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"There are...","secondary":"/ðeər ɑːr/","desc":"Há / Existem (plural)","context":"Usado para 2 ou mais objetos ou pessoas.","audio":"There are...","level":"A1","module":"There is / There are (Existence)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Is there...? / Are there...?","secondary":"/ɪz ðeər / ɑːr ðeər/","desc":"Há...? / Existem...?","context":"Forma interrogativa.","audio":"Is there...? / Are there...?","level":"A1","module":"There is / There are (Existence)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Diferença Fundamental: There is vs. Have","secondary":"Existence ➔ There is / There are | Possession ➔ I have / You have","desc":"EM INGLÊS NÃO SE USA O VERBO 'HAVE' PARA INDICAR EXISTÊNCIA! O verbo 'Have' indica POSSE. Para dizer 'Há um livro', use 'THERE IS a book', nunca 'Has a book'!","context":"There is a car in the garage (Há um carro). I have a car (Eu tenho um carro).","audio":"Diferença Fundamental: There is vs. Have","level":"A1","module":"There is / There are (Existence)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Forma Negativa: There isn't / There aren't","secondary":"There isn't + singular | There aren't + plural","desc":"Para negar a existência, adicione 'not': There is not (There isn't) ou There are not (There aren't).","context":"There isn't any milk. There aren't any cars.","audio":"Forma Negativa: There isn't / There aren't","level":"A1","module":"There is / There are (Existence)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Living room / Bedroom / Bathroom","secondary":"/ˈlɪvɪŋ ruːm / ˈbedruːm / ˈbɑːθruːm/","desc":"Sala de estar / Quarto / Banheiro","context":"Cômodos principais.","audio":"Living room / Bedroom / Bathroom","level":"A1","module":"Rooms & Furniture in the House"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Kitchen / Dining room / Garden","secondary":"/ˈkɪtʃɪn / ˈdaɪnɪŋ ruːm / ˈɡɑːrdn/","desc":"Cozinha / Sala de jantar / Jardim","context":"Áreas comuns.","audio":"Kitchen / Dining room / Garden","level":"A1","module":"Rooms & Furniture in the House"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Bed / Sofa / Desk / Fridge","secondary":"/bed / ˈsoʊfə / desk / frɪdʒ/","desc":"Cama / Sofá / Escrivaninha / Geladeira","context":"Móveis e utensílios.","audio":"Bed / Sofa / Desk / Fridge","level":"A1","module":"Rooms & Furniture in the House"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbo HAVE para Cômodos (Possuir)","secondary":"My house + HAS + [cômodos]","desc":"Para descrever o que a casa possui, usamos o verbo 'Have' (para I/You/We/They) ou 'Has' (para He/She/It - inclusive 'my house').","context":"My house has three bedrooms. (Minha casa tem três quartos).","audio":"Verbo HAVE para Cômodos (Possuir)","level":"A1","module":"Rooms & Furniture in the House"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Uso de IN para Cômodos","secondary":"Object + is/are + IN + the + [cômodo]","desc":"Para dizer que algo está 'dentro' de um cômodo, usamos a preposição 'IN'.","context":"The TV is in the living room. The bed is in the bedroom.","audio":"Uso de IN para Cômodos","level":"A1","module":"Rooms & Furniture in the House"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"In / On / Under","secondary":"/ɪn / ɒn / ˈʌndər/","desc":"Dentro de / Em cima de (com contato) / Embaixo de","context":"Preposições de posição física.","audio":"In / On / Under","level":"A1","module":"Prepositions of Place (In, On, Under, Next to)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Next to / Between / Behind","secondary":"/nekst tuː / bɪˈtwiːn / bɪˈhaɪnd/","desc":"Ao lado de / Entre (dois) / Atrás de","context":"Relações de vizinhança espacial.","audio":"Next to / Between / Behind","level":"A1","module":"Prepositions of Place (In, On, Under, Next to)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"In front of","secondary":"/ɪn frʌnt əv/","desc":"Na frente de","context":"Posição frontal.","audio":"In front of","level":"A1","module":"Prepositions of Place (In, On, Under, Next to)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Diferença Crítica: IN vs. ON","secondary":"IN + espaço fechado | ON + superfície","desc":"'IN' significa dentro de um recipiente, caixa, sala ou espaço fechado. 'ON' significa em cima de uma superfície com contato físico (mesa, parede, chão).","context":"In the box (Dentro da caixa). On the table (Em cima da mesa). On the wall (Na parede).","audio":"Diferença Crítica: IN vs. ON","level":"A1","module":"Prepositions of Place (In, On, Under, Next to)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura da Pergunta de Localização: Where is / Where are","secondary":"Where is + [Objeto Singular]? | Where are + [Objetos Plurais]?","desc":"Para perguntar onde está algo, use 'Where is + singular' ou 'Where are + plural'.","context":"Where is my key? It is on the desk. Where are my shoes? They are under the bed.","audio":"Estrutura da Pergunta de Localização: Where is / Where are","level":"A1","module":"Prepositions of Place (In, On, Under, Next to)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"What time is it?","secondary":"/wɒt taɪm ɪz ɪt/","desc":"Que horas são?","context":"Pergunta padrão sobre o horário.","audio":"What time is it?","level":"A1","module":"Telling the Time"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"O'clock","secondary":"/əˈklɒk/","desc":"Em ponto (ex: 7 o'clock = 07:00)","context":"Horas exatas sem minutos.","audio":"O'clock","level":"A1","module":"Telling the Time"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Half past / Quarter past","secondary":"/hɑːf pɑːst / ˈkwɔːrtər pɑːst/","desc":"E meia (:30) / E quinze (:15)","context":"Fração de horas.","audio":"Half past / Quarter past","level":"A1","module":"Telling the Time"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura para Dizer as Horas (It is...)","secondary":"It is + [Hora] + (o'clock / minutos)","desc":"EM INGLÊS AS HORAS SÃO SEMPRE SINGULAR ('IT IS')! Nunca diga 'They are 7 hours'. Diga 'It is 7 o'clock'.","context":"It is 8:00 (It is eight o'clock). It is 8:30 (It is eight thirty / half past eight).","audio":"Estrutura para Dizer as Horas (It is...)","level":"A1","module":"Telling the Time"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Preposição AT para Horários Marcados","secondary":"AT + [Horário]","desc":"Para dizer que um evento acontece em um determinado horário, use a preposição 'AT'.","context":"The class is AT 9 o'clock. I wake up AT 7:00.","audio":"Preposição AT para Horários Marcados","level":"A1","module":"Telling the Time"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Days of the Week","secondary":"Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday","desc":"Segunda a Domingo","context":"Dias da semana (Sempre com maiúscula!).","audio":"Days of the Week","level":"A1","module":"Days of the Week & Months"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Months of the Year","secondary":"January, February, March, April, May, June...","desc":"Janeiro a Dezembro","context":"Meses do ano (Sempre com maiúscula!).","audio":"Months of the Year","level":"A1","module":"Days of the Week & Months"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"When is your birthday?","secondary":"/wen ɪz jɔːr ˈbɜːrθdeɪ/","desc":"Quando é seu aniversário?","context":"Pergunta sobre data de nascimento.","audio":"When is your birthday?","level":"A1","module":"Days of the Week & Months"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra das Preposições de Tempo: ON vs. IN","secondary":"ON + Dia/Data | IN + Mês/Ano","desc":"Use 'ON' para DIAS específicos da semana e datas completas. Use 'IN' para MESES e ANOS soltos!","context":"ON Monday. ON May 15th. | IN May. IN 2024.","audio":"Regra das Preposições de Tempo: ON vs. IN","level":"A1","module":"Days of the Week & Months"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Letra Maiúscula Obrigatória em Dias e Meses","secondary":"monday ➔ ERROR | Monday ➔ CORRECT","desc":"Em inglês, dias da semana e meses do ano são SEMPRE escritos com a PRIMEIRA LETRA MAIÚSCULA!","context":"I work on Monday. My birthday is in July.","audio":"Letra Maiúscula Obrigatória em Dias e Meses","level":"A1","module":"Days of the Week & Months"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Wake up / Get up","secondary":"/weɪk ʌp / ɡet ʌp/","desc":"Acordar / Levantar da cama","context":"Ações matinais.","audio":"Wake up / Get up","level":"A1","module":"Daily Habits & Present Simple I"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Have breakfast / Have lunch / Have dinner","secondary":"/hæv ˈbrekfəst / lʌntʃ / ˈdɪnər/","desc":"Tomar café da manhã / Almoçar / Jantar","context":"Refeições (usar o verbo 'HAVE').","audio":"Have breakfast / Have lunch / Have dinner","level":"A1","module":"Daily Habits & Present Simple I"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Go to work / Go to school / Sleep","secondary":"/ɡoʊ tuː wɜːrk / sliːp/","desc":"Ir ao trabalho / Ir à escola / Dormir","context":"Deslocamento e descanso.","audio":"Go to work / Go to school / Sleep","level":"A1","module":"Daily Habits & Present Simple I"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Present Simple com I, You, We, They (Verbo Base)","secondary":"Subject (I/You/We/They) + Verb (Base)","desc":"Para falar de hábitos no presente com I, You, We, They, usamos o verbo na sua forma base sem alterações!","context":"I wake up at 7:00. We have lunch at 12:00. They study English.","audio":"Present Simple com I, You, We, They (Verbo Base)","level":"A1","module":"Daily Habits & Present Simple I"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Negação no Present Simple: DON'T (Do not)","secondary":"Subject + DON'T + Verb (Base)","desc":"Para negar uma ação no presente com I/You/We/They, colocamos o auxiliar 'don't' antes do verbo!","context":"I don't drink coffee. They don't work on Sunday.","audio":"Negação no Present Simple: DON'T (Do not)","level":"A1","module":"Daily Habits & Present Simple I"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Works / Lives / Speaks","secondary":"/wɜːrks / lɪvz / spiːks/","desc":"Trabalha / Mora / Fala","context":"Verbos na 3ª pessoa (+S).","audio":"Works / Lives / Speaks","level":"A1","module":"Present Simple II (He/She/It -s)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Teaches / Watches / Studies","secondary":"/ˈtiːtʃɪz / ˈwɒtʃɪz / ˈstʌdiz/","desc":"Ensina (+es) / Assiste (+es) / Estuda (y➔ies)","context":"Variações ortográficas de 3ª pessoa.","audio":"Teaches / Watches / Studies","level":"A1","module":"Present Simple II (He/She/It -s)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Has (ter na 3ª pessoa)","secondary":"/hæz/","desc":"Tem (He/She/It HAS)","context":"Forma irregular de 'have'.","audio":"Has (ter na 3ª pessoa)","level":"A1","module":"Present Simple II (He/She/It -s)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Regra do 'S' para He / She / It na Afirmativa","secondary":"He/She/It + Verb + S / ES / IES","desc":"Na afirmativa do Present Simple, quando o sujeito for HE, SHE ou IT, adicione a letra 'S' ao final do verbo principal!","context":"He workS at a hospital. She liveS in London. It rainS today.","audio":"A Regra do 'S' para He / She / It na Afirmativa","level":"A1","module":"Present Simple II (He/She/It -s)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Negação na 3ª Pessoa: DOESN'T (Does not)","secondary":"He/She/It + DOESN'T + Verb (Base - Sem S!)","desc":"Para negar com He/She/It, use o auxiliar 'DOESN'T' e O VERBO VOLTA À SUA FORMA NORMAL SEM S!","context":"She doesn't work on Sunday. (NÃO 'She doesn't works').","audio":"Negação na 3ª Pessoa: DOESN'T (Does not)","level":"A1","module":"Present Simple II (He/She/It -s)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Always (100%) / Usually (80%)","secondary":"/ˈɔːlweɪz / ˈjuːʒuəli/","desc":"Sempre / Usualmente (geralmente)","context":"Alta frequência.","audio":"Always (100%) / Usually (80%)","level":"A1","module":"Adverbs of Frequency"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Sometimes (50%) / Hardly ever (10%)","secondary":"/ˈsʌmtaɪmz / ˈhɑːrdli ˈevər/","desc":"Às vezes / Quase nunca","context":"Frequência média/baixa.","audio":"Sometimes (50%) / Hardly ever (10%)","level":"A1","module":"Adverbs of Frequency"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Never (0%)","secondary":"/ˈnevər/","desc":"Nunca","context":"Frequência nula.","audio":"Never (0%)","level":"A1","module":"Adverbs of Frequency"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Posição do Advérbio com Verbos Normais","secondary":"Subject + ADVERB + Main Verb","desc":"Advérbios de frequência vêm ANTES do verbo principal da ação!","context":"I ALWAYS drink coffee. She NEVER arrives late. They SOMETIMES play tennis.","audio":"Posição do Advérbio com Verbos Normais","level":"A1","module":"Adverbs of Frequency"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Exceção: Posição do Advérbio com o Verbo TO BE","secondary":"Subject + TO BE + ADVERB","desc":"Com o verbo To Be (am, is, are), o advérbio de frequência vem DEPOIS do verbo!","context":"He IS ALWAYS happy. (NÃO 'He always is happy'). They ARE NEVER late.","audio":"Exceção: Posição do Advérbio com o Verbo TO BE","level":"A1","module":"Adverbs of Frequency"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Bread / Cheese / Butter / Egg","secondary":"/bred / tʃiːz / ˈbʌtər / eɡ/","desc":"Pão / Queijo / Manteiga / Ovo","context":"Alimentos de café da manhã.","audio":"Bread / Cheese / Butter / Egg","level":"A1","module":"Food & Drinks Vocabulary"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Water / Milk / Coffee / Tea","secondary":"/ˈwɔːtər / mɪlk / ˈkɒfi / tiː/","desc":"Água / Leite / Café / Chá","context":"Bebidas essenciais.","audio":"Water / Milk / Coffee / Tea","level":"A1","module":"Food & Drinks Vocabulary"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Chicken / Meat / Fish / Rice","secondary":"/ˈtʃɪkɪn / miːt / fɪʃ / raɪs/","desc":"Frango / Carne vermelha / Peixe / Arroz","context":"Alimentos de almoço e jantar.","audio":"Chicken / Meat / Fish / Rice","level":"A1","module":"Food & Drinks Vocabulary"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbos EAT (Comer) e DRINK (Beber)","secondary":"Eat + comida | Drink + bebida | Have + comida/bebida","desc":"Use 'Eat' para alimentos sólidos e 'Drink' para líquidos. Alternativamente, o verbo 'HAVE' pode ser usado para ambos!","context":"I eat bread. I drink water. I have breakfast (como/tomo o café).","audio":"Verbos EAT (Comer) e DRINK (Beber)","level":"A1","module":"Food & Drinks Vocabulary"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Substantivos Plurais com Alimentos (Eggs, Apples)","secondary":"Countable + S | Uncountable ➔ Sem plural em S","desc":"Alimentos contáveis ganham 'S' no plural (an egg ➔ two eggs). Alimentos incontáveis como 'bread' ou 'water' não ganham 's'!","context":"Three eggs. Two apples. Water (sem waters). Bread (sem breads).","audio":"Substantivos Plurais com Alimentos (Eggs, Apples)","level":"A1","module":"Food & Drinks Vocabulary"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Love / Like","secondary":"/lʌv / laɪk/","desc":"Amar / Gostar de","context":"Preferências positivas.","audio":"Love / Like","level":"A1","module":"Expressing Likes & Dislikes (Like / Hate)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Don't like / Hate","secondary":"/doʊnt laɪk / heɪt/","desc":"Não gostar de / Detestar (odiar)","context":"Preferências negativas.","audio":"Don't like / Hate","level":"A1","module":"Expressing Likes & Dislikes (Like / Hate)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Do you like...?","secondary":"/duː juː laɪk/","desc":"Você gosta de...?","context":"Pergunta sobre gostos.","audio":"Do you like...?","level":"A1","module":"Expressing Likes & Dislikes (Like / Hate)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra do Verbo LIKE com 3ª Pessoa (He/She/It)","secondary":"I/You/We/They + LIKE | He/She/It + LIKES","desc":"Lembre-se da regra do Present Simple! Com I/You/We/They use 'LIKE'. Com He/She/It adicione a letra S: 'LIKES'!","context":"I like chocolate. She likes chocolate. He loves ice cream.","audio":"Regra do Verbo LIKE com 3ª Pessoa (He/She/It)","level":"A1","module":"Expressing Likes & Dislikes (Like / Hate)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntas com DO / DOES + LIKE","secondary":"DO + You + LIKE...? | DOES + She + LIKE...?","desc":"Para perguntar se alguém gosta de algo, inicie com 'Do' (para I/You/We/They) ou 'Does' (para He/She/It).","context":"Do you like pizza? ➔ Yes, I do. Does she like coffee? ➔ Yes, she does.","audio":"Perguntas com DO / DOES + LIKE","level":"A1","module":"Expressing Likes & Dislikes (Like / Hate)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"How much is this?","secondary":"/haʊ mʌtʃ ɪz ðɪs/","desc":"Quanto custa isto? (Singular)","context":"Pergunta de preço no singular.","audio":"How much is this?","level":"A1","module":"Asking for Prices & Money (How much?)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"How much are these?","secondary":"/haʊ mʌtʃ ɑːr ðiːz/","desc":"Quanto custam estes? (Plural)","context":"Pergunta de preço no plural.","audio":"How much are these?","level":"A1","module":"Asking for Prices & Money (How much?)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Dollars / Cents / Euros / Pounds","secondary":"/ˈdɒlərz / sents/","desc":"Dólares / Centavos / Euros / Libras","context":"Moedas internacionais.","audio":"Dollars / Cents / Euros / Pounds","level":"A1","module":"Asking for Prices & Money (How much?)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura de Preços: How much IS vs. How much ARE","secondary":"How much IS + singular | How much ARE + plural","desc":"Use 'How much IS' para 1 objeto no singular. Use 'How much ARE' para 2 ou mais objetos ou palavras no plural (ex: shoes).","context":"How much is this book? It is $10. How much are these shoes? They are $50.","audio":"Estrutura de Preços: How much IS vs. How much ARE","level":"A1","module":"Asking for Prices & Money (How much?)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Respostas de Preço com IT IS / THEY ARE","secondary":"Singular ➔ It is $X | Plural ➔ They are $X","desc":"Responda com 'It is...' para singular e 'They are...' para plural.","context":"It is 15 dollars. They are 40 euros.","audio":"Respostas de Preço com IT IS / THEY ARE","level":"A1","module":"Asking for Prices & Money (How much?)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Can I have...?","secondary":"/kæn aɪ hæv/","desc":"Você pode me ver...? / Eu gostaria de...","context":"Expressão mais usada para pedir em restaurantes.","audio":"Can I have...?","level":"A1","module":"Ordering in a Restaurant (Can I have...?)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I would like... (I'd like)","secondary":"/aɪ wʊd laɪk/","desc":"Eu gostaria de...","context":"Pedido formal e educado.","audio":"I would like... (I'd like)","level":"A1","module":"Ordering in a Restaurant (Can I have...?)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Menu / Bill (Check) / Tip","secondary":"/ˈmenjuː / bɪl / tɪp/","desc":"Cardápio / Conta / Gorjeta","context":"Elementos de um restaurante.","audio":"Menu / Bill (Check) / Tip","level":"A1","module":"Ordering in a Restaurant (Can I have...?)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fazendo Pedidos Educados: Can I have vs. Give me","secondary":"Can I have + [Item] + please? | I'd like + [Item]","desc":"Em inglês, NUNCA diga 'Give me a coffee' (Me dá um café) pois soa agressivo! Use SEMPRE 'Can I have a coffee, please?' ou 'I'd like a coffee'.","context":"Can I have a cheese pizza, please? I'd like an orange juice.","audio":"Fazendo Pedidos Educados: Can I have vs. Give me","level":"A1","module":"Ordering in a Restaurant (Can I have...?)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pedindo a Conta: Can I have the bill/check?","secondary":"Can I have the bill/check, please?","desc":"No Reino Unido diz-se 'bill', nos EUA diz-se 'check'.","context":"Excuse me, can I have the check, please?","audio":"Pedindo a Conta: Can I have the bill/check?","level":"A1","module":"Ordering in a Restaurant (Can I have...?)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Countable (Apples, Eggs, Books)","secondary":"/ˈkaʊntəbəl/","desc":"Contáveis (podem ser contados por unidade: 1, 2, 3...)","context":"Aceitam plural em S.","audio":"Countable (Apples, Eggs, Books)","level":"A1","module":"Countable & Uncountable Nouns (Some / Any)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Uncountable (Water, Milk, Rice, Money)","secondary":"/ʌnˈkaʊntəbəl/","desc":"Incontáveis (Líquidos, grãos, dinheiro)","context":"NÃO aceitam plural em S.","audio":"Uncountable (Water, Milk, Rice, Money)","level":"A1","module":"Countable & Uncountable Nouns (Some / Any)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Some vs. Any","secondary":"/sʌm / ˈeni/","desc":"Algum(a/s) / Nenhum(a) ou Algum(a)?","context":"Quantificadores.","audio":"Some vs. Any","level":"A1","module":"Countable & Uncountable Nouns (Some / Any)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra do SOME (Afirmativas)","secondary":"Afirmativa ➔ SOME","desc":"Use 'SOME' em frases AFIRMATIVAS antes de substantivos plurais contáveis ou incontáveis.","context":"I have some apples. I want some water.","audio":"Regra do SOME (Afirmativas)","level":"A1","module":"Countable & Uncountable Nouns (Some / Any)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra do ANY (Negações e Perguntas)","secondary":"Negação / Pergunta ➔ ANY","desc":"Use 'ANY' em frases NEGATIVAS (significando 'nenhum/a') e em PERGUNTAS (significando 'algum/a').","context":"I don't have any money. Is there any milk in the fridge?","audio":"Regra do ANY (Negações e Perguntas)","level":"A1","module":"Countable & Uncountable Nouns (Some / Any)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Bank / Supermarket / Pharmacy","secondary":"/bæŋk / ˈsuːpərmɑːrkɪt / ˈfɑːrməsi/","desc":"Banco / Supermercado / Farmácia","context":"Serviços essenciais.","audio":"Bank / Supermarket / Pharmacy","level":"A1","module":"Places in the City"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Airport / Train station / Bus stop","secondary":"/ˈeərpɔːrt / treɪn ˈsteɪʃn / bʌs stɒp/","desc":"Aeroporto / Estação de trem / Ponto de ônibus","context":"Locais de transporte.","audio":"Airport / Train station / Bus stop","level":"A1","module":"Places in the City"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Hotel / Restaurant / Park / Hospital","secondary":"/hoʊˈtel / ˈrestrɒnt / pɑːrk / ˈhɒspɪtl/","desc":"Hotel / Restaurante / Parque / Hospital","context":"Locais públicos.","audio":"Hotel / Restaurant / Park / Hospital","level":"A1","module":"Places in the City"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Preposição AT para Locais Específicos","secondary":"AT + the + [Local]","desc":"Para dizer que você está em um determinado estabelecimento ou local público da cidade, use a preposição 'AT'.","context":"I am AT the airport. She is AT the bank. They are AT the restaurant.","audio":"Preposição AT para Locais Específicos","level":"A1","module":"Places in the City"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbo GO TO (Ir para)","secondary":"Subject + GO TO + the + [Local]","desc":"Para indicar deslocamento até um local da cidade, usamos o verbo 'Go to' (ou 'goes to' na 3ª pessoa).","context":"I go to the supermarket on Saturdays. He goes to the bank.","audio":"Verbo GO TO (Ir para)","level":"A1","module":"Places in the City"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"By bus / By car / By train","secondary":"/baɪ bʌs / baɪ kɑːr / baɪ treɪn/","desc":"De ônibus / De carro / De trem","context":"Transportes terrestres.","audio":"By bus / By car / By train","level":"A1","module":"Means of Transportation & 'By'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"By plane / By subway / By taxi","secondary":"/baɪ pleɪn / baɪ ˈsʌbweɪ / baɪ ˈtæksi/","desc":"De avião / De metrô / De táxi","context":"Transportes aéreos e urbanos.","audio":"By plane / By subway / By taxi","level":"A1","module":"Means of Transportation & 'By'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"On foot (A pé)","secondary":"/ɒn fʊt/","desc":"A pé (caminhando)","context":"A EXCEÇÃO OBRIGATÓRIA (NUNCA 'by foot')!","audio":"On foot (A pé)","level":"A1","module":"Means of Transportation & 'By'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra da Preposição BY para Transportes","secondary":"BY + [Veículo] (by car, by bus, by train)","desc":"Para indicar o MEIO de transporte que você utiliza, use SEMPRE a preposição 'BY' diretamente antes do veículo (sem artigo!).","context":"I go to work BY bus. She travels BY plane.","audio":"Regra da Preposição BY para Transportes","level":"A1","module":"Means of Transportation & 'By'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Exceção Obrigatória: ON FOOT (A pé)","secondary":"ON FOOT (exclusivo para ir a pé)","desc":"NUNCA DIGA 'by foot'! Para dizer que você vai a pé/caminhando, a única forma correta é 'ON FOOT'.","context":"I go to school ON FOOT. (NÃO 'by foot').","audio":"Exceção Obrigatória: ON FOOT (A pé)","level":"A1","module":"Means of Transportation & 'By'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Turn left / Turn right","secondary":"/tɜːrn left / tɜːrn raɪt/","desc":"Vire à esquerda / Vire à direita","context":"Mudança de direção.","audio":"Turn left / Turn right","level":"A1","module":"Asking for Directions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Go straight / Go straight ahead","secondary":"/ɡoʊ streɪt əˈhed/","desc":"Siga em frente / Siga reto","context":"Manter trajetória.","audio":"Go straight / Go straight ahead","level":"A1","module":"Asking for Directions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"On the corner / Across from","secondary":"/ɒn ðə ˈkɔːrnər / əˈkrɒs frɒm/","desc":"Na esquina / Do outro lado da rua de","context":"Pontos de referência.","audio":"On the corner / Across from","level":"A1","module":"Asking for Directions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura para Pedir Direções: Excuse me, where is...?","secondary":"Excuse me, where is + the + [Local]?","desc":"Sempre inicie com 'Excuse me' para ser cortês antes de pedir a localização.","context":"Excuse me, where is the train station?","audio":"Estrutura para Pedir Direções: Excuse me, where is...?","level":"A1","module":"Asking for Directions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbos no Imperativo para dar Direções","secondary":"Verb + Direction (Turn left / Go straight / Cross the street)","desc":"Para dar instruções de caminho, use o verbo diretamente na forma imperativa (sem sujeito!).","context":"Turn left on Main Street. Go straight for two blocks.","audio":"Verbos no Imperativo para dar Direções","level":"A1","module":"Asking for Directions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I can... / I can't...","secondary":"/aɪ kæn / aɪ kænt/","desc":"Eu posso/consigo... / Eu não posso/consigo...","context":"Expressar capacidade/habilidade.","audio":"I can... / I can't...","level":"A1","module":"Abilities & Requests (Can / Can't)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Speak English / Drive / Swim","secondary":"/spiːk ˈɪŋɡlɪʃ / draɪv / swɪm/","desc":"Falar inglês / Dirigir / Nadar","context":"Habilidades comuns.","audio":"Speak English / Drive / Swim","level":"A1","module":"Abilities & Requests (Can / Can't)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Can you help me?","secondary":"/kæn juː help miː/","desc":"Você pode me ajudar?","context":"Pedido de ajuda.","audio":"Can you help me?","level":"A1","module":"Abilities & Requests (Can / Can't)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Verbo Modal CAN (Invariável)","secondary":"Subject + CAN + Verb (Base)","desc":"O verbo CAN NUNCA MUDA! Não ganha 'S' na 3ª pessoa (He can, She can) e o verbo seguinte fica na forma base sem 'to'!","context":"He can speak English. (NÃO 'He cans speak' nem 'He can to speak').","audio":"O Verbo Modal CAN (Invariável)","level":"A1","module":"Abilities & Requests (Can / Can't)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Negação CAN'T (Cannot) e Perguntas com CAN","secondary":"Negação ➔ Subject + CAN'T + Verb | Pergunta ➔ CAN + Subject + Verb?","desc":"A negação é 'can't'. Nas perguntas, inverte-se a ordem colocando 'Can' no início.","context":"She can't swim. Can you drive?","audio":"Negação CAN'T (Cannot) e Perguntas com CAN","level":"A1","module":"Abilities & Requests (Can / Can't)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Passport & Boarding pass","secondary":"/ˈpɑːspɔːrt & ˈbɔːrdɪŋ pɑːs/","desc":"Passaporte e Cartão de embarque","context":"Documentos de viagem.","audio":"Passport & Boarding pass","level":"A1","module":"🏆 A1 Final Challenge: The Airport & Hotel Simulation"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Reservation / Single room / Double room","secondary":"/ˌrezərˈveɪʃn/","desc":"Reserva / Quarto de solteiro / Quarto de casal","context":"Vocabulário de hotel.","audio":"Reservation / Single room / Double room","level":"A1","module":"🏆 A1 Final Challenge: The Airport & Hotel Simulation"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Have a nice stay!","secondary":"/hæv ə naɪs steɪ/","desc":"Tenha uma boa estadia!","context":"Desejo de boas-vindas no hotel.","audio":"Have a nice stay!","level":"A1","module":"🏆 A1 Final Challenge: The Airport & Hotel Simulation"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Revisão Geral A1: To Be vs. Present Simple","secondary":"State ➔ To Be | Action ➔ Verb","desc":"To Be (am/is/are) descreve QUEM você é, ONDE você está e COMO você está. Present Simple (verbo de ação) descreve o que você FAZ!","context":"I am a tourist (To Be). I speak English and I want a coffee (Action).","audio":"Revisão Geral A1: To Be vs. Present Simple","level":"A1","module":"🏆 A1 Final Challenge: The Airport & Hotel Simulation"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Check-in de Hotel: Expressões Chave","secondary":"I have a reservation under [Name]","desc":"Para fazer o check-in: 'I have a reservation under the name of...'","context":"I have a reservation under the name of Carlos Silva.","audio":"Check-in de Hotel: Expressões Chave","level":"A1","module":"🏆 A1 Final Challenge: The Airport & Hotel Simulation"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Wake up / Get up","secondary":"/weɪk ʌp / ɡet ʌp/","desc":"Acordar / Levantar-se da cama","context":"Primeira ação do dia.","audio":"Wake up / Get up","level":"A2","module":"Everyday Routines & Present Simple Review"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Brush my teeth","secondary":"/brʌʃ maɪ tiːθ/","desc":"Escovar os dentes","context":"Higiene matinal e noturna.","audio":"Brush my teeth","level":"A2","module":"Everyday Routines & Present Simple Review"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Take a shower / Have a shower","secondary":"/teɪk ə ˈʃaʊər/","desc":"Tomar banho","context":"Higiene pessoal.","audio":"Take a shower / Have a shower","level":"A2","module":"Everyday Routines & Present Simple Review"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Get dressed","secondary":"/ɡet drest/","desc":"Vestir-se / Trocar de roupa","context":"Preparar-se para o dia.","audio":"Get dressed","level":"A2","module":"Everyday Routines & Present Simple Review"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Present Simple: Terceira Pessoa (He/She/It)","secondary":"He/She/It + Verbo(-s/-es) | Negativa: does not (doesn't) + Verbo base","desc":"Na 3ª pessoa do singular (He/She/It), adiciona-se '-s', '-es' ou '-ies' ao verbo na forma afirmativa. Verbos terminados em -ch, -sh, -ss, -x, -z, -o recebem '-es'.","context":"She wakes up at 7 AM. He doesn't take a shower in the evening.","audio":"Present Simple: Terceira Pessoa (He/She/It)","level":"A2","module":"Everyday Routines & Present Simple Review"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Conectores de Sequência Temporal","secondary":"First, [Ação 1]. Then, [Ação 2]. Finally, [Ação 3].","desc":"Para descrever a ordem da rotina, usam-se conectores como 'First' (Primeiro), 'Then / After that' (Depois), 'Finally' (Finalmente).","context":"First, I wake up. Then, I brush my teeth. Finally, I have breakfast.","audio":"Conectores de Sequência Temporal","level":"A2","module":"Everyday Routines & Present Simple Review"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Once / Twice / Three times","secondary":"/wʌns / twaɪs / θriː taɪmz/","desc":"Uma vez / Duas vezes / Três vezes","context":"Frequência numérica exata.","audio":"Once / Twice / Three times","level":"A2","module":"Adverbs & Expressions of Frequency"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Hardly ever / Seldom","secondary":"/ˈhɑːrdli ˈevər / ˈseldəm/","desc":"Quase nunca / Raramente","context":"Frequência baixa (~5-10%).","audio":"Hardly ever / Seldom","level":"A2","module":"Adverbs & Expressions of Frequency"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Every day / Every week / Every month","secondary":"/ˈevri deɪ/","desc":"Todo dia / Toda semana / Todo mês","context":"Frequência regular periódica.","audio":"Every day / Every week / Every month","level":"A2","module":"Adverbs & Expressions of Frequency"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Posição dos Advérbios de Frequência","secondary":"Subject + Advérbio + Verbo Principal | Subject + To Be + Advérbio","desc":"Advérbios de frequência (always, usually, often, sometimes, hardly ever, never) ficam ANTES do verbo principal, mas DEPOIS do verbo To Be.","context":"I ALWAYS drink coffee. She IS NEVER late for class.","audio":"Posição dos Advérbios de Frequência","level":"A2","module":"Adverbs & Expressions of Frequency"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressões de Frequência com 'A' (Once a week, Twice a month)","secondary":"Once/Twice/Three times + a + day/week/month/year","desc":"Usamos 'once' (1x), 'twice' (2x) e '[número] times' seguidos de 'a + período de tempo' para indicar repetição regular.","context":"I workout three times a week. We travel twice a year.","audio":"Expressões de Frequência com 'A' (Once a week, Twice a month)","level":"A2","module":"Adverbs & Expressions of Frequency"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Enjoy / Love / Hate","secondary":"/ɪnˈdʒɔɪ / lʌv / heɪt/","desc":"Apreciar, Gostar de / Amar / Odiar","context":"Verbos de preferência pessoal.","audio":"Enjoy / Love / Hate","level":"A2","module":"Free Time & Hobbies"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Playing video games / Reading books","secondary":"/ˈpleɪ.ɪŋ ˈvɪd.i.oʊ ɡeɪmz/","desc":"Jogar videogame / Ler livros","context":"Atividades de lazer comuns.","audio":"Playing video games / Reading books","level":"A2","module":"Free Time & Hobbies"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Watching movies / Going out with friends","secondary":"/ˈwɒtʃɪŋ ˈmuːviz/","desc":"Assistir filmes / Sair com amigos","context":"Passatempos sociais e relaxantes.","audio":"Watching movies / Going out with friends","level":"A2","module":"Free Time & Hobbies"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbos de Gosto + Gerúndio (-ing)","secondary":"Subject + like / enjoy / love / hate + Verb(-ing)","desc":"Após os verbos de sentimento/gosto (like, enjoy, love, hate, don't mind), o verbo seguinte costuma ser usado no gerúndio (com final '-ing').","context":"I ENJOY PLAYING basketball. She HATES DOING homework.","audio":"Verbos de Gosto + Gerúndio (-ing)","level":"A2","module":"Free Time & Hobbies"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Gerúndio (-ing) vs. Infinitivo (to + verbo)","secondary":"Enjoy + V(-ing) [NUNCA enjoy + to V]","desc":"Com 'like' e 'love', você pode usar -ing ou infinitivo (ex: 'I like reading' ou 'I like to read'). Porém, após 'ENJOY' e 'DON'T MIND', usa-se EXCLUSIVAMENTE a forma com -ing!","context":"I enjoy watching series. (CORRETO) | I enjoy to watch series. (INCORRETO)","audio":"Gerúndio (-ing) vs. Infinitivo (to + verbo)","level":"A2","module":"Free Time & Hobbies"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Attend meetings / Write emails","secondary":"/əˈtend ˈmiːtɪŋz/","desc":"Participar de reuniões / Escrever e-mails","context":"Tarefas de escritório.","audio":"Attend meetings / Write emails","level":"A2","module":"Jobs, Workplace & Daily Tasks"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Manage projects / Answer phone calls","secondary":"/ˈmænɪdʒ ˈprɒdʒekts/","desc":"Gerenciar projetos / Atender chamadas","context":"Responsabilidades de trabalho.","audio":"Manage projects / Answer phone calls","level":"A2","module":"Jobs, Workplace & Daily Tasks"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Workplace / Office / Factory","secondary":"/ˈwɜːrkpleɪs / ˈɒfɪs/","desc":"Local de trabalho / Escritório / Fábrica","context":"Locais de trabalho.","audio":"Workplace / Office / Factory","level":"A2","module":"Jobs, Workplace & Daily Tasks"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntas de Trabalho com 'What do you do?'","secondary":"What + do/does + Subject + do at work?","desc":"Para perguntar a rotina de trabalho específica, usamos 'What do you do at work?' ou 'What are your daily responsibilities?'.","context":"What does she do at work? ➔ She manages a team.","audio":"Perguntas de Trabalho com 'What do you do?'","level":"A2","module":"Jobs, Workplace & Daily Tasks"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Uso da Preposição 'FOR' e 'IN' para Emprego","secondary":"Work for [Company] | Work in [Department/Field]","desc":"Usamos 'work FOR + nome da empresa/pessoa' e 'work IN + setor/cidade/local'.","context":"I work FOR Google. She works IN IT / IN sales.","audio":"Uso da Preposição 'FOR' e 'IN' para Emprego","level":"A2","module":"Jobs, Workplace & Daily Tasks"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Don't you? / Doesn't he?","secondary":"/doʊnt juː / dʌzənt hiː/","desc":"Não é? / Não mora? (Question tags)","context":"Confirmação no final da frase.","audio":"Don't you? / Doesn't he?","level":"A2","module":"Habits & Free Time Grammar Review"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"On weekdays / On weekends","secondary":"/ɒn ˈwiːkdeɪz/","desc":"Nos dias úteis / Nos fins de semana","context":"Expressões de tempo habitual.","audio":"On weekdays / On weekends","level":"A2","module":"Habits & Free Time Grammar Review"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Question Tags com Present Simple (do/does)","secondary":"[Frase Afirmativa], + don't / doesn't + Subject?","desc":"Question tags são pequenas perguntas no final da frase para pedir confirmação. Se a frase for AFIRMATIVA, a tag será NEGATIVA usando don't/doesn't.","context":"You work here, DON'T YOU? | She likes tea, DOESN'T SHE?","audio":"Question Tags com Present Simple (do/does)","level":"A2","module":"Habits & Free Time Grammar Review"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Question Tags com Frase Negativa","secondary":"[Frase Negativa], + do / does + Subject?","desc":"Se a frase principal for NEGATIVA, a question tag será AFIRMATIVA usando do/does.","context":"You don't smoke, DO YOU? | He doesn't drive, DOES HE?","audio":"Question Tags com Frase Negativa","level":"A2","module":"Habits & Free Time Grammar Review"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Worked / Played / Visited","secondary":"/wɜːrkt / pleɪd / ˈvɪzɪtɪd/","desc":"Trabalhei / Joguei / Visitei","context":"Verbos regulares no passado.","audio":"Worked / Played / Visited","level":"A2","module":"Regular Verbs in Past Simple (-ed)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Yesterday / Last night / Last week","secondary":"/ˈjestərdeɪ/","desc":"Ontem / Ontem à noite / Semana passada","context":"Marcadores de tempo passado.","audio":"Yesterday / Last night / Last week","level":"A2","module":"Regular Verbs in Past Simple (-ed)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra Geral do Past Simple para Verbos Regulares","secondary":"Subject + Verbo(-ed) + Complemento","desc":"Para formar o passado de verbos regulares na afirmativa, adiciona-se '-ed' ao verbo base. Se o verbo termina em -e, adiciona-se apenas '-d'. Se termina em consoante + y, troca-se por '-ied'.","context":"I work ➔ I worked | She live ➔ She lived | They study ➔ They studied","audio":"Regra Geral do Past Simple para Verbos Regulares","level":"A2","module":"Regular Verbs in Past Simple (-ed)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pronúncia do sufixo -ED (/t/, /d/, /ɪd/)","secondary":"Terminados em T/D ➔ Pronúncia /ɪd/ (ex: decided, started)","desc":"O som '/ɪd/' (com sílaba extra) só ocorre quando o verbo base termina em som de T ou D! Ex: visited, wanted, needed.","context":"Worked (/t/) | Played (/d/) | Visited (/ɪd/ - pronuncia o 'e')","audio":"Pronúncia do sufixo -ED (/t/, /d/, /ɪd/)","level":"A2","module":"Regular Verbs in Past Simple (-ed)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Go ➔ Went | Eat ➔ Ate","secondary":"/went / eɪt/","desc":"Ir ➔ Foi/Fui | Comer ➔ Comeu/Comi","context":"Verbos irregulares essenciais.","audio":"Go ➔ Went | Eat ➔ Ate","level":"A2","module":"Irregular Verbs in Past Simple"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Buy ➔ Bought | See ➔ Saw","secondary":"/bɔːt / sɔː/","desc":"Comprar ➔ Comprou | Ver ➔ Viu","context":"Verbos de ação no passado.","audio":"Buy ➔ Bought | See ➔ Saw","level":"A2","module":"Irregular Verbs in Past Simple"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Have ➔ Had | Take ➔ Took","secondary":"/hæd / tʊk/","desc":"Ter ➔ Teve/Tinha | Pegar/Tirar ➔ Pego/Tirou","context":"Possessão e ação no passado.","audio":"Have ➔ Had | Take ➔ Took","level":"A2","module":"Irregular Verbs in Past Simple"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Verbos Irregulares no Afirmativo","secondary":"Subject + Verbo Irregular (Past Simple)","desc":"Verbos irregulares NÃO seguem a regra do '-ed'. Cada verbo possui uma forma própria no Past Simple que precisa ser memorizada.","context":"Go ➔ WENT | Eat ➔ ATE | Buy ➔ BOUGHT | Have ➔ HAD","audio":"Verbos Irregulares no Afirmativo","level":"A2","module":"Irregular Verbs in Past Simple"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pegadinha Comum: Sem '-ed' nos Irregulares!","secondary":"Incorreto: goed, eated, buyed | Correto: went, ate, bought","desc":"NUNCA adicione '-ed' a um verbo irregular no passado. 'Goed' ou 'eated' são erros graves!","context":"I WENT to London. (NÃO 'I goed to London').","audio":"Pegadinha Comum: Sem '-ed' nos Irregulares!","level":"A2","module":"Irregular Verbs in Past Simple"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Did you...? / I didn't...","secondary":"/dɪd juː / aɪ dɪdnt/","desc":"Você...? / Eu não...","context":"Perguntas e negativas no passado.","audio":"Did you...? / I didn't...","level":"A2","module":"Past Simple Questions & Negatives"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Stay home / Go out","secondary":"/steɪ hoʊm / ɡoʊ aʊt/","desc":"Ficar em casa / Sair","context":"Ações de fim de semana.","audio":"Stay home / Go out","level":"A2","module":"Past Simple Questions & Negatives"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra Fundamental do Auxiliar DID / DIDN'T","secondary":"Negativa: Subject + didn't + Verbo BASE | Pergunta: Did + Subject + Verbo BASE?","desc":"Quando usamos DID (perguntas) ou DIDN'T (negativas), o verbo principal VOLTA PARA A FORMA BASE (sem -ed e sem forma irregular)!","context":"I DIDN'T GO to work. (NÃO 'didn't went'). DID YOU SEE the film? (NÃO 'Did you saw').","audio":"Regra Fundamental do Auxiliar DID / DIDN'T","level":"A2","module":"Past Simple Questions & Negatives"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Respostas Curtas no Past Simple","secondary":"Yes, [Subject] + did. | No, [Subject] + didn't.","desc":"Para responder perguntas do tipo Yes/No no passado, usamos 'Yes, I did' ou 'No, I didn't'.","context":"Did you study? ➔ Yes, I did. / No, I didn't.","audio":"Respostas Curtas no Past Simple","level":"A2","module":"Past Simple Questions & Negatives"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Travel to / Stay at a hotel / Visit landmarks","secondary":"/ˈtrævl tuː / steɪ æt / ˈlændmɑːrks/","desc":"Viajar para / Ficar num hotel / Visitar pontos turísticos","context":"Vocabulário de férias.","audio":"Travel to / Stay at a hotel / Visit landmarks","level":"A2","module":"Travel Memories & Vacations"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Flight / Souvenirs / Beach resort","secondary":"/flaɪt / ˌsuːvəˈnɪərz / biːtʃ rɪˈzɔːrt/","desc":"Voo / Lembrancinhas / Resort de praia","context":"Elementos de viagem.","audio":"Flight / Souvenirs / Beach resort","level":"A2","module":"Travel Memories & Vacations"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntas de Viagem com Wh- Words no Past Simple","secondary":"Wh- Word + did + Subject + Verb (base)?","desc":"Para perguntar detalhes de viagens passadas, usam-se as Wh- words (Where, When, How, Who) seguidas de DID + Sujeito + Verbo base.","context":"WHERE did you go? | WHEN did you arrive? | HOW did you travel?","audio":"Perguntas de Viagem com Wh- Words no Past Simple","level":"A2","module":"Travel Memories & Vacations"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Duração com FOR e AGO","secondary":"For + período de tempo | [Tempo] + ago","desc":"Usamos 'FOR' para duração (ex: for 2 weeks) e 'AGO' para indicar quanto tempo atrás a viagem aconteceu (ex: 3 months ago).","context":"I stayed in Rome FOR ten days. I visited Paris two years AGO.","audio":"Expressando Duração com FOR e AGO","level":"A2","module":"Travel Memories & Vacations"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Was / Were sleeping","secondary":"/wɒz / wɜːr ˈsliːpɪŋ/","desc":"Estava / Estavam dormindo","context":"Ação contínua no passado.","audio":"Was / Were sleeping","level":"A2","module":"Past Continuous vs. Past Simple"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"When / While","secondary":"/wen / waɪl/","desc":"Quando (ação pontual) / Enquanto (ação contínua)","context":"Conectores de histórias no passado.","audio":"When / While","level":"A2","module":"Past Continuous vs. Past Simple"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura do Past Continuous (Was/Were + V-ing)","secondary":"Subject + was/were + Verb(-ing)","desc":"Usamos Was (para I, He, She, It) ou Were (para You, We, They) seguidos de verbo com '-ing' para descrever ações que estavam acontecendo em um momento do passado.","context":"I WAS STUDYING at 8 PM. They WERE PLAYING football.","audio":"Estrutura do Past Continuous (Was/Were + V-ing)","level":"A2","module":"Past Continuous vs. Past Simple"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Combinação: Past Continuous + Past Simple (WHEN vs. WHILE)","secondary":"[Ação longa: Past Continuous] + WHEN + [Ação curta: Past Simple] | WHILE + [Past Continuous], [Past Simple]","desc":"Usamos o Past Continuous para a ação longa em andamento e o Past Simple para a ação curta que a interrompe. Geralmente usamos 'WHEN' antes do Past Simple e 'WHILE' antes do Past Continuous.","context":"I was sleeping WHEN the phone rang. | WHILE I was cooking, he arrived.","audio":"Combinação: Past Continuous + Past Simple (WHEN vs. WHILE)","level":"A2","module":"Past Continuous vs. Past Simple"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Bigger / Faster / Taller","secondary":"/ˈbɪɡər / ˈfæstər / ˈtɔːlər/","desc":"Maior / Mais rápido / Mais alto","context":"Comparativos de adjetivos curtos.","audio":"Bigger / Faster / Taller","level":"A2","module":"Comparative Adjectives"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"More expensive / More comfortable","secondary":"/mɔːr ɪkˈspensɪv/","desc":"Mais caro / Mais confortável","context":"Comparativos de adjetivos longos.","audio":"More expensive / More comfortable","level":"A2","module":"Comparative Adjectives"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra dos Adjetivos Curtos (-er + than)","secondary":"Adjetivo Curto + er + THAN","desc":"Para adjetivos curtos (1 sílaba), adicione '-er' ao adjetivo seguido da palavra 'than' (do que). Se terminar em CVC (consoante-vogal-consoante), dobre a última consoante antes de -er.","context":"Fast ➔ FAST-ER than | Big ➔ BIGG-ER than | Small ➔ SMALL-ER than","audio":"Regra dos Adjetivos Curtos (-er + than)","level":"A2","module":"Comparative Adjectives"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra dos Adjetivos Longos (more + adjetivo + than)","secondary":"MORE + Adjetivo Longo + THAN","desc":"Para adjetivos longos (2 ou mais sílabas, exceto os terminados em -y), coloque 'MORE' antes do adjetivo e 'THAN' depois.","context":"Expensive ➔ MORE expensive THAN | Beautiful ➔ MORE beautiful THAN","audio":"Regra dos Adjetivos Longos (more + adjetivo + than)","level":"A2","module":"Comparative Adjectives"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Comparativos Irregulares (Good, Bad, Far)","secondary":"Good ➔ better than | Bad ➔ worse than","desc":"Alguns adjetivos são irregulares e mudam completamente no comparativo: Good ➔ BETTER than | Bad ➔ WORSE than | Far ➔ FARTHER/FURTHER than.","context":"This car is BETTER than that one. My results were WORSE than yours.","audio":"Comparativos Irregulares (Good, Bad, Far)","level":"A2","module":"Comparative Adjectives"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"The biggest / The fastest / The tallest","secondary":"/ðə ˈbɪɡɪst / ˈfæstɪst/","desc":"O maior / O mais rápido / O mais alto","context":"Superlativos de adjetivos curtos.","audio":"The biggest / The fastest / The tallest","level":"A2","module":"Superlative Adjectives"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"The most popular / The most expensive","secondary":"/ðə moʊst ˈpɒpjələr/","desc":"O mais popular / O mais caro","context":"Superlativos de adjetivos longos.","audio":"The most popular / The most expensive","level":"A2","module":"Superlative Adjectives"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra dos Superlativos Curtos (THE + adjetivo + -est)","secondary":"THE + Adjetivo Curto + est","desc":"Para adjetivos curtos (1 sílaba), coloca-se a palavra 'THE' antes e adiciona-se '-est' ao final do adjetivo.","context":"Tall ➔ THE TALL-EST | High ➔ THE HIGH-EST | Fast ➔ THE FAST-EST","audio":"Regra dos Superlativos Curtos (THE + adjetivo + -est)","level":"A2","module":"Superlative Adjectives"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra dos Superlativos Longos (THE MOST + adjetivo)","secondary":"THE MOST + Adjetivo Longo","desc":"Para adjetivos longos (2 ou mais sílabas), coloca-se 'THE MOST' antes do adjetivo sem alterar sua terminação.","context":"Famous ➔ THE MOST famous | Popular ➔ THE MOST popular","audio":"Regra dos Superlativos Longos (THE MOST + adjetivo)","level":"A2","module":"Superlative Adjectives"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Superlativos Irregulares (Best, Worst, Farthest)","secondary":"Good ➔ THE BEST | Bad ➔ THE WORST","desc":"Os adjetivos irregulares no superlativo são: Good ➔ THE BEST | Bad ➔ THE WORST | Far ➔ THE FARTHEST / FURTHEST.","context":"He is THE BEST player in the team. That was THE WORST day of my life.","audio":"Superlativos Irregulares (Best, Worst, Farthest)","level":"A2","module":"Superlative Adjectives"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I think that... / In my opinion...","secondary":"/aɪ θɪŋk ðæt / ɪn maɪ əˈpɪnjən/","desc":"Eu acho que... / Na minha opinião...","context":"Introdução de opinião.","audio":"I think that... / In my opinion...","level":"A2","module":"Expressing Opinions & Agreement"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I agree / I disagree","secondary":"/aɪ əˈɡriː / ˌdɪsəˈɡriː/","desc":"Eu concordo / Eu discordo","context":"Expressar concordância.","audio":"I agree / I disagree","level":"A2","module":"Expressing Opinions & Agreement"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"CUIDADO: NUNCA diga 'I am agree'!","secondary":"CORRETO: I agree / I disagree | INCORRETO: I am agree / I am disagree","desc":"O verbo 'agree' (concordar) e 'disagree' (discordar) são VERBOS NORMAIS em inglês. NUNCA coloque o verbo To Be (am/is/are) antes deles!","context":"I agree with your idea. (NÃO 'I am agree with your idea').","audio":"CUIDADO: NUNCA diga 'I am agree'!","level":"A2","module":"Expressing Opinions & Agreement"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Discordância Educada em Inglês","secondary":"I see your point, BUT... | I don't think so","desc":"Para discordar de forma educada e cortês, usam-se estruturas suaves como: 'I'm afraid I disagree', 'I see your point, but...', ou 'I don't think so'.","context":"I see your point, but living in a big city is very stressful.","audio":"Discordância Educada em Inglês","level":"A2","module":"Expressing Opinions & Agreement"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Prefer ... to ...","secondary":"/prɪˈfɜːr tuː/","desc":"Preferir [algo] a [outro algo]","context":"Preposição correta com 'prefer'.","audio":"Prefer ... to ...","level":"A2","module":"Preferences with 'Prefer' & 'Would Rather'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Would rather ('d rather)","secondary":"/wʊd ˈræðər/","desc":"Preferiria / Preferia (no momento)","context":"Escolha específica imediata.","audio":"Would rather ('d rather)","level":"A2","module":"Preferences with 'Prefer' & 'Would Rather'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura do Verbo PREFER (Prefer ... TO ...)","secondary":"Subject + prefer + [Coisa A] + TO + [Coisa B]","desc":"Em inglês, quando comparamos duas coisas com o verbo 'prefer', usamos a preposição 'TO' e NUNCA 'than'!","context":"I prefer tea TO coffee. (NÃO 'prefer tea than coffee'). She prefers walking to driving.","audio":"Estrutura do Verbo PREFER (Prefer ... TO ...)","level":"A2","module":"Preferences with 'Prefer' & 'Would Rather'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura de WOULD RATHER ('d rather + verbo base)","secondary":"Subject + 'd rather + Verbo BASE (+ THAN + Verbo BASE)","desc":"'Would rather' (ou a contração 'd rather) é seguido diretamente por um VERBO NA FORMA BASE (sem 'to'). Na comparação entre duas ações, usa-se 'THAN'.","context":"I'd rather STAY home tonight. I'd rather drink tea THAN drink coffee.","audio":"Estrutura de WOULD RATHER ('d rather + verbo base)","level":"A2","module":"Preferences with 'Prefer' & 'Would Rather'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Because / So / That's why","secondary":"/bɪˈkɒz / soʊ / ðæt s waɪ/","desc":"Porque / Portanto, Por isso / É por isso que","context":"Conectores de causa e efeito.","audio":"Because / So / That's why","level":"A2","module":"Making Choices & Justifications"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Choose to / Make a decision","secondary":"/tʃuːz tuː / meɪk ə dɪˈsɪʒn/","desc":"Escolher / Tomar uma decisão","context":"Tomada de decisão.","audio":"Choose to / Make a decision","level":"A2","module":"Making Choices & Justifications"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Diferença: BECAUSE (Motivo) vs. SO (Consequência)","secondary":"[Resultado] + BECAUSE + [Motivo] | [Motivo] + SO + [Resultado]","desc":"'BECAUSE' introduz a razão/motivo de algo. 'SO' introduz o resultado/consequência da ação.","context":"I stayed home BECAUSE it was raining. | It was raining, SO I stayed home.","audio":"Diferença: BECAUSE (Motivo) vs. SO (Consequência)","level":"A2","module":"Making Choices & Justifications"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Uso de THAT'S WHY (É por isso que)","secondary":"[Justificativa prévia]. THAT'S WHY + [Resultado]","desc":"'That's why' é usado para enfatizar a conclusão lógica resultante de uma justificativa prévia.","context":"I love animals. That's why I became a veterinarian.","audio":"Uso de THAT'S WHY (É por isso que)","level":"A2","module":"Making Choices & Justifications"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Boarding pass / Passport / Gate","secondary":"/ˈbɔːrdɪŋ pæs / ˈpæspɔːrt / ɡeɪt/","desc":"Cartão de embarque / Passaporte / Portão","context":"Documentos e local do aeroporto.","audio":"Boarding pass / Passport / Gate","level":"A2","module":"At the Airport & Security"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Luggage, Baggage / Carry-on bag","secondary":"/ˈlʌɡɪdʒ / ˈkæri ɒn bæɡ/","desc":"Bagagem / Mala de mão","context":"Tipos de bagagem.","audio":"Luggage, Baggage / Carry-on bag","level":"A2","module":"At the Airport & Security"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Security check / Customs","secondary":"/sɪˈkjʊərəti tʃek / ˈkʌstəmz/","desc":"Inspeção de segurança / Alfândega","context":"Controle aeroportuário.","audio":"Security check / Customs","level":"A2","module":"At the Airport & Security"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Substantivo Incontável: LUGGAGE / BAGGAGE","secondary":"Correto: my luggage, two pieces of luggage | Incorreto: a luggage, luggages","desc":"Em inglês, 'luggage' e 'baggage' são SUBSTANTIVOS INCONTÁVEIS! Nunca adicione 's' no final (luggages é erro) nem use o artigo 'a' antes deles.","context":"I have two PIECES OF LUGGAGE. (NÃO 'two luggages').","audio":"Substantivo Incontável: LUGGAGE / BAGGAGE","level":"A2","module":"At the Airport & Security"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pedidos Educados com MAY / COULD","secondary":"May I + [Verbo base]? | Could you + [Verbo base]?","desc":"Em aeroportos e balcões de atendimento, usam-se 'May I see...?' ou 'Could you show me...?' para solicitações extremamente formais e educadas.","context":"May I see your passport? | Could you place your bag here?","audio":"Pedidos Educados com MAY / COULD","level":"A2","module":"At the Airport & Security"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Reservation / Check-in / Check-out","secondary":"/ˌrezərˈveɪʃn/","desc":"Reserva / Entrada no hotel / Saída do hotel","context":"Procedimentos de hotelaria.","audio":"Reservation / Check-in / Check-out","level":"A2","module":"Checking into a Hotel & Requests"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Double room / Single room / Key card","secondary":"/ˈdʌbl ruːm / kiː kɑːrd/","desc":"Quarto duplo / Quarto de solteiro / Cartão-chave","context":"Tipos de quarto e acesso.","audio":"Double room / Single room / Key card","level":"A2","module":"Checking into a Hotel & Requests"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Extra towels / Room service / Amenities","secondary":"/ˈekstrə ˈtaʊəlz/","desc":"Toalhas extras / Serviço de quarto / Comodidades","context":"Pedidos no hotel.","audio":"Extra towels / Room service / Amenities","level":"A2","module":"Checking into a Hotel & Requests"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pedidos Formais com COULD I HAVE / COULD I GET","secondary":"Could I have / get + [Item], please?","desc":"Em hotéis e restaurantes, usam-se 'Could I have...?' ou 'Could I get...?' para pedir objetos ou alimentos educadamente.","context":"Could I have extra towels, please? | Could I get a wake-up call at 7 AM?","audio":"Pedidos Formais com COULD I HAVE / COULD I GET","level":"A2","module":"Checking into a Hotel & Requests"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Identificação de Reserva: UNDER THE NAME OF","secondary":"I have a reservation under [Name]","desc":"Para indicar o nome na reserva do hotel, usa-se a expressão 'under the name of [Nome]' ou 'under [Nome]'.","context":"I have a reservation under the name of John Smith.","audio":"Identificação de Reserva: UNDER THE NAME OF","level":"A2","module":"Checking into a Hotel & Requests"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"One-way ticket / Round-trip ticket","secondary":"/wʌn weɪ / raʊnd trɪp/","desc":"Passagem só de ida / Passagem de ida e volta","context":"Tipos de bilhete.","audio":"One-way ticket / Round-trip ticket","level":"A2","module":"Buying Tickets & Transportation"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Platform / Schedule, Timetable","secondary":"/ˈplætfɔːrm / ˈskedʒuːl/","desc":"Plataforma / Horário, Tabela de horários","context":"Estação de trem/ônibus.","audio":"Platform / Schedule, Timetable","level":"A2","module":"Buying Tickets & Transportation"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Transfer / Change trains","secondary":"/ˈtrænsfɜːr / tʃeɪndʒ treɪnz/","desc":"Baldeação, Transbordo / Trocar de trem","context":"Troca de linha de transporte.","audio":"Transfer / Change trains","level":"A2","module":"Buying Tickets & Transportation"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Diferença: ONE-WAY vs. ROUND-TRIP (ou Return Ticket)","secondary":"US: one-way / round-trip | UK: single / return","desc":"No inglês americano: 'one-way' (ida) e 'round-trip' (ida e volta). No inglês britânico: 'single ticket' (ida) e 'return ticket' (ida e volta).","context":"A round-trip ticket to Boston, please. | A return ticket to London, please.","audio":"Diferença: ONE-WAY vs. ROUND-TRIP (ou Return Ticket)","level":"A2","module":"Buying Tickets & Transportation"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Perguntas de Embarque com LEAVE FROM","secondary":"Which platform + does + [transport] + leave from?","desc":"Para perguntar de onde parte o transporte, usamos 'Which platform does the train leave from?' ou 'What time does the bus leave?'.","context":"Which platform does the train to Oxford leave from?","audio":"Perguntas de Embarque com LEAVE FROM","level":"A2","module":"Buying Tickets & Transportation"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Intersection / Traffic light / Crosswalk","secondary":"/ˌɪntərˈsekʃn / ˈtræfɪk laɪt/","desc":"Cruzamento, Interseção / Semáforo / Faixa de pedestres","context":"Pontos de referência urbanos.","audio":"Intersection / Traffic light / Crosswalk","level":"A2","module":"Giving & Asking for Detailed Directions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Cross the bridge / Walk past the bank","secondary":"/krɒs ðə brɪdʒ/","desc":"Cruzar a ponte / Passar direto pelo banco","context":"Ações de deslocamento.","audio":"Cross the bridge / Walk past the bank","level":"A2","module":"Giving & Asking for Detailed Directions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Go straight / Turn left / Turn right","secondary":"/ɡoʊ streɪt/","desc":"Siga reto / Vire à esquerda / Vire à direita","context":"Direções básicas.","audio":"Go straight / Turn left / Turn right","level":"A2","module":"Giving & Asking for Detailed Directions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Imperativo para Dar Instruções de Caminho","secondary":"Verbo Base + [Direção / Ponto de Referência]","desc":"Para dar direções na cidade, usamos o verbo na forma imperativa (sem sujeito, direto no verbo base).","context":"GO straight. TURN left at the supermarket. CROSS the street.","audio":"Imperativo para Dar Instruções de Caminho","level":"A2","module":"Giving & Asking for Detailed Directions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Preposição de Passagem: PAST","secondary":"Walk / Go + PAST + [Ponto de referência]","desc":"Quando você deve continuar andando e passar por um prédio sem entrar nele, usa-se o verbo + 'past [lugar]'.","context":"Walk PAST the museum and turn left. (Passe direto pelo museu e vire à esquerda).","audio":"Preposição de Passagem: PAST","level":"A2","module":"Giving & Asking for Detailed Directions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I lost my wallet / my passport","secondary":"/aɪ lɒst maɪ ˈwɒlɪt/","desc":"Eu perdi minha carteira / meu passaporte","context":"Perda de pertences.","audio":"I lost my wallet / my passport","level":"A2","module":"Travel Emergencies & Lost Items"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Police station / Embassy / Hospital","secondary":"/pəˈliːs steɪʃn / ˈembəsi/","desc":"Delegacia de polícia / Embaixada / Hospital","context":"Locais de emergência.","audio":"Police station / Embassy / Hospital","level":"A2","module":"Travel Emergencies & Lost Items"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Stolen / Robbed / Emergency","secondary":"/ˈstoʊlən / rɑːbd/","desc":"Roubado / Assaltado / Emergência","context":"Ocorrência policial.","audio":"Stolen / Robbed / Emergency","level":"A2","module":"Travel Emergencies & Lost Items"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressões Urgentes de Socorro: HELP! / I NEED...","secondary":"I need + [Ajuda/Serviço] + immediately / right now!","desc":"Em emergências, usam-se frases curtas e diretas com 'I lost...', 'My [item] was stolen', ou 'I need a doctor / the police immediately'.","context":"I need the police immediately! | My bag was stolen.","audio":"Expressões Urgentes de Socorro: HELP! / I NEED...","level":"A2","module":"Travel Emergencies & Lost Items"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Localização de Serviços de Emergência: NEAREST","secondary":"Where is the NEAREST + [police station / hospital / embassy]?","desc":"Para perguntar onde fica o hospital ou delegacia mais próximo, usamos 'Where is the NEAREST...?' (superlativo de near).","context":"Where is the nearest police station?","audio":"Localização de Serviços de Emergência: NEAREST","level":"A2","module":"Travel Emergencies & Lost Items"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Headache / Stomachache / Toothache","secondary":"/ˈhedeɪk / ˈstʌmək-eɪk/","desc":"Dor de cabeça / Dor de estômago / Dor de dente","context":"Dores de corpo com -ache.","audio":"Headache / Stomachache / Toothache","level":"A2","module":"Symptoms, Illness & At the Pharmacy"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Fever / Cough / Sore throat","secondary":"/ˈfiːvər / kɒf / sɔːr θroʊt/","desc":"Febre / Tosse / Dor de garganta","context":"Sintomas de gripe.","audio":"Fever / Cough / Sore throat","level":"A2","module":"Symptoms, Illness & At the Pharmacy"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Painkillers / Medicine / Pharmacy","secondary":"/ˈpeɪnkɪlərz / ˈmedsn/","desc":"Analgésicos / Remédio / Farmácia","context":"Tratamento na farmácia.","audio":"Painkillers / Medicine / Pharmacy","level":"A2","module":"Symptoms, Illness & At the Pharmacy"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressando Dores com HAVE A...","secondary":"Subject + have / has + a + [headache / fever / cough / sore throat]","desc":"Em inglês, para indicar dores e sintomas de saúde, usa-se o verbo 'HAVE A + [sintoma]'. O artigo 'a' é obrigatório na maioria das dores com '-ache'!","context":"I HAVE A headache. She HAS A fever. He HAS A sore throat.","audio":"Expressando Dores com HAVE A...","level":"A2","module":"Symptoms, Illness & At the Pharmacy"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Sufixo de Dor: -ACHE","secondary":"[Parte do corpo] + ache","desc":"O sufixo '-ache' significa dor contínua e junta-se com partes do corpo: Head + ache = headache | Back + ache = backache | Ear + ache = earache.","context":"Headache (cabeça) | Stomachache (estômago) | Toothache (dente)","audio":"O Sufixo de Dor: -ACHE","level":"A2","module":"Symptoms, Illness & At the Pharmacy"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Have to / Has to","secondary":"/hæv tuː / hæz tuː/","desc":"Ter que / Tem que (Obrigação)","context":"Obrigação diária.","audio":"Have to / Has to","level":"A2","module":"Obligation & Necessity (Have to / Don't have to)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Don't have to / Doesn't have to","secondary":"/doʊnt hæv tuː/","desc":"Não precisar / Não ter que (Sem obrigação)","context":"Ausência de necessidade.","audio":"Don't have to / Doesn't have to","level":"A2","module":"Obligation & Necessity (Have to / Don't have to)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura de HAVE TO (Obrigação Externa)","secondary":"Subject + have to / has to + Verbo Base","desc":"Usamos 'have to' (para I, You, We, They) e 'has to' (para He, She, It) seguidos de verbo base para indicar coisas obrigatórias ou necessárias.","context":"I HAVE TO wear a uniform. She HAS TO take her medicine.","audio":"Estrutura de HAVE TO (Obrigação Externa)","level":"A2","module":"Obligation & Necessity (Have to / Don't have to)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"CUIDADO: DON'T HAVE TO = Ausência de Obrigação (Opção)","secondary":"Subject + don't/doesn't have to + Verbo Base","desc":"'Don't have to' NÃO significa proibição! Significa que você NÃO É OBRIGADO a fazer algo, mas PODE fazer se quiser.","context":"Tomorrow is Sunday, so I DON'T HAVE TO wake up early. (Posso acordar tarde se quiser).","audio":"CUIDADO: DON'T HAVE TO = Ausência de Obrigação (Opção)","level":"A2","module":"Obligation & Necessity (Have to / Don't have to)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Must not (Mustn't) / Can't","secondary":"/mʌst nɒt / kænt/","desc":"Não pode, É proibido / Não pode","context":"Expressar proibição.","audio":"Must not (Mustn't) / Can't","level":"A2","module":"Prohibitions & Rules (Must not / Can't)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Forbidden / Not allowed / Against the law","secondary":"/fərˈbɪdn / əˈlaʊd/","desc":"Proibido / Não permitido / Contra a lei","context":"Expressões de regras.","audio":"Forbidden / Not allowed / Against the law","level":"A2","module":"Prohibitions & Rules (Must not / Can't)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"DIFERENÇA CRÍTICA: Mustn't (Proibição) vs. Don't have to (Opcional)","secondary":"MUSTN'T = Proibido | DON'T HAVE TO = Não necessário / Opcional","desc":"MUSTN'T significa que algo é ESTRITAMENTE PROIBIDO! Don't have to significa que é OPCIONAL (não é necessário).","context":"You MUSTN'T smoke here. (É proibido fumar!). You DON'T HAVE TO wear a tie. (Pode usar gravata se quiser).","audio":"DIFERENÇA CRÍTICA: Mustn't (Proibição) vs. Don't have to (Opcional)","level":"A2","module":"Prohibitions & Rules (Must not / Can't)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Uso de CAN'T para Proibição Informal","secondary":"Subject + CAN'T + Verbo Base","desc":"Na linguagem cotidiana, 'Can't' é muito usado para indicar que algo não é permitido pelas regras do local.","context":"You CAN'T park here. (Você não pode estacionar aqui).","audio":"Uso de CAN'T para Proibição Informal","level":"A2","module":"Prohibitions & Rules (Must not / Can't)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Should / Shouldn't","secondary":"/ʃʊd / ˈʃʊdnt/","desc":"Deveria / Não deveria","context":"Conselhos e recomendações.","audio":"Should / Shouldn't","level":"A2","module":"Giving Advice with 'Should'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Give advice / Take a break","secondary":"/ɡɪv ədˈvaɪs / teɪk ə breɪk/","desc":"Dar conselho / Fazer uma pausa","context":"Ações de suporte.","audio":"Give advice / Take a break","level":"A2","module":"Giving Advice with 'Should'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Uso do Modal SHOULD (Conselho / Recomendação)","secondary":"Subject + SHOULD / SHOULDN'T + Verbo Base","desc":"Usamos 'SHOULD' (deveria) e 'SHOULDN'T' (não deveria) para expressar nossa opinião sobre o que é uma boa ou má ideia para alguém fazer.","context":"You SHOULD see a doctor. You SHOULDN'T work so hard.","audio":"Uso do Modal SHOULD (Conselho / Recomendação)","level":"A2","module":"Giving Advice with 'Should'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra Modal: Sem 'TO' e Sem '-S' na 3ª Pessoa","secondary":"CORRETO: He should rest | INCORRETO: He shoulds rest / He should to rest","desc":"Como todos os modais, 'Should' é idêntico para todos os sujeitos (I, You, He, She, We, They) e NUNCA usa 'to' antes do verbo seguinte!","context":"She SHOULD rest. (NÃO 'she shoulds to rest').","audio":"Regra Modal: Sem 'TO' e Sem '-S' na 3ª Pessoa","level":"A2","module":"Giving Advice with 'Should'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Because of / Due to","secondary":"/bɪˈkɒz əv / djuː tuː/","desc":"Por causa de / Devido a","context":"Causa seguida de substantivo.","audio":"Because of / Due to","level":"A2","module":"Expressing Reasons & Explanations"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Since / As","secondary":"/sɪns / æz/","desc":"Já que / Como (introduzindo causa)","context":"Causa no início da frase.","audio":"Since / As","level":"A2","module":"Expressing Reasons & Explanations"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Diferença: BECAUSE vs. BECAUSE OF / DUE TO","secondary":"Because + [Sujeito + Verbo] | Because of / Due to + [Substantivo]","desc":"'BECAUSE' é seguido de uma oração completa (com sujeito + verbo). 'BECAUSE OF' e 'DUE TO' são seguidos por um SUBSTANTIVO ou grupo nominal!","context":"We stayed inside BECAUSE IT WAS RAINING. | We stayed inside BECAUSE OF THE RAIN.","audio":"Diferença: BECAUSE vs. BECAUSE OF / DUE TO","level":"A2","module":"Expressing Reasons & Explanations"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Uso de SINCE como 'Já que'","secondary":"SINCE + [Razão/Causa], + [Resultado]","desc":"Além de indicar tempo ('desde'), 'SINCE' também é usado como conjunção de causa no início de frases, significando 'Já que' ou 'Visto que'.","context":"SINCE you are tired, you should go to sleep early.","audio":"Uso de SINCE como 'Já que'","level":"A2","module":"Expressing Reasons & Explanations"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Am / Is / Are going to","secondary":"/ɡoʊɪŋ tuː/","desc":"Vou / Vai / Vamos (Futuro planejado)","context":"Planos futuros intencionais.","audio":"Am / Is / Are going to","level":"A2","module":"Future Intentions with 'Be Going To'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Next week / Next month / Next year","secondary":"/nekst wiːk/","desc":"Próxima semana / Próximo mês / Próximo ano","context":"Marcadores de tempo futuro.","audio":"Next week / Next month / Next year","level":"A2","module":"Future Intentions with 'Be Going To'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura do Futuro com BE GOING TO","secondary":"Subject + am/is/are + GOING TO + Verbo Base","desc":"Usamos o verbo To Be (am/is/are) + GOING TO + verbo base para falar sobre planos ou intenções que já foram decididos antes do momento da fala.","context":"I AM GOING TO VISIT my doctor. She IS GOING TO BUY a car.","audio":"Estrutura do Futuro com BE GOING TO","level":"A2","module":"Future Intentions with 'Be Going To'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Forma Negativa e Interrogativa com BE GOING TO","secondary":"Negativa: Subject + isn't/aren't + going to + V | Pergunta: Is/Are + Subject + going to + V?","desc":"Na negativa, adiciona-se 'not' após o verbo To Be (am not, isn't, aren't). Na pergunta, inverte-se o verbo To Be com o sujeito.","context":"They AREN'T GOING TO TRAVEL. | ARE YOU GOING TO STUDY tonight?","audio":"Forma Negativa e Interrogativa com BE GOING TO","level":"A2","module":"Future Intentions with 'Be Going To'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Would you like to...? / Do you want to...?","secondary":"/wʊd juː laɪk tuː/","desc":"Você gostaria de...? / Você quer...?","context":"Fazer convite social.","audio":"Would you like to...? / Do you want to...?","level":"A2","module":"Making & Responding to Invitations"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I'd love to! / That sounds great!","secondary":"/aɪd lʌv tuː / ðæt saʊndz ɡreɪt/","desc":"Eu adoraria! / Parece ótimo!","context":"Aceitar convites com entusiasmo.","audio":"I'd love to! / That sounds great!","level":"A2","module":"Making & Responding to Invitations"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fazer Convites com WOULD YOU LIKE TO","secondary":"Would you like to + Verbo Base + complemento?","desc":"A forma mais elegante e educada de convidar alguém para um evento é usar 'Would you like to + [verbo base]?'.","context":"WOULD YOU LIKE TO HAVE lunch with me? | WOULD YOU LIKE TO GO to the cinema?","audio":"Fazer Convites com WOULD YOU LIKE TO","level":"A2","module":"Making & Responding to Invitations"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Aceitar Convites com I'D LOVE TO","secondary":"I'd love to! (+ Thank you for asking)","desc":"A resposta afirmativa mais comum e cortês é 'I'd love to!' (contração de 'I would love to'). O 'to' no final é mantido!","context":"Would you like to join us? ➔ I'D LOVE TO! Thanks!","audio":"Aceitar Convites com I'D LOVE TO","level":"A2","module":"Making & Responding to Invitations"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I'm afraid I can't / I'd love to, but...","secondary":"/aɪm əˈfreɪd aɪ kænt/","desc":"Receio que não posso / Adoraria, mas...","context":"Recusa educada.","audio":"I'm afraid I can't / I'd love to, but...","level":"A2","module":"Polite Refusals & Excuses"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Maybe next time / Another time","secondary":"/ˈmeɪbi nekst taɪm/","desc":"Talvez da próxima vez / Em outro momento","context":"Deixar porta aberta para o futuro.","audio":"Maybe next time / Another time","level":"A2","module":"Polite Refusals & Excuses"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Fórmula da Recusa Educada em Inglês","secondary":"[Agradecer/Lamentar] + [Justificativa] + [Maybe next time!]","desc":"Em inglês, NUNCA responda apenas 'No' a um convite social! A estrutura educada de recusa exige 3 passos: 1. Agradecer/Expressar lamento ('I'm afraid I can't' ou 'I'd love to, but') + 2. Dar uma justificativa gentil ('I have to study') + 3. Manter o laço social ('Maybe next time!').","context":"I'd love to, BUT I have to work late. Maybe next time!","audio":"A Fórmula da Recusa Educada em Inglês","level":"A2","module":"Polite Refusals & Excuses"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Uso de 'I'M AFRAID...'","secondary":"I'm afraid + [notícia negativa / recusa]","desc":"No inglês social, 'I'm afraid...' não significa ter medo de algo. Significa 'Infelizmente / Receio que...', usado para suavizar notícias ou recusas.","context":"I'm afraid I can't come to your party on Saturday.","audio":"Uso de 'I'M AFRAID...'","level":"A2","module":"Polite Refusals & Excuses"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"This is for you! / Happy Birthday!","secondary":"/ðɪs ɪz fɔːr juː/","desc":"Isto é para você! / Feliz Aniversário!","context":"Entregar um presente.","audio":"This is for you! / Happy Birthday!","level":"A2","module":"Giving & Receiving Gifts (Presentations & Favors)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"You shouldn't have! / Thank you so much!","secondary":"/juː ˈʃʊdnt hæv/","desc":"Não precisava! (Expressão de carinho) / Muito obrigado!","context":"Agradecer presente.","audio":"You shouldn't have! / Thank you so much!","level":"A2","module":"Giving & Receiving Gifts (Presentations & Favors)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressão Cultural de Cortesia: YOU SHOULDN'T HAVE!","secondary":"Oh, thank you! YOU SHOULDN'T HAVE!","desc":"Ao receber um presente especial em inglês, é muito comum dizer 'You shouldn't have!' (literalmente: você não precisava ter tido esse trabalho/gasto!). É um elogio de extrema gratidão.","context":"A gift for me? Oh, you shouldn't have! Thank you so much!","audio":"Expressão Cultural de Cortesia: YOU SHOULDN'T HAVE!","level":"A2","module":"Giving & Receiving Gifts (Presentations & Favors)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Respostas a Agradecimentos de Presente","secondary":"I'm glad you like it! | My pleasure!","desc":"Em resposta ao agradecimento de um presente, usam-se expressões calorosas como 'You're very welcome!', 'I'm glad you like it!' (Fico feliz que tenha gostado!).","context":"Thank you for the gift! ➔ I'm so glad you like it!","audio":"Respostas a Agradecimentos de Presente","level":"A2","module":"Giving & Receiving Gifts (Presentations & Favors)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Resumo Gramatical do Nível A2","secondary":"A2 Master Grammar Matrix","desc":"O Nível A2 consolida o Present Simple vs Continuous, Past Simple (regulares -ed e irregulares), Past Continuous, Comparativos e Superlativos, Modais de Obrigação (Have to, Mustn't, Should) e Expressões de Futuro (Be going to).","context":"I went, she was sleeping, it's better than, you should rest, I'm going to travel.","audio":"Resumo Gramatical do Nível A2","level":"A2","module":"A2 Final Challenge: Complete Travel & Social Simulation"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Gonna / Wanna","secondary":"/ˈɡənə / ˈwɑːnə/","desc":"Indo (Going to) / Querer (Want to)","context":"Contrações de intenção e desejo em conversas informais.","audio":"Gonna / Wanna","level":"B1","module":"Informal Speech & Reduced Forms"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Gotta / Kinda / Outta","secondary":"/ˈɡɑːtə / ˈkaɪndə / ˈaʊtə/","desc":"Ter que (Got to) / Um pouco (Kind of) / Fora de (Out of)","context":"Formas reduzidas da fala fluida.","audio":"Gotta / Kinda / Outta","level":"B1","module":"Informal Speech & Reduced Forms"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Formas Reduzidas (Reduced Forms)","secondary":"Subject + gonna/wanna/gotta + Verb base","desc":"Na fala rápida e informal, preposições e auxiliares fundem-se com verbos. 'Going to' vira 'gonna', 'want to' vira 'wanna' e 'got to' vira 'gotta'. Usam-se em conversas casuais, mas NUNCA em escrita formal ou profissional.","context":"I gonna leave. (Incorreto) ➔ I'm gonna leave. (Correto - mantenha o verbo Be com gonna!).","audio":"Formas Reduzidas (Reduced Forms)","level":"B1","module":"Informal Speech & Reduced Forms"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Pegadinha Gramatical: 'Gonna' exige verbo 'To Be'","secondary":"Subject + am/is/are + gonna + Verb base","desc":"Embora 'gonna' reduza 'going to', ele AINDA requer o verbo auxiliares (am/is/are) antes dele na frase.","context":"She is gonna buy a car. (NÃO: She gonna buy a car).","audio":"Pegadinha Gramatical: 'Gonna' exige verbo 'To Be'","level":"B1","module":"Informal Speech & Reduced Forms"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Pick it up / Check it out","secondary":"/pɪkɪtʌp / tʃekɪtaʊt/","desc":"Pegar isso / Conferir isso","context":"Exemplos clássicos de consoante ligada a vogal.","audio":"Pick it up / Check it out","level":"B1","module":"Connected Speech & Linking Sounds"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Rock 'n' roll / Fish 'n' chips","secondary":"/rɑːkənroʊl/","desc":"Rock and roll / Peixe com fritas","context":"Redução da conjunção 'and' para um som 'n'.","audio":"Rock 'n' roll / Fish 'n' chips","level":"B1","module":"Connected Speech & Linking Sounds"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra de Encadeamento Consoante + Vogal","secondary":"[Consoante final] + [Vogal inicial] ➔ Som contínuo","desc":"Quando uma palavra termina em som de consoante e a seguinte começa com som de vogal, elas se unem na fala parecendo uma única palavra.","context":"Far away ➔ /fɑːrəweɪ/ | Hold on ➔ /hoʊldɑːn/","audio":"Regra de Encadeamento Consoante + Vogal","level":"B1","module":"Connected Speech & Linking Sounds"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Redução do 'And' e do 'Of'","secondary":"Bread and butter ➔ 'Bread 'n' butter' | Piece of cake ➔ 'Piece av cake'","desc":"O 'and' é frequentemente reduzido para /n/ ou /ən/. O 'of' costuma soar apenas como /əv/ ou /ə/ antes de consoantes.","context":"Cup of tea ➔ /kʌp əv tiː/","audio":"A Redução do 'And' e do 'Of'","level":"B1","module":"Connected Speech & Linking Sounds"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"In my opinion / From my perspective","secondary":"/ɪn maɪ əˈpɪnjən/","desc":"Na minha opinião / Da minha perspectiva","context":"Introdução formal e neutra de pareceres.","audio":"In my opinion / From my perspective","level":"B1","module":"Expressing Opinions & Thoughts"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"As far as I'm concerned","secondary":"/æz fɑːr æz aɪm kənˈsɜːrnd/","desc":"No que me diz respeito / Ao meu ver","context":"Expressão forte e elegante de opinião pessoal.","audio":"As far as I'm concerned","level":"B1","module":"Expressing Opinions & Thoughts"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Marcadores de Opinião e Posição","secondary":"[Marcador de Opinião], + [Frase Principal]","desc":"Para evitar repetir 'I think', use conectores variados como 'In my view', 'To be honest', ou 'I reckon' (muito comum no inglês britânico).","context":"As far as I'm concerned, this project is a success.","audio":"Marcadores de Opinião e Posição","level":"B1","module":"Expressing Opinions & Thoughts"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura do 'I think that...'","secondary":"I believe (that) + Subject + Verb","desc":"A conjunção 'that' após verbos de pensamento (think, believe, feel) é opcional na fala.","context":"I reckon (that) we will win.","audio":"Estrutura do 'I think that...'","level":"B1","module":"Expressing Opinions & Thoughts"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Might / May","secondary":"/maɪt / meɪ/","desc":"Pode ser que / Talvez","context":"Verbos modais de possibilidade presente/futura.","audio":"Might / May","level":"B1","module":"Expressing Doubts & Uncertainty"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I'm not entirely sure","secondary":"/aɪm nɑːt ɪnˈtaɪərli ʃʊr/","desc":"Não tenho absoluta certeza","context":"Forma educada de demonstrar dúvida.","audio":"I'm not entirely sure","level":"B1","module":"Expressing Doubts & Uncertainty"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Might vs. May (Possibilidade)","secondary":"Subject + might / may + Verb base","desc":"Ambos expressam possibilidade no presente ou futuro. 'Might' indica uma probabilidade um pouco menor ou mais remota que 'May'. Nenhum deles muda de forma para He/She/It.","context":"She MIGHT come to the party. (Talvez ela venha).","audio":"Might vs. May (Possibilidade)","level":"B1","module":"Expressing Doubts & Uncertainty"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressões de Dúvida: 'I doubt that' e 'It's unlikely'","secondary":"It is unlikely + (that) + Clause","desc":"Para expressar que algo dificilmente acontecerá, usam-se 'I doubt that...' ou 'It is unlikely that...'.","context":"It's unlikely that the price will drop.","audio":"Expressões de Dúvida: 'I doubt that' e 'It's unlikely'","level":"B1","module":"Expressing Doubts & Uncertainty"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Have you ever...? / I have never...","secondary":"/hæv juː ˈevər/","desc":"Você já... (alguma vez na vida)? / Eu nunca...","context":"Perguntas e negações sobre experiências de vida.","audio":"Have you ever...? / I have never...","level":"B1","module":"Life Experiences with 'Present Perfect'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Already / Yet / Just","secondary":"/ɔːlˈredi / jet / dʒʌst/","desc":"Já (afirmativa) / Já, ainda (negativa/pergunta) / Acabar de","context":"Adverbiais temporais do Present Perfect.","audio":"Already / Yet / Just","level":"B1","module":"Life Experiences with 'Present Perfect'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fórmula do Present Perfect","secondary":"Subject + have/has + Past Participle","desc":"Usa-se o auxiliar HAVE/HAS seguido do verbo no Past Participle (3ª coluna dos verbos). É usado para ações passadas onde o tempo exato NÃO é mencionado ou importa a experiência no presente.","context":"I HAVE VISITED Paris. She HAS TRIED sushi.","audio":"Fórmula do Present Perfect","level":"B1","module":"Life Experiences with 'Present Perfect'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Diferença: 'Been to' vs. 'Gone to'","secondary":"Been to = foi e voltou | Gone to = foi e não voltou","desc":"'Have been to' significa que a pessoa foi e JÁ VOLTOU. 'Have gone to' significa que a pessoa foi e AINDA ESTÁ LÁ.","context":"He has been to Italy. (Ele já esteve na Itália e voltou).","audio":"Diferença: 'Been to' vs. 'Gone to'","level":"B1","module":"Life Experiences with 'Present Perfect'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Yesterday / Last year / In 2020","secondary":"/ˈjestərdeɪ/","desc":"Ontem / Ano passado / Em 2020","context":"Expressões de tempo acabado (marcam o Past Simple).","audio":"Yesterday / Last year / In 2020","level":"B1","module":"Present Perfect vs. Past Simple"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Since 2010 / For 5 years","secondary":"/sɪns / fɔːr/","desc":"Desde 2010 / Por 5 anos","context":"Marcadores de duração contínua no Present Perfect.","audio":"Since 2010 / For 5 years","level":"B1","module":"Present Perfect vs. Past Simple"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra de Ouro: Tempo Definido vs. Indefinido","secondary":"Specific time ➔ Past Simple | Unspecified time / Continuous ➔ Present Perfect","desc":"Se você menciona QUANDO a ação aconteceu no passado (ex: yesterday, last week, in 2015), USE PAST SIMPLE. Se o tempo NÃO é especificado ou a ação continua no presente, USE PRESENT PERFECT.","context":"I saw him YESTERDAY. (Past) vs. I have seen him ALREADY. (Present Perfect)","audio":"Regra de Ouro: Tempo Definido vs. Indefinido","level":"B1","module":"Present Perfect vs. Past Simple"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Since' vs. 'For'","secondary":"Since + Start Point | For + Duration","desc":"'Since' marca o ponto de início (Since 2015, Since Monday). 'For' indica a duração total do tempo (For 10 years, For two hours).","context":"I have worked here SINCE 2020. | I have worked here FOR 4 years.","audio":"'Since' vs. 'For'","level":"B1","module":"Present Perfect vs. Past Simple"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Due to / Owing to","secondary":"/djuː tuː / ˈoʊɪŋ tuː/","desc":"Devido a / Em razão de","context":"Conectores de causa seguidos de substantivo ou pronome.","audio":"Due to / Owing to","level":"B1","module":"Explaining Reasons & Consequences"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"As a result / Therefore","secondary":"/æz ə rɪˈzʌlt / ˈðerfɔːr/","desc":"Como resultado / Portanto","context":"Conectores de consequência formal.","audio":"As a result / Therefore","level":"B1","module":"Explaining Reasons & Consequences"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Conectores Causais: 'Due to' + Noun","secondary":"Due to + [Substantivo] | Due to + the fact that + [Oração]","desc":"'Due to' e 'Owing to' devem ser seguidos diretamente por um substantivo ou grupo nominal (ou pela estrutura 'the fact that').","context":"Due to heavy rain, the event was canceled.","audio":"Conectores Causais: 'Due to' + Noun","level":"B1","module":"Explaining Reasons & Consequences"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Conectores de Consequência: 'As a result' & 'Therefore'","secondary":"[Causa]. Therefore, + [Consequência]","desc":"'As a result' e 'Therefore' introduzem a consequência de algo mencionado anteriormente e costumam vir iniciados por ponto ou vírgula.","context":"He didn't study. Therefore, he failed the exam.","audio":"Conectores de Consequência: 'As a result' & 'Therefore'","level":"B1","module":"Explaining Reasons & Consequences"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Should have / Shouldn't have","secondary":"/ʃʊd hæv / ˈʃʊdnt hæv/","desc":"Deveria ter / Não deveria ter","context":"Expressão de remorso ou conselho no passado.","audio":"Should have / Shouldn't have","level":"B1","module":"Regrets, Accidents & Mistakes"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"End up","secondary":"/end ʌp/","desc":"Acabar (acontecendo/indo)","context":"Resultado de uma sequência inesperada de fatos.","audio":"End up","level":"B1","module":"Regrets, Accidents & Mistakes"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Arrependimentos: Should Have + Past Participle","secondary":"Subject + should (not) have + Past Participle","desc":"Para expressar que você se arrepende de algo no passado ou que uma ação ideal não ocorreu, use 'should have' ou 'shouldn't have' + 3ª forma do verbo.","context":"I SHOULD HAVE STUDIED more. (Eu deveria ter estudado mais).","audio":"Arrependimentos: Should Have + Past Participle","level":"B1","module":"Regrets, Accidents & Mistakes"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Imprevistos com 'End Up'","secondary":"End up + Verb(-ing)","desc":"Após o phrasal verb 'end up', o verbo seguinte fica obrigatoriamente no gerúndio (-ing).","context":"We got lost and ENDED UP TAKING a taxi.","audio":"Imprevistos com 'End Up'","level":"B1","module":"Regrets, Accidents & Mistakes"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"If / Unless","secondary":"/ɪf / ənˈles/","desc":"Se / A não ser que (A menos que)","context":"Conectores de condição real e alternativa.","audio":"If / Unless","level":"B1","module":"First Conditional (Real Possibilities)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"As soon as / Provided that","secondary":"/æz suːn æz/","desc":"Assim que / Contanto que","context":"Marcadores temporais e condicionais de futuro.","audio":"As soon as / Provided that","level":"B1","module":"First Conditional (Real Possibilities)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura do First Conditional","secondary":"If + Present Simple, Subject + Will + Verb base","desc":"A oração da condição (com 'If') fica no PRESENT SIMPLE, e a oração do resultado fica no FUTURE SIMPLE (Will + Verbo base). NUNCA use 'will' logo após o 'if'!","context":"IF IT RAINS, I WILL STAY home. (NÃO: If it will rain...)","audio":"Estrutura do First Conditional","level":"B1","module":"First Conditional (Real Possibilities)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Unless' = 'If... not'","secondary":"Unless + Affirmative Verb = If + Negative Verb","desc":"'Unless' significa 'a não ser que' ou 'a menos que' e já possui sentido negativo. Não use negação dupla com 'unless'.","context":"UNLESS YOU STUDY, you won't pass = IF YOU DON'T STUDY, you won't pass.","audio":"'Unless' = 'If... not'","level":"B1","module":"First Conditional (Real Possibilities)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"If I won / If I had","secondary":"/ɪf aɪ wʌn/","desc":"Se eu ganhasse / Se eu tivesse","context":"Orações hipotéticas no passado subjuntivo/simples.","audio":"If I won / If I had","level":"B1","module":"Second Conditional (Hypothetical Situations)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I would (I'd) / If I were you","secondary":"/aɪ dʊd / ɪf aɪ wɜːr juː/","desc":"Eu iria/faria (Eu...) / Se eu fosse você","context":"Resultado imaginário e dar conselhos.","audio":"I would (I'd) / If I were you","level":"B1","module":"Second Conditional (Hypothetical Situations)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura do Second Conditional","secondary":"If + Past Simple, Subject + Would + Verb base","desc":"A oração da condição com 'If' usa o PAST SIMPLE, e a oração do resultado usa WOULD + Verbo na forma base. Expressa situações imaginárias ou hipotéticas.","context":"If I HAD more free time, I WOULD TRAVEL the world.","audio":"Estrutura do Second Conditional","level":"B1","module":"Second Conditional (Hypothetical Situations)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Uso do 'If I WERE you' para conselhos","secondary":"If I were you, I would + Verb","desc":"No inglês formal/padrão hipotético, o verbo To Be no passado para TODAS as pessoas em 'If' é 'WERE' (If I were, If he were). 'If I were you' é a forma clássica de dar conselhos.","context":"If I were you, I would see a doctor.","audio":"Uso do 'If I WERE you' para conselhos","level":"B1","module":"Second Conditional (Hypothetical Situations)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Used to + Verb","secondary":"/juːst tuː/","desc":"Costumava (fazer algo no passado)","context":"Hábitos ou estados passados que não acontecem mais.","audio":"Used to + Verb","level":"B1","module":"Expressing Changes & Habits ('Used to' & 'Get used to')"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Get used to + V(-ing)","secondary":"/ɡet juːst tuː/","desc":"Acostumar-se com / Adaptar-se","context":"Processo de transição e adaptação a algo novo.","audio":"Get used to + V(-ing)","level":"B1","module":"Expressing Changes & Habits ('Used to' & 'Get used to')"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Used to' (Hábitos Passados)","secondary":"Subject + used to + Verb base | Negativa: didn't use to","desc":"'Used to' é seguido do verbo na FORMA BASE. Indica ações habituais ou estados no passado que JÁ NÃO ocorrem mais no presente.","context":"I USED TO PLAY tennis when I was young.","audio":"'Used to' (Hábitos Passados)","level":"B1","module":"Expressing Changes & Habits ('Used to' & 'Get used to')"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Get used to' vs. 'Be used to'","secondary":"Get/Be used to + Verb(-ing) / Noun","desc":"'Get used to' indica o PROCESSO de se acostumar. 'Be used to' indica que a pessoa JÁ ESTÁ acostumada. Ambos exigem verbo com '-ing' ou substantivo depois!","context":"I'm GETTING USED TO DRIVING on the left. | I AM USED TO THE COLD.","audio":"'Get used to' vs. 'Be used to'","level":"B1","module":"Expressing Changes & Habits ('Used to' & 'Get used to')"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Give it a try / Give it a shot","secondary":"/ɡɪv ɪt ə traɪ / ʃɑːt/","desc":"Dar uma chance / Tentar a sorte","context":"Expressões comuns de incentivo para encarar desafios.","audio":"Give it a try / Give it a shot","level":"B1","module":"Trying & Experiencing New Things"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Take a chance / Step out of your comfort zone","secondary":"/teɪk ə tʃæns/","desc":"Arriscar-se / Sair da zona de conforto","context":"Encorajar mudanças e superação pessoal.","audio":"Take a chance / Step out of your comfort zone","level":"B1","module":"Trying & Experiencing New Things"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expressões de Incentivo com Verbos na Forma Base","secondary":"Why don't you + Verb base? | You should + Verb base","desc":"Para encorajar alguém a tentar algo, usam-se estruturas imperativas ou perguntas de sugestão como 'Why don't you...?' seguidas de verbo na forma base.","context":"WHY DON'T YOU GIVE IT A SHOT? (Por que você não tenta?)","audio":"Expressões de Incentivo com Verbos na Forma Base","level":"B1","module":"Trying & Experiencing New Things"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Try' + Gerúndio vs. 'Try' + Infinitivo","secondary":"Try to do = fazer esforço | Try doing = experimentar/testar","desc":"'Try to + V' significa fazer esforço para conseguir algo difícil. 'Try + V(-ing)' significa experimentar um método novo para ver se funciona.","context":"Try taking an aspirin for your headache. (Experimente tomar).","audio":"'Try' + Gerúndio vs. 'Try' + Infinitivo","level":"B1","module":"Trying & Experiencing New Things"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Turn on / Turn off","secondary":"/tɜːrn ɑːn / ɒf/","desc":"Ligar / Desligar (aparelhos, luzes)","context":"Ações cotidianas com eletrônicos.","audio":"Turn on / Turn off","level":"B1","module":"Essential Phrasal Verbs I (Daily Actions)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Put on / Take off","secondary":"/pʊt ɑːn / teɪk ɒf/","desc":"Vestir (colocar) / Tirar (roupas/sapatos) ou Descolar (avião)","context":"Ações com vestuário e aviação.","audio":"Put on / Take off","level":"B1","module":"Essential Phrasal Verbs I (Daily Actions)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Phrasal Verbs Separáveis (Separable)","secondary":"Verb + Pronoun + Particle (OBRIGATÓRIO)","desc":"Muitos Phrasal Verbs transitivos permitem colocar o objeto ENTRE o verbo e a partícula. Se o objeto for um PRONOME (it/them/me), é OBRIGATÓRIO colocá-lo no meio!","context":"Turn off the light = Turn the light off | Turn IT off (CORRETO) | Turn off IT (INCORRETO)","audio":"Phrasal Verbs Separáveis (Separable)","level":"B1","module":"Essential Phrasal Verbs I (Daily Actions)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Look for' vs. 'Look after'","secondary":"Look for = pesquisar/procurar | Look after = cuidar/zelar","desc":"'Look for' significa procurar/buscar algo perdido. 'Look after' significa cuidar de alguém ou algo.","context":"I am LOOKING FOR my keys. | Can you LOOK AFTER my dog?","audio":"'Look for' vs. 'Look after'","level":"B1","module":"Essential Phrasal Verbs I (Daily Actions)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Get along with / Count on","secondary":"/ɡet əˈlɔːŋ wɪð / kaʊnt ɑːn/","desc":"Dar-se bem com / Contar com (confiar)","context":"Phrasal verbs de convivência e confiança.","audio":"Get along with / Count on","level":"B1","module":"Essential Phrasal Verbs II (Relationships)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Break up / Run into / Look up to","secondary":"/breɪk ʌp / rʌn ˈɪntuː/","desc":"Terminar namoro / Esbarrar em alguém / Admirar alguém","context":"Eventos sociais e de relacionamento.","audio":"Break up / Run into / Look up to","level":"B1","module":"Essential Phrasal Verbs II (Relationships)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Phrasal Verbs com Três Palavras (Three-part Phrasal Verbs)","secondary":"Verb + Particle 1 + Particle 2 + Object","desc":"Alguns Phrasal Verbs consistem em um verbo + duas partículas (ex: get along with, look up to). Eles são SEMPRE inseparáveis. O objeto vem sempre no final!","context":"I get along with HER. (NÃO: I get her along with).","audio":"Phrasal Verbs com Três Palavras (Three-part Phrasal Verbs)","level":"B1","module":"Essential Phrasal Verbs II (Relationships)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Run into' vs. 'Meet'","secondary":"Run into = encontrar por acaso | Meet = encontrar de forma combinada","desc":"'Run into' significa encontrar alguém por acaso/sem planejar na rua. 'Meet' refere-se a encontros combinados ou a conhecer alguém pela 1ª vez.","context":"I RAN INTO John at the supermarket yesterday.","audio":"'Run into' vs. 'Meet'","level":"B1","module":"Essential Phrasal Verbs II (Relationships)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Would you mind...? / Could you do me a favor?","secondary":"/wʊd juː maɪnd/","desc":"Você se importaria de...? / Poderia me fazer um favor?","context":"Fórmulas polidas de solicitação.","audio":"Would you mind...? / Could you do me a favor?","level":"B1","module":"Asking for & Offering Favors"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Give a hand / Help out","secondary":"/ɡɪv ə hænd/","desc":"Dar uma mão (ajudar) / Dar um auxílio","context":"Colocações para ajuda prática.","audio":"Give a hand / Help out","level":"B1","module":"Asking for & Offering Favors"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Regra de 'Would you mind...?'","secondary":"Would you mind + Verb(-ing)...?","desc":"A estrutura 'Would you mind' exige o verbo principal obrigatoriamente no gerúndio (-ing). Lembre-se: responder 'No, not at all' significa 'Não me importo (Sim, eu ajudo!)'.","context":"WOULD YOU MIND OPENING the door? ➔ No, not at all! (Com prazer!).","audio":"A Regra de 'Would you mind...?'","level":"B1","module":"Asking for & Offering Favors"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Respostas Polidas para Favores","secondary":"Polite Acceptance / Polite Refusal","desc":"Para aceitar: 'I'd be happy to!', 'Sure thing!', 'Not at all!'. Para recusar educadamente: 'I'd love to, but I'm in a rush.'","context":"Could you help me? ➔ I'd be happy to help!","audio":"Respostas Polidas para Favores","level":"B1","module":"Asking for & Offering Favors"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Said that... / Told me that...","secondary":"/sed ðæt / toʊld miː ðæt/","desc":"Disse que... / Me disse que...","context":"Verbos de relato principal.","audio":"Said that... / Told me that...","level":"B1","module":"Reporting What Others Said (Reported Speech)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Backshifting","secondary":"/ˈbæk.ʃɪft.ɪŋ/","desc":"Regressão temporal","context":"Regra de recuo dos tempos verbais ao relatar o passado.","audio":"Backshifting","level":"B1","module":"Reporting What Others Said (Reported Speech)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Said vs. Told","secondary":"Say + (that) + Clause | Tell + Person + (that) + Clause","desc":"Usamos 'SAY' sem objeto indireto (He said that...). Usamos 'TELL' obrigatoriamente com a pessoa a quem se falou (He told ME that... / She told US that...).","context":"He SAID that he was tired. | He TOLD ME that he was tired.","audio":"Said vs. Told","level":"B1","module":"Reporting What Others Said (Reported Speech)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Regra do Backshifting (Recuo de Tempos)","secondary":"Present ➔ Past | Will ➔ Would | Can ➔ Could","desc":"Ao relatar no passado o que alguém disse, os tempos verbais costumam recuar um passo no tempo: Present Simple ➔ Past Simple | Present Perfect ➔ Past Perfect | Will ➔ Would.","context":"Direct: 'I am happy' ➔ Reported: He said he WAS happy.","audio":"Regra do Backshifting (Recuo de Tempos)","level":"B1","module":"Reporting What Others Said (Reported Speech)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Could you please...? / Would it be possible...?","secondary":"/kʊd juː pliːz/","desc":"Você poderia por favor...? / Seria possível...?","context":"Solicitações corporativas extremamente polidas.","audio":"Could you please...? / Would it be possible...?","level":"B1","module":"Polite Business English (Modal Verbs)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"May I suggest...? / I would appreciate it if...","secondary":"/meɪ aɪ səˈdʒest/","desc":"Posso sugerir...? / Eu agradeceria se...","context":"Propostas e pedidos diplomáticos em reuniões.","audio":"May I suggest...? / I would appreciate it if...","level":"B1","module":"Polite Business English (Modal Verbs)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Suavização de Pedidos com Modais","secondary":"Could/Would you + Verb base + please?","desc":"Em ambientes profissionais, evita-se o tom imperativo ou direto (ex: 'Send me the file'). Prefere-se suavizar com 'Could you', 'Would you' ou 'May I'.","context":"COULD YOU PLEASE FORWARD the email to the manager?","audio":"Suavização de Pedidos com Modais","level":"B1","module":"Polite Business English (Modal Verbs)"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Estrutura 'I would appreciate it if you could...'","secondary":"I would appreciate it if you could + Verb base","desc":"Uma das formas mais formais e elegantes de solicitar um favor no trabalho é conectar o verbo 'appreciate' com 'if you could'.","context":"I WOULD APPRECIATE IT IF YOU COULD review the proposal.","audio":"A Estrutura 'I would appreciate it if you could...'","level":"B1","module":"Polite Business English (Modal Verbs)"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Dear Mr./Ms. / Best regards","secondary":"/dɪər / best rɪˈɡɑːrdz/","desc":"Prezado(a) Sr.(a) / Atenciosamente","context":"Saudação de abertura e encerramento formal de e-mails.","audio":"Dear Mr./Ms. / Best regards","level":"B1","module":"Professional Emails & Formal Communication"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I am writing to... / Please find attached","secondary":"/aɪ æm ˈraɪtɪŋ tuː/","desc":"Escrevo para... / Em anexo você encontrará","context":"Frases de propósito e indicação de arquivos anexos.","audio":"I am writing to... / Please find attached","level":"B1","module":"Professional Emails & Formal Communication"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Estrutura do E-mail Profissional","secondary":"Greeting ➔ Purpose ➔ Attachments ➔ Closing ➔ Sign-off","desc":"1. Saudação (Dear [Name], / Dear Hiring Manager,) | 2. Propósito (I am writing to inquire/inform...) | 3. Detalhes (Please find attached...) | 4. Encerramento (I look forward to hearing from you.) | 5. Despedida (Best regards, / Sincerely,).","context":"Dear Ms. Green, I am writing to confirm our meeting. Best regards, John.","audio":"Estrutura do E-mail Profissional","level":"B1","module":"Professional Emails & Formal Communication"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'I look forward to' + Gerúndio (-ing)","secondary":"I look forward to + Verb(-ing)","desc":"A expressão formal de encerramento 'I look forward to' exige o verbo principal obrigatoriamente no GERÚNDIO (-ing) por causa da preposição 'to'!","context":"I look forward to HEARING from you soon. (NÃO: to hear).","audio":"'I look forward to' + Gerúndio (-ing)","level":"B1","module":"Professional Emails & Formal Communication"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Strengths & Weaknesses","secondary":"/streŋkθs & ˈwiːknəsɪz/","desc":"Pontos fortes e Pontos a melhorar","context":"Vocabulário central de entrevistas de trabalho.","audio":"Strengths & Weaknesses","level":"B1","module":"Job Interviews & Professional Pitch"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Track record / Problem-solving","secondary":"/træk ˈrekərd/","desc":"Histórico de realizações / Resolução de problemas","context":"Termos chave para valorizar o currículo.","audio":"Track record / Problem-solving","level":"B1","module":"Job Interviews & Professional Pitch"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Descrevendo Habilidades com 'Good at' + Gerúndio","secondary":"Subject + be + good at / skilled at + Verb(-ing)","desc":"Para descrever suas habilidades profissionais, use o adjetivo 'good at' ou 'skilled at' seguido de verbo no gerúndio (-ing).","context":"I am GOOD AT MANAGING high-pressure projects.","audio":"Descrevendo Habilidades com 'Good at' + Gerúndio","level":"B1","module":"Job Interviews & Professional Pitch"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Foco em Resultados: Past Simple + Dados","secondary":"Action Verb (Past) + Quantifiable Result","desc":"Ao relatar conquistas passadas na entrevista, combine verbos de ação no Past Simple com resultados mensuráveis.","context":"I INCREASED sales by 20% in my previous role.","audio":"Foco em Resultados: Past Simple + Dados","level":"B1","module":"Job Interviews & Professional Pitch"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I couldn't agree more / I see your point, but...","secondary":"/aɪ kʊdnt əˈɡriː mɔːr/","desc":"Concordo plenamente / Entendo seu ponto, mas...","context":"Marcadores de concordância e discordância elegante.","audio":"I couldn't agree more / I see your point, but...","level":"B1","module":"Meetings, Agreement & Disagreement"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I hear what you're saying, however...","secondary":"/aɪ hɪər wʌt jʊər ˈseɪɪŋ/","desc":"Compreendo o que diz, no entanto...","context":"Transição polida para apresentar contrapontos.","audio":"I hear what you're saying, however...","level":"B1","module":"Meetings, Agreement & Disagreement"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Concordância Absoluta: 'I couldn't agree more'","secondary":"I couldn't agree more = Concordo totalmente | I agree (NÃO: I am agree)","desc":"Apesar de ter estrutura negativa ('couldn't'), a expressão 'I couldn't agree more' significa 'Concordo 100% (não seria possível concordar mais)'. NUNCA diga 'I am agree'!","context":"That's a fantastic idea! I couldn't agree more.","audio":"Concordância Absoluta: 'I couldn't agree more'","level":"B1","module":"Meetings, Agreement & Disagreement"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Técnica da Discordância Suavizada (Softened Disagreement)","secondary":"Validation (I see your point) + Conjunction (but/however) + Counter-argument","desc":"Em reuniões corporativas em inglês, não se diz 'You are wrong'. Primeiro valida-se a ideia do interlocutor para depois introduzir o contraponto com 'but' ou 'however'.","context":"I see your point, BUT we don't have the budget right now.","audio":"Técnica da Discordância Suavizada (Softened Disagreement)","level":"B1","module":"Meetings, Agreement & Disagreement"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Look like / Sound like","secondary":"/lʊk laɪk / saʊnd laɪk/","desc":"Parecer (visualmente) / Parecer (ao ouvir)","context":"Descrições de percepção sensorial.","audio":"Look like / Sound like","level":"B1","module":"Describing Appearances & Sensations"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Feel as if / Taste like","secondary":"/fiːl æz ɪf/","desc":"Parecer como se / Ter gosto de","context":"Sensações táteis, degustativas e hipotéticas.","audio":"Feel as if / Taste like","level":"B1","module":"Describing Appearances & Sensations"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Look / Sound / Feel' + Adjetivo vs. Substantivo","secondary":"Look/Sound/Feel + Adjective | Look/Sound/Feel + LIKE + Noun","desc":"Se for seguido diretamente de ADJETIVO, use apenas o verbo (ex: It looks great). Se for seguido de SUBSTANTIVO, use 'like' (ex: It looks LIKE a movie).","context":"You LOOK tired. | You LOOK LIKE a doctor.","audio":"'Look / Sound / Feel' + Adjetivo vs. Substantivo","level":"B1","module":"Describing Appearances & Sensations"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Feels as if' + Oração","secondary":"It feels / looks + AS IF + Clause","desc":"Usamos 'as if' ou 'as though' quando a percepção é seguida por uma oração completa (sujeito + verbo).","context":"It FEELS AS IF we have been waiting for hours.","audio":"'Feels as if' + Oração","level":"B1","module":"Describing Appearances & Sensations"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Flight delay / Weather alert","secondary":"/flaɪt dɪˈleɪ/","desc":"Atraso de voo / Alerta meteorológico","context":"Vocabulário frequente em anúncios públicos de mídia.","audio":"Flight delay / Weather alert","level":"B1","module":"Understanding News & Public Announcements"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Has been canceled / Is expected to...","secondary":"/hæz biːn ˈkænsəld/","desc":"Foi cancelado / Espera-se que...","context":"Estruturas passivas em manchetes e alertas.","audio":"Has been canceled / Is expected to...","level":"B1","module":"Understanding News & Public Announcements"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Voz Passiva em Anúncios Públicos","secondary":"Subject + be (is/was/has been) + Past Participle","desc":"Em notícias e avisos públicos, o foco é o EVENTO e não quem o realizou. Por isso, usa-se a Voz Passiva (Be + Past Participle).","context":"Flight 302 HAS BEEN DELAYED. | Passengers ARE REQUESTED to remain seated.","audio":"A Voz Passiva em Anúncios Públicos","level":"B1","module":"Understanding News & Public Announcements"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Manchetes de Notícias (Headlines)","secondary":"Headline style: [Noun] + [Past Participle]","desc":"Nas manchetes de jornais, costuma-se omitir artigos e auxiliares para economizar espaço (ex: 'Plane delayed' em vez de 'The plane has been delayed').","context":"Road closed due to flood.","audio":"Manchetes de Notícias (Headlines)","level":"B1","module":"Understanding News & Public Announcements"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Piece of cake / Break a leg","secondary":"/piːs əv keɪk / breɪk ə leg/","desc":"Mamão com açúcar (muito fácil) / Boa sorte (no teatro/apresentações)","context":"Expressões idiomáticas de encorajamento e facilidade.","audio":"Piece of cake / Break a leg","level":"B1","module":"Cultural Idioms & Slang in Context"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Hit the nail on the head / Once in a blue moon","secondary":"/hɪt ðə neɪl ɑːn ðə hed/","desc":"Acertar na mosca / Uma vez a cada morte de bispo (raramente)","context":"Idiomas culturais de precisão e frequência.","audio":"Hit the nail on the head / Once in a blue moon","level":"B1","module":"Cultural Idioms & Slang in Context"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Natureza Figurativa dos Idiomas","secondary":"Idiom ➔ Figurative Meaning","desc":"Expressões idiomáticas NÃO devem ser traduzidas ao pé da letra. 'Break a leg' não significa quebrar a perna, mas sim desejar boa sorte!","context":"The test was A PIECE OF CAKE. (O teste foi muito fácil).","audio":"A Natureza Figurativa dos Idiomas","level":"B1","module":"Cultural Idioms & Slang in Context"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Once in a blue moon' como Advérbio","secondary":"Clause + once in a blue moon","desc":"'Once in a blue moon' funciona gramaticalmente como um advérbio de frequência (raramente / quase nunca) e costuma vir no final ou início da frase.","context":"I eat fast food ONCE IN A BLUE MOON.","audio":"'Once in a blue moon' como Advérbio","level":"B1","module":"Cultural Idioms & Slang in Context"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Autonomy & Fluency","secondary":"/ɔːˈtɑːnəmi & ˈfluːənsi/","desc":"Autonomia e Fluência","context":"Meta atingida ao concluir o nível B1.","audio":"Autonomy & Fluency","level":"B1","module":"🏆 B1 Final Challenge: Independence & Autonomy Simulation"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Comprehensive review","secondary":"/ˌkɑːmprɪˈhensɪv rɪˈvjuː/","desc":"Revisão abrangente","context":"Síntese dos 24 módulos pedagógicos.","audio":"Comprehensive review","level":"B1","module":"🏆 B1 Final Challenge: Independence & Autonomy Simulation"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Síntese Gramatical B1: Conditionals & Modals","secondary":"1st: If Present ➔ Will | 2nd: If Past ➔ Would","desc":"First Conditional (If + Present ➔ Will) = Possibilidade real. Second Conditional (If + Past ➔ Would) = Hipótese. Modais formais (Could/Would/May) = Cortesia e etiqueta corporativa.","context":"If I study, I will pass. | If I had money, I would travel.","audio":"Síntese Gramatical B1: Conditionals & Modals","level":"B1","module":"🏆 B1 Final Challenge: Independence & Autonomy Simulation"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Síntese de Verbos: Present Perfect & Phrasal Verbs","secondary":"Have/Has + Past Participle | Turn IT off","desc":"Present Perfect contrasta tempo indeterminado/contínuo com o Past Simple (tempo acabado). Phrasal Verbs com pronomes exigem o pronome no meio se forem separáveis.","context":"I have lived here for 5 years. | Pick them up!","audio":"Síntese de Verbos: Present Perfect & Phrasal Verbs","level":"B1","module":"🏆 B1 Final Challenge: Independence & Autonomy Simulation"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Supposed to be / Turn out","secondary":"/səˈpoʊzd tuː biː/","desc":"Deveria ser (expectativa) / Acontecer que, resultar em","context":"Expressões para comparar planos com a realidade.","audio":"Supposed to be / Turn out","level":"B2","module":"Expectations & Disappointments"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Fall short of expectations / Leave much to be desired","secondary":"/fɔːl ʃɔːrt əv/","desc":"Ficar aquém das expectativas / Deixar a desejar","context":"Crítica sutil em nível avançado.","audio":"Fall short of expectations / Leave much to be desired","level":"B2","module":"Expectations & Disappointments"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Expectativas com 'Be supposed to'","secondary":"Subject + was/were + supposed to + Verb base","desc":"Usa-se 'was/were supposed to' para indicar algo que estava planejado ou era esperado no passado, mas que NÃO aconteceu como previsto.","context":"The concert WAS SUPPOSED TO START at 8 PM, but it was delayed.","audio":"Expectativas com 'Be supposed to'","level":"B2","module":"Expectations & Disappointments"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Reviravoltas com 'It turned out (that)'","secondary":"It turned out that + Clause | Subject + turned out to be + Noun/Adj","desc":"'Turn out' indica o resultado final ou uma surpresa descoberta no desfecho de uma situação.","context":"It turned out that the rumor was true. | He turned out to be a great manager.","audio":"Reviravoltas com 'It turned out (that)'","level":"B2","module":"Expectations & Disappointments"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Not only... but also / Barely","secondary":"/nɑːt ˈoʊnli / ˈberli/","desc":"Não apenas... como também / Mal, quase não","context":"Estruturas de ênfase e escassez temporal.","audio":"Not only... but also / Barely","level":"B2","module":"Advanced Nuances of 'Only' & 'Barely'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Hardly / Merely / No sooner... than","secondary":"/ˈhɑːrdli / ˈmɪrli/","desc":"Quase não / Mero, apenas / Mal tinha... quando","context":"Advérbios restritivos e de sucessão imediata.","audio":"Hardly / Merely / No sooner... than","level":"B2","module":"Advanced Nuances of 'Only' & 'Barely'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Inversão Sintática com 'Not only'","secondary":"Not only + [Auxiliar (did/had/does)] + Subject + Verb...","desc":"Quando iniciamos uma oração com 'Not only' para dar ênfase formal, o verbo auxiliar deve vir ANTES do sujeito (ordem interrogativa na frase afirmativa!).","context":"NOT ONLY DID HE PASS the test, BUT HE ALSO got an A.","audio":"Inversão Sintática com 'Not only'","level":"B2","module":"Advanced Nuances of 'Only' & 'Barely'"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Sucessão Imediata: 'No sooner... than' & 'Hardly... when'","secondary":"No sooner had + Subject + Participle + THAN + Clause","desc":"'No sooner had + Subject + Past Participle... THAN' indica que um fato aconteceu imediatamente após outro.","context":"NO SOONER HAD I LEFT the house THAN it started to rain.","audio":"Sucessão Imediata: 'No sooner... than' & 'Hardly... when'","level":"B2","module":"Advanced Nuances of 'Only' & 'Barely'"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Despite / In spite of","secondary":"/dɪˈspaɪt / ɪn spaɪt əv/","desc":"Apesar de / A despeito de","context":"Conectores de concessão seguidos de substantivo ou gerúndio.","audio":"Despite / In spite of","level":"B2","module":"Subtle Criticism & Contradictions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Whereas / On the other hand","secondary":"/ˌwerˈæz/","desc":"Enquanto que / Por outro lado","context":"Conectores de contraste direto entre duas ideias.","audio":"Whereas / On the other hand","level":"B2","module":"Subtle Criticism & Contradictions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Despite / In Spite of + Noun / V(-ing)","secondary":"Despite + Noun / V(-ing) | Despite + the fact that + Clause","desc":"'Despite' e 'In spite of' são preposições. NUNCA coloque oração completa (sujeito+verbo) logo após eles, a menos que use a expressão 'the fact that'.","context":"DESPITE THE RAIN, we went out. (NÃO: Despite it was raining).","audio":"Despite / In Spite of + Noun / V(-ing)","level":"B2","module":"Subtle Criticism & Contradictions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Contraste com 'Whereas' & 'Even though'","secondary":"Even though / Whereas + Subject + Verb","desc":"'Even though' e 'Whereas' são conjunções subordinativas e DEVEM ser seguidos por oração completa (sujeito + verbo).","context":"EVEN THOUGH HE WAS TIRED, he kept working. | John is quiet, WHEREAS HIS BROTHER IS LOUD.","audio":"Contraste com 'Whereas' & 'Even though'","level":"B2","module":"Subtle Criticism & Contradictions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Break the ice / Bite the bullet","secondary":"/breɪk ðə aɪs/","desc":"Quebrar o gelo / Encarar uma situação difícil com coragem","context":"Metáforas de negociação e tomada de decisão.","audio":"Break the ice / Bite the bullet","level":"B2","module":"Figurative Language & Idioms"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Burn the midnight oil / Touch base","secondary":"/bɜːrn ðə ˈmɪdnaɪt ɔɪl/","desc":"Trabalhar até de madrugada / Fazer um contato rápido","context":"Idiomas e gírias corporativas sofisticadas.","audio":"Burn the midnight oil / Touch base","level":"B2","module":"Figurative Language & Idioms"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Metáforas Corporativas (Corporate Metaphors)","secondary":"Subject + Verb (conjugated idiom) + Object","desc":"No nível B2, o uso de idiomas metáforicos demonstra alta fluência. No entanto, é essencial usá-los no tempo verbal correto como qualquer outro verbo.","context":"We BIT THE BULLET (passado de bite) and accepted the terms.","audio":"Metáforas Corporativas (Corporate Metaphors)","level":"B2","module":"Figurative Language & Idioms"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Touch base with' + Person","secondary":"Touch base with + Person","desc":"'Touch base' significa entrar em contato rápido para atualização de informações. Deve ser seguido pela preposição 'with'.","context":"Let's TOUCH BASE WITH the legal team tomorrow.","audio":"'Touch base with' + Person","level":"B2","module":"Figurative Language & Idioms"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Hedging / Strategic pivot","secondary":"/ˈhedʒɪŋ/","desc":"Suavização diplomática / Mudança estratégica de rumo","context":"Técnicas de comunicação de alta liderança.","audio":"Hedging / Strategic pivot","level":"B2","module":"Advanced Executive English & Leadership"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"It appears that / I tend to believe","secondary":"/ɪt əˈpɪərz ðæt/","desc":"Parece que / Eu me inclino a acreditar","context":"Amofinadores de opinião executiva.","audio":"It appears that / I tend to believe","level":"B2","module":"Advanced Executive English & Leadership"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Técnica do Hedging (Suavização Diplomática)","secondary":"It seems/appears + that... | Subject + tend to + Verb","desc":"Líderes seniores evitam afirmações categóricas e agressivas (ex: 'This plan is wrong'). Usam-se verbos de atenuação como 'seem', 'appear', 'tend to' e advérbios como 'somewhat', 'relatively'.","context":"IT SEEMS THAT there is a misunderstanding. (Em vez de: You misunderstood).","audio":"A Técnica do Hedging (Suavização Diplomática)","level":"B2","module":"Advanced Executive English & Leadership"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Uso de Modais na Liderança: 'Might' & 'Could'","secondary":"We might want to consider + V(-ing)","desc":"Para sugerir mudanças de curso sem impor ordens ríspidas, utilizam-se modais de probabilidade.","context":"WE MIGHT WANT TO CONSIDER revising the quarterly goals.","audio":"Uso de Modais na Liderança: 'Might' & 'Could'","level":"B2","module":"Advanced Executive English & Leadership"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Further to our conversation / In response to","secondary":"/ˈfɜːrðər tuː/","desc":"Em continuação a nossa conversa / Em resposta a","context":"Frases de abertura formalíssimas para e-mails institucionais.","audio":"Further to our conversation / In response to","level":"B2","module":"Corporate Emails & Reports"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Comprehensive report / At your earliest convenience","secondary":"/ˌkɑːmprɪˈhensɪv/","desc":"Relatório detalhado/abrangente / Assim que possível (formal)","context":"Vocabulário de correspondência executiva.","audio":"Comprehensive report / At your earliest convenience","level":"B2","module":"Corporate Emails & Reports"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Fórmulas de Referência: 'Further to' & 'With reference to'","secondary":"Further to + [Substantivo], I am writing to...","desc":"Para dar continuidade a uma reunião ou chamada anterior por e-mail, usam-se 'Further to' ou 'With reference to' seguidos do substantivo.","context":"FURTHER TO OUR TELEPHONE CONVERSATION, I am sending the proposal.","audio":"Fórmulas de Referência: 'Further to' & 'With reference to'","level":"B2","module":"Corporate Emails & Reports"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Solicitações Formais de Prazo com 'At your earliest convenience'","secondary":"Please reply / confirm + at your earliest convenience","desc":"Em e-mails formais, evita-se usar 'ASAP' (As soon as possible) por ser considerado informal ou exigente. Prefere-se 'At your earliest convenience'.","context":"Please review the document AT YOUR EARLIEST CONVENIENCE.","audio":"Solicitações Formais de Prazo com 'At your earliest convenience'","level":"B2","module":"Corporate Emails & Reports"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Not feasible / Standpoint","secondary":"/nɑːt ˈfiːzəbl/","desc":"Inviável, não exequível / Ponto de vista, perspectiva","context":"Vocabulário de negociação e análise de viabilidade.","audio":"Not feasible / Standpoint","level":"B2","module":"Negotiations & Polite Disagreement"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"I'm afraid that... / With all due respect","secondary":"/aɪm əˈfreɪd ðæt/","desc":"Receio que... / Com todo o respeito","context":"Amofinadores para recusa diplomática de propostas.","audio":"I'm afraid that... / With all due respect","level":"B2","module":"Negotiations & Polite Disagreement"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Recusas Diplomáticas com 'I'm afraid that...'","secondary":"I'm afraid (that) + [Proposta] + is not feasible","desc":"Em negociações em inglês, raramente se usa 'No' ou 'I refuse'. A recusa é introduzida com 'I'm afraid (that)...' para demonstrar pesar polido.","context":"I'M AFRAID THAT a 20% discount IS NOT FEASIBLE for us.","audio":"Recusas Diplomáticas com 'I'm afraid that...'","level":"B2","module":"Negotiations & Polite Disagreement"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Análise por Perspectivas: 'From a... standpoint'","secondary":"From a + [financial / legal / technical] + standpoint","desc":"Para fundamentar uma objeção de forma técnica, usa-se a estrutura 'From a [adjetivo] standpoint' (ex: financial, operational, legal).","context":"FROM A FINANCIAL STANDPOINT, this investment makes sense.","audio":"Análise por Perspectivas: 'From a... standpoint'","level":"B2","module":"Negotiations & Polite Disagreement"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Moving on to / As you can see from this chart","secondary":"/ˈmuːvɪŋ ɑːn tuː/","desc":"Passando para / Como podem ver por este gráfico","context":"Frases de transição visual em apresentações.","audio":"Moving on to / As you can see from this chart","level":"B2","module":"Business Presentations & Executive Pitches"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"To illustrate this point / In conclusion","secondary":"/tʊ ˈɪləstreɪt ðɪs pɔɪnt/","desc":"Para ilustrar este ponto / Concluindo","context":"Sinalizadores de discurso em pitches e palestras.","audio":"To illustrate this point / In conclusion","level":"B2","module":"Business Presentations & Executive Pitches"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Frases de Transição em Apresentações","secondary":"Moving on to + [Novo Tópico] | This brings me to + [Ponto]","desc":"Para mudar de tópico sem romper a fluidez da fala, usam-se estruturas como 'Moving on to...', 'Turning our attention to...' ou 'This brings me to my next point'.","context":"THIS BRINGS ME TO MY NEXT POINT: our expansion plan.","audio":"Frases de Transição em Apresentações","level":"B2","module":"Business Presentations & Executive Pitches"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Conduzindo a Rodada de Perguntas (Q&A)","secondary":"I'd be happy / glad to take questions now","desc":"Para abrir espaço para perguntas: 'I'd be glad to take any questions now.' Para adiar respostas complexas: 'Let's address that during the Q&A session.'","context":"Thank you for your time. I'D BE GLAD TO TAKE ANY QUESTIONS.","audio":"Conduzindo a Rodada de Perguntas (Q&A)","level":"B2","module":"Business Presentations & Executive Pitches"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Allegedly / According to reports","secondary":"/əˈledʒɪdli/","desc":"Aparentemente, supostamente / De acordo com relatórios","context":"Linguagem jornalística de imparcialidade jurídica.","audio":"Allegedly / According to reports","level":"B2","module":"Journalistic English & News Analysis"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"It is claimed that / Sources reveal","secondary":"/ɪt ɪz kleɪmd ðæt/","desc":"Alega-se que / Fontes revelam","context":"Estruturas passivas de jornalismo investigativo.","audio":"It is claimed that / Sources reveal","level":"B2","module":"Journalistic English & News Analysis"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Uso do 'Allegedly' no Jornalismo","secondary":"Subject + allegedly + Verb","desc":"Jornalistas usam 'allegedly' (alegadamente/supostamente) para relatar acusações que ainda não foram provadas em tribunal, evitando processos por difamação.","context":"The suspect ALLEGEDLY FLED the country last night.","audio":"O Uso do 'Allegedly' no Jornalismo","level":"B2","module":"Journalistic English & News Analysis"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Voz Passiva Impessoal de Reportagem","secondary":"It is + [reported / claimed / rumored] + that + Clause","desc":"Para transmitir notícias de forma neutra sem citar fontes específicas, usam-se estruturas passivas como 'It is reported that...' ou 'He is believed to be...'.","context":"IT IS CLAIMED THAT negotiations have stalled.","audio":"Voz Passiva Impessoal de Reportagem","level":"B2","module":"Journalistic English & News Analysis"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Terms and conditions / Comply with","secondary":"/tɜːrmz ænd kənˈdɪʃnz/","desc":"Termos e condições / Estar em conformidade com (cumprir)","context":"Linguagem burocrática e contratual.","audio":"Terms and conditions / Comply with","level":"B2","module":"Public Notices, Documents & Bureaucracy"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Outlined in / Subject to approval","secondary":"/ˈaʊtlaɪnd ɪn/","desc":"Delineado/Descrevido em / Sujeito a aprovação","context":"Cláusulas de editais e termos de serviço.","audio":"Outlined in / Subject to approval","level":"B2","module":"Public Notices, Documents & Bureaucracy"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Verbo 'Comply with'","secondary":"Comply WITH + [Rules / Regulations / Laws]","desc":"Para indicar que uma pessoa ou empresa segue regras, leis ou regulamentos, usa-se 'comply' acompanhado obrigatoriamente da preposição 'WITH'.","context":"All staff must COMPLY WITH the safety regulations.","audio":"O Verbo 'Comply with'","level":"B2","module":"Public Notices, Documents & Bureaucracy"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Subject to' + Substantivo","secondary":"Subject TO + Noun","desc":"A expressão 'subject to' indica dependência condicional (ex: sujeito a alterações, sujeito à aprovação final).","context":"The schedule is SUBJECT TO CHANGE without prior notice.","audio":"'Subject to' + Substantivo","level":"B2","module":"Public Notices, Documents & Bureaucracy"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Colloquialism / Jargon","secondary":"/kəˈloʊkwiəlɪzəm/","desc":"Expressão coloquial / Jargão técnico/específico","context":"Categorias de fala nativa sem filtro.","audio":"Colloquialism / Jargon","level":"B2","module":"Media, Movies & Informal Slang without Subtitles"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Catch on / Binge-watch","secondary":"/kætʃ ɑːn/","desc":"Pegar o jeito (entender) / Maratonar séries","context":"Gírias modernas de consumo de mídia.","audio":"Catch on / Binge-watch","level":"B2","module":"Media, Movies & Informal Slang without Subtitles"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Gírias e Contrações de Filmes (Catching Nuances)","secondary":"Colloquial reduction ➔ Natural listening recognition","desc":"Em diálogos de filmes nativos, ocorrem elisões de consoantes e gírias de ritmo rápido como 'dunno' (don't know), 'gimme' (give me), 'watcha' (what are you).","context":"Whatcha doin'? ➔ What are you doing?","audio":"Gírias e Contrações de Filmes (Catching Nuances)","level":"B2","module":"Media, Movies & Informal Slang without Subtitles"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Verbo 'Catch on'","secondary":"Catch on to + Noun = entender | Catch on = virar moda","desc":"'Catch on' significa compreender uma ideia após algum tempo ou tornar-se popular na cultura pop.","context":"It took me a while to CATCH ON to the plot of the movie.","audio":"O Verbo 'Catch on'","level":"B2","module":"Media, Movies & Informal Slang without Subtitles"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Sustainability / Carbon footprint","secondary":"/səˌsteɪnəˈbɪləti/","desc":"Sustentabilidade / Pegada de carbono (impacto ambiental)","context":"Vocabulário ambientalista e corporativo moderno.","audio":"Sustainability / Carbon footprint","level":"B2","module":"Social & Environmental Issues"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Aging population / Renewable energy","secondary":"/ˈeɪdʒɪŋ pɑːpjuˈleɪʃn/","desc":"Envelhecimento populacional / Energia renovável","context":"Debates socioeconômicos globais.","audio":"Aging population / Renewable energy","level":"B2","module":"Social & Environmental Issues"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Causa e Efeito Global: 'Lead to' & 'Result in'","secondary":"Problem + lead to / result in + Consequences","desc":"Para conectar problemas sociais às suas consequências, utilizam-se os Phrasal Verbs 'lead to' e 'result in' seguidos de substantivo ou gerúndio.","context":"Deforestation LEADS TO climate change. | Excessive waste RESULTS IN pollution.","audio":"Causa e Efeito Global: 'Lead to' & 'Result in'","level":"B2","module":"Social & Environmental Issues"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Adjetivos de Urgência: 'Pressing' & 'Urgent'","secondary":"Pressing + issue / concern / problem","desc":"No nível B2, para descrever um problema grave que exige atenção imediata, usa-se o adjetivo 'pressing' (ex: a pressing issue).","context":"Global warming is a PRESSING ISSUE.","audio":"Adjetivos de Urgência: 'Pressing' & 'Urgent'","level":"B2","module":"Social & Environmental Issues"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Furthermore / Moreover","secondary":"/ˈfɜːrðərmɔːr / mɔːrˈoʊvər/","desc":"Além disso / Ademais (conectores de adição formal)","context":"Coesão textual acadêmica de adição.","audio":"Furthermore / Moreover","level":"B2","module":"Academic Connectors & Text Cohesion"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Nevertheless / In light of","secondary":"/ˌnevərðəˈles/","desc":"Não obstante, no entanto / Em vista de, diante de","context":"Conectores de concessão e evidência.","audio":"Nevertheless / In light of","level":"B2","module":"Academic Connectors & Text Cohesion"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Conectores de Adição Formal: 'Furthermore' & 'Moreover'","secondary":"[Argumento 1]. Furthermore, + [Argumento 2]","desc":"Para adicionar um argumento de peso em um ensaio ou discurso acadêmico, usam-se 'Furthermore' ou 'Moreover' seguidos de vírgula no início da oração.","context":"The strategy is cost-effective. FURTHERMORE, it saves time.","audio":"Conectores de Adição Formal: 'Furthermore' & 'Moreover'","level":"B2","module":"Academic Connectors & Text Cohesion"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Concessão Acadêmica: 'Nevertheless' & 'Nonetheless'","secondary":"[Fato A]. Nevertheless, + [Fato B de oposição]","desc":"'Nevertheless' é um sinônimo extremamente formal de 'However' (No entanto/Não obstante).","context":"The test was difficult. NEVERTHELESS, most students passed.","audio":"Concessão Acadêmica: 'Nevertheless' & 'Nonetheless'","level":"B2","module":"Academic Connectors & Text Cohesion"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"It can be argued that / It is undeniable that","secondary":"/ɪt kæn biː ˈɑːrɡjuːd ðæt/","desc":"Pode-se argumentar que / É inegável que","context":"Estruturas impessoais de defesa de tese.","audio":"It can be argued that / It is undeniable that","level":"B2","module":"Defending Thesis & Points of View"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"In light of the evidence / Assert that","secondary":"/əˈsɜːrt/","desc":"À luz das evidências / Afirmar/Sustentar categoricamente","context":"Vocabulário de debates formais e artigos acadêmicos.","audio":"In light of the evidence / Assert that","level":"B2","module":"Defending Thesis & Points of View"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Argumentação Impessoal em Ensaios","secondary":"It is + [argued / believed / established / undeniable] + THAT + Clause","desc":"Em textos de nível B2/C1, evita-se o uso excessivo de 'I think'. Prefere-se a Voz Passiva Impessoal para conferir autoridade científica à tese.","context":"IT IS UNDENIABLE THAT education changes lives.","audio":"Argumentação Impessoal em Ensaios","level":"B2","module":"Defending Thesis & Points of View"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Verbo 'Assert'","secondary":"Subject + assert that + Clause","desc":"'Assert' significa afirmar ou sustentar uma tese com convicção e evidências.","context":"The author ASSERTS THAT economic growth is slowing down.","audio":"O Verbo 'Assert'","level":"B2","module":"Defending Thesis & Points of View"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Convey a sense of / Underlying theme","secondary":"/kənˈveɪ/","desc":"Transmitir a sensação de / Tema subjacente/profundo","context":"Vocabulário de crítica literária e análise textual.","audio":"Convey a sense of / Underlying theme","level":"B2","module":"Literary Analysis & Reading Native Texts"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Employ metaphors / Narrative voice","secondary":"/ɪmˈplɔɪ ˈmetəfɔːrz/","desc":"Empregar/Usar metáforas / Voz narrativa","context":"Termos técnicos de teoria literária.","audio":"Employ metaphors / Narrative voice","level":"B2","module":"Literary Analysis & Reading Native Texts"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"O Verbo 'Convey' em Análise de Texto","secondary":"Author / Passage + convey + [Emotion / Meaning]","desc":"Usa-se 'convey' em vez de 'show' ou 'tell' para descrever como um autor transmite sentimentos, ideias ou atmosferas em um texto.","context":"The poem CONVEYS A SENSE OF MELANCHOLY.","audio":"O Verbo 'Convey' em Análise de Texto","level":"B2","module":"Literary Analysis & Reading Native Texts"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"'Employ' como uso de recursos estilísticos","secondary":"Author + employ + [Literary Device / Metaphor / Symbolism]","desc":"Em análises literárias, 'employ' significa utilizar conscientemente figuras de linguagem ou técnicas de escrita.","context":"Shakespeare EMPLOYS SYMBOLISM to highlight the tragedy.","audio":"'Employ' como uso de recursos estilísticos","level":"B2","module":"Literary Analysis & Reading Native Texts"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Serve as a catalyst / Stem from","secondary":"/sɜːrv æz ə ˈkætəlɪst/","desc":"Servir como um catalisador (impulsionador) / Derivar de, originar-se de","context":"Conexões causais profundas em debates.","audio":"Serve as a catalyst / Stem from","level":"B2","module":"Advanced Cause, Effect & Catalysts"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Give rise to / As a consequence of","secondary":"/ɡɪv raɪz tuː/","desc":"Dar origem a / Como consequência de","context":"Relações de efeito em estudos de caso.","audio":"Give rise to / As a consequence of","level":"B2","module":"Advanced Cause, Effect & Catalysts"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Causas Originais: 'Stem from'","secondary":"Effect + stem from + Root Cause","desc":"Usa-se 'stem from' para explicar a origem primária de um fenómeno ou problema presente.","context":"His anxiety STEMS FROM past traumatic experiences.","audio":"Causas Originais: 'Stem from'","level":"B2","module":"Advanced Cause, Effect & Catalysts"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Ação Catalisadora: 'Serve as a catalyst for'","secondary":"Event + serve as a catalyst for + Transformation","desc":"Para descrever um evento que acelerou dramaticamente uma transformação social ou econômica, usa-se 'serve as a catalyst for'.","context":"The new law SERVED AS A CATALYST FOR clean energy adoption.","audio":"Ação Catalisadora: 'Serve as a catalyst for'","level":"B2","module":"Advanced Cause, Effect & Catalysts"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Flat / Apartment","secondary":"/flæt / əˈpɑːrtmənt/","desc":"Apartamento (UK) / Apartamento (US)","context":"Diferenças de vocabulário entre variantes de inglês.","audio":"Flat / Apartment","level":"B2","module":"Global English Dialects & Accents"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Lorry / Truck / Mate","secondary":"/ˈlɔːri / trʌk/","desc":"Caminhão (UK) / Caminhão (US) / Amigo, parceiro (UK/AU)","context":"Termos regionais do cotidiano.","audio":"Lorry / Truck / Mate","level":"B2","module":"Global English Dialects & Accents"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Diferenças Gramaticais: 'Have got' vs. 'Have'","secondary":"UK: Subject + have got + Object | US: Subject + have + Object","desc":"No inglês britânico, é muito comum usar 'I've got' para posse no presente. No americano, prefere-se 'I have'.","context":"UK: I've got a new car. | US: I have a new car.","audio":"Diferenças Gramaticais: 'Have got' vs. 'Have'","level":"B2","module":"Global English Dialects & Accents"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Ortografia: -ize vs. -ise & -or vs. -our","secondary":"US: color, organize | UK: colour, organise","desc":"EUA usam -ize e -or (organize, color). Reino Unido usa -ise e -our (organise, colour). Ambas são corretas no padrão internacional.","context":"US: Labor and Honor. | UK: Labour and Honour.","audio":"Ortografia: -ize vs. -ise & -or vs. -our","level":"B2","module":"Global English Dialects & Accents"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Sizzle / Whisper / Clatter","secondary":"/ˈsɪzl/","desc":"Chiar (fritar) / Sussurrar / Barulho de objetos colidindo","context":"Verbos de som e descrição sensorial avançada.","audio":"Sizzle / Whisper / Clatter","level":"B2","module":"Onomatopoeia, Sound Effects & Vivid Descriptions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Mumble / Creak / Buzz","secondary":"/ˈmʌmbl/","desc":"Resmungar, falar entre os dentes / Ranger / Zumbir","context":"Sensações auditivas em narrativa fluida.","audio":"Mumble / Creak / Buzz","level":"B2","module":"Onomatopoeia, Sound Effects & Vivid Descriptions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Sensações Auditivas na Narrativa","secondary":"Subject + Sound Verb (whispered / mumbled) + Clause","desc":"No nível B2/C1, evita-se usar verbos genéricos como 'said softly' ou 'made a noise'. Substituem-se por verbos de som específicos como 'whispered', 'mumbled', 'clattered'.","context":"He WHISPERED the password in her ear.","audio":"Sensações Auditivas na Narrativa","level":"B2","module":"Onomatopoeia, Sound Effects & Vivid Descriptions"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Participios como Adjetivos de Som","secondary":"The + Sound Verb(-ing) + Noun","desc":"Os verbos de som podem vir no particípio presente (-ing) para descrever a atmosfera contínua de um ambiente.","context":"The SIZZLING bacon smelled delicious. | The CREAKING door scared us.","audio":"Participios como Adjetivos de Som","level":"B2","module":"Onomatopoeia, Sound Effects & Vivid Descriptions"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Work-life balance / Mindfulness","secondary":"/wɜːrk laɪf ˈbæləns/","desc":"Equilíbrio entre vida pessoal e trabalho / Atenção plena","context":"Conceitos modernos de saúde mental e estilo de vida.","audio":"Work-life balance / Mindfulness","level":"B2","module":"Cultural Etiquette & Philosophical Concepts"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Cultural intelligence / Cultural faux pas","secondary":"/ˈkʌltʃərəl ɪnˈtelɪdʒəns/","desc":"Inteligência cultural / Gafe cultural","context":"Etiqueta e diplomacia interpessoal global.","audio":"Cultural intelligence / Cultural faux pas","level":"B2","module":"Cultural Etiquette & Philosophical Concepts"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Discussão de Conceitos Abstratos","secondary":"Practicing + [Substantivo Abstrato] + leads to / enhances + [Benefício]","desc":"Para articular visões filosóficas e culturais avançadas, combinam-se substantivos abstratos com conectores de utilidade social.","context":"PRACTICING MINDFULNESS ENHANCES emotional resilience.","audio":"Discussão de Conceitos Abstratos","level":"B2","module":"Cultural Etiquette & Philosophical Concepts"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"A Expressão 'Commit a faux pas'","secondary":"Commit a + cultural faux pas","desc":"'Faux pas' (do francês, incorporado ao inglês) significa uma gafe social ou violação de etiqueta. Usa-se com o verbo 'commit'.","context":"He COMMITTED A CULTURAL FAUX PAS by wearing shoes indoors.","audio":"A Expressão 'Commit a faux pas'","level":"B2","module":"Cultural Etiquette & Philosophical Concepts"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Capstone project / Fluency Certification","secondary":"/ˈkæpstoʊn/","desc":"Projeto de conclusão / Certificação de fluência","context":"Avaliação final do nível Upper-Intermediate B2.","audio":"Capstone project / Fluency Certification","level":"B2","module":"🏆 The Great B2 Final Challenge: Capstone Project & Fluency Assessment"},{"cat":"vocab","catLabel":"VOCABULÁRIO","primary":"Mastery / Advanced proficiency","secondary":"/ˈmæstəri/","desc":"Domínio completo / Proficiência avançada","context":"Nível final atingido no curso.","audio":"Mastery / Advanced proficiency","level":"B2","module":"🏆 The Great B2 Final Challenge: Capstone Project & Fluency Assessment"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Revisão Geral de Inversão & Modais Avançados","secondary":"Not only + Aux + S + V | I'm afraid that... is not feasible","desc":"Inversão sintática (Not only did he... / Hardly had I...), modais de cortesia (Could, Would, May) e linguagem diplomática de liderança (Hedging).","context":"Not only did he succeed, but he also inspired everyone.","audio":"Revisão Geral de Inversão & Modais Avançados","level":"B2","module":"🏆 The Great B2 Final Challenge: Capstone Project & Fluency Assessment"},{"cat":"grammar","catLabel":"GRAMÁTICA","primary":"Revisão Geral de Conectores & Passiva Impessoal","secondary":"Despite + Noun | It can be argued that...","desc":"Conectores formais (Furthermore, Nevertheless, Whereas, Despite) e estruturas passivas impessoais de tese (It is undeniable that...).","context":"Despite the challenges, it is undeniable that progress was made.","audio":"Revisão Geral de Conectores & Passiva Impessoal","level":"B2","module":"🏆 The Great B2 Final Challenge: Capstone Project & Fluency Assessment"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Wake up","secondary":"Acordar (despertar)","desc":"Indica o momento em que a pessoa abre os olhos e deixa de dormir.","context":"Ex: \"I usually wake up at 6:30 AM every morning.\" (Eu geralmente me acordo às 6h30 todas as manhãs.)","audio":"Wake up","level":"A1","module":"Module 1: Home Routines & Waking Up"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Get up","secondary":"Levantar-se (da cama ou cadeira)","desc":"Refere-se à ação de sair da cama ou ficar de pé após ter acordado.","context":"Ex: \"He gets up at 7:00 AM on weekdays.\" (Ele se levanta às 7h nos dias de semana.)","audio":"Get up","level":"A1","module":"Module 1: Home Routines & Waking Up"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Dress up","secondary":"Arrumar-se / Vestir roupa elegante ou fantasia","desc":"Usado quando alguém veste roupas mais elegantes para um evento ou se fantasia.","context":"Ex: \"We need to dress up for the wedding tonight.\" (Nós precisamos nos arrumar para o casamento hoje à noite.)","audio":"Dress up","level":"A1","module":"Module 1: Home Routines & Waking Up"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Lie down","secondary":"Deitar-se (para descansar)","desc":"Ação de colocar o corpo na horizontal para descansar ou dormir um pouco.","context":"Ex: \"I feel dizzy, I need to lie down for a minute.\" (Estou tonto, preciso me deitar por um minuto.)","audio":"Lie down","level":"A1","module":"Module 1: Home Routines & Waking Up"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Sleep in","secondary":"Dormir até mais tarde","desc":"Ação de dormir além do horário habitual, geralmente nos fins de semana.","context":"Ex: \"On Sundays, I love to sleep in until 10 AM.\" (Aos domingos, eu adoro dormir até mais tarde, até as 10h.)","audio":"Sleep in","level":"A1","module":"Module 1: Home Routines & Waking Up"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Wash up","secondary":"Lavar as mãos/rosto ou lavar a louça","desc":"Significa lavar as mãos e o rosto antes de comer ou lavar a louça pós-refeição.","context":"Ex: \"Go wash up before dinner, kids!\" (Vão lavar as mãos antes do jantar, crianças!)","audio":"Wash up","level":"A1","module":"Module 1: Home Routines & Waking Up"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Put on","secondary":"Vestir / Colocar (roupa, sapatos, maquiagem)","desc":"Ação de colocar uma peça de vestuário ou acessório no corpo.","context":"Ex: \"Put on your coat, it's freezing outside!\" (Vista seu casaco, está congelando lá fora!)","audio":"Put on","level":"A1","module":"Module 2: Clothing, Dressing & Appearance"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Take off","secondary":"Tirar (roupa ou sapatos)","desc":"O oposto de 'put on'; despir uma roupa ou tirar os sapatos.","context":"Ex: \"Please take off your shoes at the door.\" (Por favor, tire seus sapatos na porta.)","audio":"Take off","level":"A1","module":"Module 2: Clothing, Dressing & Appearance"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Try on","secondary":"Experimentar roupa","desc":"Vestir uma roupa na loja para verificar se o tamanho e o caimento servem.","context":"Ex: \"Can I try on this blue dress, please?\" (Posso experimentar este vestido azul, por favor?)","audio":"Try on","level":"A1","module":"Module 2: Clothing, Dressing & Appearance"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Hang up","secondary":"Pendurar (roupas no cabide/varal)","desc":"Colocar as roupas penduradas em cabides ou no armário.","context":"Ex: \"Please hang up your shirt in the closet.\" (Por favor, pendure sua camisa no armário.)","audio":"Hang up","level":"A1","module":"Module 2: Clothing, Dressing & Appearance"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Zip up","secondary":"Fechar o zíper","desc":"Puxar o fecho ecler (zíper) para fechar uma jaqueta ou calça.","context":"Ex: \"Zip up your jacket, the wind is cold.\" (Feche o zíper da sua jaqueta, o vento está frio.)","audio":"Zip up","level":"A1","module":"Module 2: Clothing, Dressing & Appearance"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Fit in","secondary":"Servir / Encaixar-se (em uma roupa ou grupo)","desc":"Refere-se ao caimento adequado da roupa ou a sentir-se parte de um grupo.","context":"Ex: \"These jeans don't fit in my suitcase.\" (Esta calça jeans não cabe na minha mala.)","audio":"Fit in","level":"A1","module":"Module 2: Clothing, Dressing & Appearance"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Go out","secondary":"Sair (para passear, divertir-se ou jantar)","desc":"Sair de casa para lazer, compras ou encontros sociais.","context":"Ex: \"Let's go out for dinner tonight!\" (Vamos sair para jantar hoje à noite!)","audio":"Go out","level":"A1","module":"Module 3: Physical Movement & Social Basics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Come in","secondary":"Entrar (em uma sala ou casa)","desc":"Convidar alguém ou mover-se para o interior de um ambiente.","context":"Ex: \"Knock on the door before you come in.\" (Bata na porta antes de entrar.)","audio":"Come in","level":"A1","module":"Module 3: Physical Movement & Social Basics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Sit down","secondary":"Sentar-se","desc":"Ação física de abaixar o corpo e sentar em uma cadeira ou sofá.","context":"Ex: \"Take a seat and sit down.\" (Pegue uma cadeira e sente-se.)","audio":"Sit down","level":"A1","module":"Module 3: Physical Movement & Social Basics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Stand up","secondary":"Ficar de pé / Levantar-se","desc":"Levantar-se da posição sentada para a posição ereta.","context":"Ex: \"Everyone stood up when the judge entered.\" (Todos se levantaram quando o juiz entrou.)","audio":"Stand up","level":"A1","module":"Module 3: Physical Movement & Social Basics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Move in","secondary":"Mudar-se para uma casa nova","desc":"Iniciar a residência em um novo imóvel ou apartamento.","context":"Ex: \"We are moving in to our new apartment next Monday.\" (Nós vamos nos mudar para o nosso apartamento novo na próxima segunda-feira.)","audio":"Move in","level":"A1","module":"Module 3: Physical Movement & Social Basics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Walk away","secondary":"Afastar-se / Ir embora caminhando","desc":"Caminhar para longe de uma pessoa, discussão ou local.","context":"Ex: \"Don't just walk away when I am talking to you!\" (Não vá embora simplesmente quando estou falando com você!)","audio":"Walk away","level":"A1","module":"Module 3: Physical Movement & Social Basics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Pay for","secondary":"Pagar por algo","desc":"Entregar dinheiro em troca de um bem, produto ou serviço.","context":"Ex: \"How much did you pay for that smartphone?\" (Quanto você pagou por aquele smartphone?)","audio":"Pay for","level":"A1","module":"Module 4: Shopping, Money & Transactions"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Save up","secondary":"Juntar dinheiro / Economizar para uma meta","desc":"Acumular dinheiro gradualmente para comprar algo caro no futuro.","context":"Ex: \"I am saving up to buy a new car.\" (Estou juntando dinheiro para comprar um carro novo.)","audio":"Save up","level":"A1","module":"Module 4: Shopping, Money & Transactions"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Pay back","secondary":"Devolver dinheiro emprestado / Reembolsar","desc":"Devolver uma quantia que lhe foi emprestada anteriormente.","context":"Ex: \"I will pay you back as soon as I get my salary.\" (Eu vou te pagar de volta assim que receber meu salário.)","audio":"Pay back","level":"A1","module":"Module 4: Shopping, Money & Transactions"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Sell out","secondary":"Esgotar o estoque de um produto","desc":"Vender todas as unidades disponíveis de um item ou ingresso.","context":"Ex: \"The concert tickets sold out in ten minutes!\" (Os ingressos do show se esgotaram em dez minutos!)","audio":"Sell out","level":"A1","module":"Module 4: Shopping, Money & Transactions"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Shop around","secondary":"Pesquisar preços em várias lojas","desc":"Comparar preços e condições em estabelecimentos diferentes antes de comprar.","context":"Ex: \"Don't buy the first one you see; shop around first!\" (Não compre o primeiro que vir; pesquise os preços antes!)","audio":"Shop around","level":"A1","module":"Module 4: Shopping, Money & Transactions"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Rip off","secondary":"Cobrar um preço abusivo / Passar a perna","desc":"Cobrar muito mais caro do que um produto ou serviço realmente vale.","context":"Ex: \"That taxi driver ripped us off!\" (Aquele taxista cobrou um preço abusivo da gente!)","audio":"Rip off","level":"A1","module":"Module 4: Shopping, Money & Transactions"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Eat out","secondary":"Comer fora (em restaurante)","desc":"Fazer uma refeição em um restaurante ou lanchonete em vez de cozinhar em casa.","context":"Ex: \"We are too tired to cook, let's eat out.\" (Estamos cansados demais para cozinhar, vamos comer fora.)","audio":"Eat out","level":"A1","module":"Module 5: Food, Cooking & Dining Out"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Drink up","secondary":"Beber tudo / Esbanjar a bebida","desc":"Terminar completamente a bebida no copo.","context":"Ex: \"Drink up your juice, we have to leave now!\" (Beba todo o seu suco, nós temos que ir embora agora!)","audio":"Drink up","level":"A1","module":"Module 5: Food, Cooking & Dining Out"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Warm up","secondary":"Esquentar comida no micro-ondas/fogão","desc":"Reaquecer uma refeição previamente pronta.","context":"Ex: \"I will warm up the leftover pizza for lunch.\" (Vou esquentar a sobra de pizza para o almoço.)","audio":"Warm up","level":"A1","module":"Module 5: Food, Cooking & Dining Out"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Chop up","secondary":"Picar comida em pedacinhos","desc":"Cortar ingredientes como vegetais ou carnes em pequenos pedaços com faca.","context":"Ex: \"Please chop up the onions and carrots.\" (Por favor, pique as cebolas e as cenouras.)","audio":"Chop up","level":"A1","module":"Module 5: Food, Cooking & Dining Out"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Cut down on","secondary":"Reduzir o consumo de algum alimento","desc":"Diminuir a ingestão de açúcar, café, sal ou gordura por saúde.","context":"Ex: \"My doctor told me to cut down on sugar.\" (Meu médico me disse para reduzir o açúcar.)","audio":"Cut down on","level":"A1","module":"Module 5: Food, Cooking & Dining Out"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Serve up","secondary":"Servir a refeição no prato","desc":"Colocar a comida pronta nos pratos da mesa.","context":"Ex: \"Dinner is ready! I am serving it up now.\" (O jantar está pronto! Estou servindo os pratos agora.)","audio":"Serve up","level":"A1","module":"Module 5: Food, Cooking & Dining Out"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Turn on","secondary":"Ligar (aparelho eletrônico, luz)","desc":"Acionar a energia ou chave de um dispositivo eletrônico ou lâmpada.","context":"Ex: \"Turn on the light, it's too dark in here.\" (Ligue a luz, está muito escuro aqui dentro.)","audio":"Turn on","level":"A1","module":"Module 6: Basic Communication & Technology"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Turn off","secondary":"Desligar (aparelho, luz)","desc":"Desativar a energia de um aparelho eletrônico.","context":"Ex: \"Don't forget to turn off the TV before going to bed.\" (Não se esqueça de desligar a TV antes de ir dormir.)","audio":"Turn off","level":"A1","module":"Module 6: Basic Communication & Technology"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Call back","secondary":"Retornar a ligação telefônica","desc":"Ligar de volta para alguém que te telefonou anteriormente.","context":"Ex: \"I'm busy right now, can I call you back later?\" (Estou ocupado agora, posso te ligar de volta mais tarde?)","audio":"Call back","level":"A1","module":"Module 6: Basic Communication & Technology"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Pick up","secondary":"Atender o telefone","desc":"Atender a uma chamada telefônica em vez de deixar tocar.","context":"Ex: \"I called him three times, but he didn't pick up.\" (Liguei para ele três vezes, mas ele não atendeu.)","audio":"Pick up","level":"A1","module":"Module 6: Basic Communication & Technology"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Hang up","secondary":"Desligar a ligação telefônica","desc":"Encerrar uma chamada telefônica (antigamente pendurava-se o fone no gancho).","context":"Ex: \"Don't hang up on me, I haven't finished talking!\" (Não desligue na minha cara, eu não terminei de falar!)","audio":"Hang up","level":"A1","module":"Module 6: Basic Communication & Technology"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Log in / Log on","secondary":"Fazer login / Entrar em um sistema com senha","desc":"Inserir usuário e senha para acessar uma conta ou computador.","context":"Ex: \"You need your password to log in to your email.\" (Você precisa da sua senha para fazer login no seu e-mail.)","audio":"Log in / Log on","level":"A1","module":"Module 6: Basic Communication & Technology"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Get on","secondary":"Embarcar (ônibus, trem, avião, navio)","desc":"Subir em meios de transporte coletivo onde se pode andar de pé.","context":"Ex: \"We got on the bus at the central station.\" (Nós embarcamos no ônibus na estação central.)","audio":"Get on","level":"A2","module":"Module 7: Transit, Vehicles & Travel"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Get off","secondary":"Desembarcar (ônibus, trem, avião, navio)","desc":"Descer de um veículo coletivo.","context":"Ex: \"You need to get off at the next stop.\" (Você precisa desembarcar no próximo ponto.)","audio":"Get off","level":"A2","module":"Module 7: Transit, Vehicles & Travel"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Check in","secondary":"Fazer o check-in (hotel/aeroporto)","desc":"Registrar a chegada no hotel ou despachar malas e pegar bilhete no aeroporto.","context":"Ex: \"We must check in two hours before our flight.\" (Nós devemos fazer o check-in duas horas antes do nosso voo.)","audio":"Check in","level":"A2","module":"Module 7: Transit, Vehicles & Travel"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Check out","secondary":"Fazer o check-out do hotel / Conferir","desc":"Pagar a conta e devolver as chaves do hotel na saída.","context":"Ex: \"We checked out of the hotel at 11 AM.\" (Fizemos o check-out do hotel às 11h.)","audio":"Check out","level":"A2","module":"Module 7: Transit, Vehicles & Travel"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Drop off","secondary":"Deixar alguém de carro em algum lugar","desc":"Levar alguém de carro até certo ponto e deixá-lo lá.","context":"Ex: \"Can you drop me off at the train station?\" (Você pode me deixar na estação de trem?)","audio":"Drop off","level":"A2","module":"Module 7: Transit, Vehicles & Travel"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Set off / Set out","secondary":"Partir / Iniciar uma viagem","desc":"Dar início a uma jornada ou percurso de viagem.","context":"Ex: \"We set off early in the morning to avoid traffic.\" (Nós partimos bem cedo pela manhã para evitar o trânsito.)","audio":"Set off / Set out","level":"A2","module":"Module 7: Transit, Vehicles & Travel"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Clean up","secondary":"Fazer uma limpeza geral / Limpar a sujeira","desc":"Organizar e tirar a sujeira de um ambiente completamente.","context":"Ex: \"Please clean up your room before going out.\" (Por favor, limpe seu quarto antes de sair.)","audio":"Clean up","level":"A2","module":"Module 8: Cleaning, Housework & Organizing"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Throw away / Throw out","secondary":"Jogar fora no lixo","desc":"Descartar coisas velhas ou inúteis na lixeira.","context":"Ex: \"Don't throw away those old boxes, I need them.\" (Não jogue fora aquelas caixas velhas, eu preciso delas.)","audio":"Throw away / Throw out","level":"A2","module":"Module 8: Cleaning, Housework & Organizing"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Clear out","secondary":"Esvaziar e desentulhar um espaço","desc":"Remover coisas desnecessárias de uma gaveta, armário ou garagem.","context":"Ex: \"I need to clear out my garage this weekend.\" (Preciso desentulhar minha garagem neste fim de semana.)","audio":"Clear out","level":"A2","module":"Module 8: Cleaning, Housework & Organizing"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Put away","secondary":"Guardar as coisas em seu devido lugar","desc":"Retornar objetos para seus lugares originais (ex: guardar compras/brinquedos).","context":"Ex: \"Put away your toys after playing.\" (Guarde seus brinquedos depois de brincar.)","audio":"Put away","level":"A2","module":"Module 8: Cleaning, Housework & Organizing"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Tidy up","secondary":"Arrumar / Dar uma ajeitada rápida","desc":"Colocar as coisas em ordem rápida para deixar o ambiente limpo.","context":"Ex: \"Let's tidy up the living room before the guests arrive.\" (Vamos dar uma ajeitada na sala antes que os convidados cheguem.)","audio":"Tidy up","level":"A2","module":"Module 8: Cleaning, Housework & Organizing"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Wipe off","secondary":"Limpar com pano (passar pano)","desc":"Passar pano umedecido para tirar poeira ou líquidos da mesa.","context":"Ex: \"Wipe off the table after lunch, please.\" (Passe um pano na mesa depois do almoço, por favor.)","audio":"Wipe off","level":"A2","module":"Module 8: Cleaning, Housework & Organizing"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Grow up","secondary":"Crescer / Criar-se (passar da infância à fase adulta)","desc":"O desenvolvimento físico e de maturidade da criança até ser adulto.","context":"Ex: \"I grew up in a small town in Canada.\" (Eu cresci em uma pequena cidade no Canadá.)","audio":"Grow up","level":"A2","module":"Module 9: Family, Growth & Life Stages"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Bring up","secondary":"Criar/Educar filhos ou Introduzir um assunto","desc":"Maternar/paternar criando uma criança ou trazer um tema à tona na conversa.","context":"Ex: \"She was brought up by her grandparents.\" (Ela foi criada pelos avós dela.)","audio":"Bring up","level":"A2","module":"Module 9: Family, Growth & Life Stages"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Pass away","secondary":"Falecer (eufemismo carinhoso para morrer)","desc":"Maneira educada e empática de dizer que alguém morreu.","context":"Ex: \"His grandfather passed away peacefully at age 90.\" (O avô dele faleceu pacificamente aos 90 anos.)","audio":"Pass away","level":"A2","module":"Module 9: Family, Growth & Life Stages"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Settle down","secondary":"Criar raízes / Estabilizar a vida (casar/comprar casa)","desc":"Decidir ter uma vida calma, casar-se e morar fixamente em um lugar.","context":"Ex: \"After years of traveling, he decided to settle down in Spain.\" (Após anos viajando, ele decidiu criar raízes na Espanha.)","audio":"Settle down","level":"A2","module":"Module 9: Family, Growth & Life Stages"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Take after","secondary":"Puxar a alguém da família (aparência ou gênio)","desc":"Ter traços de personalidade ou físicos semelhantes aos pais ou parentes.","context":"Ex: \"She takes after her mother in temperament.\" (Ela puxou à mãe dela no gênio/temperamento.)","audio":"Take after","level":"A2","module":"Module 9: Family, Growth & Life Stages"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Look back (on)","secondary":"Olhar para trás / Relembrar o passado","desc":"Pensar ou refletir sobre eventos passados da própria vida.","context":"Ex: \"When I look back on my childhood, I feel happy.\" (Quando olho para trás e lembro da minha infância, me sinto feliz.)","audio":"Look back (on)","level":"A2","module":"Module 9: Family, Growth & Life Stages"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Get along with","secondary":"Dar-se bem com alguém","desc":"Ter uma relação harmoniosa e sem brigas com outra pessoa.","context":"Ex: \"I get along very well with my neighbors.\" (Eu me dou muito bem com meus vizinhos.)","audio":"Get along with","level":"A2","module":"Module 10: Friendship, Dating & Social Dynamics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Break up","secondary":"Terminar um relacionamento amoroso","desc":"Encerrar um namoro ou casamento.","context":"Ex: \"They broke up after dating for two years.\" (Eles terminaram depois de namorar por dois anos.)","audio":"Break up","level":"A2","module":"Module 10: Friendship, Dating & Social Dynamics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Ask out","secondary":"Convidar alguém para um encontro amoroso","desc":"Convidar romanticamente uma pessoa para jantar ou ir ao cinema.","context":"Ex: \"He finally asked her out for coffee.\" (Ele finalmente a convidou para sair e tomar um café.)","audio":"Ask out","level":"A2","module":"Module 10: Friendship, Dating & Social Dynamics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Hang out","secondary":"Passar tempo junto / Curtir com amigos","desc":"Passar tempo de lazer de forma relaxada com amigos.","context":"Ex: \"We usually hang out at the mall on weekends.\" (Nós geralmente passamos o tempo juntos no shopping nos fins de semana.)","audio":"Hang out","level":"A2","module":"Module 10: Friendship, Dating & Social Dynamics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Make up","secondary":"Fazer as pazes após uma briga","desc":"Reconciliar-se e perdoar o outro após um desentendimento.","context":"Ex: \"They had an argument, but they quickly made up.\" (Eles tiveram uma discussão, mas logo fizeram as pazes.)","audio":"Make up","level":"A2","module":"Module 10: Friendship, Dating & Social Dynamics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Run into","secondary":"Encontrar alguém por acaso na rua","desc":"Esbarrar não planejado com um conhecido em local público.","context":"Ex: \"I ran into an old classmate at the supermarket.\" (Esbarrei com um antigo colega de classe no supermercado.)","audio":"Run into","level":"A2","module":"Module 10: Friendship, Dating & Social Dynamics"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Pass out","secondary":"Desmaiar (perder a consciência)","desc":"Ficar inconsciente de forma repentina por calor, cansaço ou dor.","context":"Ex: \"It was so hot in the room that she passed out.\" (Estava tão quente na sala que ela desmaiou.)","audio":"Pass out","level":"A2","module":"Module 11: Health, Physical States & Fitness"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Throw up","secondary":"Vomitar","desc":"Expulsar o conteúdo do estômago pela boca devido a indisposição.","context":"Ex: \"The baby threw up on my shirt.\" (O bebê vomitou na minha camisa.)","audio":"Throw up","level":"A2","module":"Module 11: Health, Physical States & Fitness"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Work out","secondary":"Fazer exercícios físicos / Treinar na academia","desc":"Praticar musculação ou corrida para manter o corpo em boa forma.","context":"Ex: \"I work out at the gym three times a week.\" (Eu treinos na academia três vezes por semana.)","audio":"Work out","level":"A2","module":"Module 11: Health, Physical States & Fitness"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Warm up","secondary":"Fazer aquecimento físico antes de um esporte","desc":"Exercitar-se levemente para preparar os músculos para o treino.","context":"Ex: \"Always warm up before running to avoid injuries.\" (Sempre faça aquecimento antes de correr para evitar lesões.)","audio":"Warm up","level":"A2","module":"Module 11: Health, Physical States & Fitness"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Ease off / Ease up","secondary":"Aliviar a dor / Diminuir o ritmo de intensidade","desc":"Quando a dor diminui de intensidade ou a chuva amaina.","context":"Ex: \"Take this medicine and the pain will ease off.\" (Tome este remédio e a dor vai aliviar.)","audio":"Ease off / Ease up","level":"A2","module":"Module 11: Health, Physical States & Fitness"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Heal up","secondary":"Cicatrizar / Curar-se de uma ferida","desc":"Processo pelo qual um corte ou machucado se regenera por completo.","context":"Ex: \"The cut on my knee is healing up nicely.\" (O corte no meu joelho está cicatrizando muito bem.)","audio":"Heal up","level":"A2","module":"Module 11: Health, Physical States & Fitness"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Look up","secondary":"Procurar uma informação (no dicionário/Google)","desc":"Buscar o significado de uma palavra ou dado em uma fonte de referência.","context":"Ex: \"If you don't know the word, look it up in the dictionary.\" (Se não souber a palavra, procure-a no dicionário.)","audio":"Look up","level":"A2","module":"Module 12: Information, Learning & Studies"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Read over / Read through","secondary":"Ler atentamente do início ao fim para revisar","desc":"Examinar um documento ou texto para conferir se há erros.","context":"Ex: \"Read over your essay before submitting it.\" (Leia sua redação atentamente antes de enviá-la.)","audio":"Read over / Read through","level":"A2","module":"Module 12: Information, Learning & Studies"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Note down / Take down","secondary":"Anotar rapidamente no papel","desc":"Registrar por escrito pontos importantes durante uma aula ou palestra.","context":"Ex: \"Note down the homework assignment on your notebook.\" (Anote o dever de casa no seu caderno.)","audio":"Note down / Take down","level":"A2","module":"Module 12: Information, Learning & Studies"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Catch up (with/on)","secondary":"Pôr a matéria em dia / Colocar o papo em dia","desc":"Alcançar o mesmo nível de estudos de outros colegas ou atualizar-se.","context":"Ex: \"I missed three classes, so I need to catch up.\" (Faltei a três aulas, então preciso colocar a matéria em dia.)","audio":"Catch up (with/on)","level":"A2","module":"Module 12: Information, Learning & Studies"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Read out","secondary":"Ler em voz alta para outros ouvir","desc":"Pronunciar um texto em voz alta diante de uma sala ou público.","context":"Ex: \"The teacher asked Maria to read out the sentence.\" (O professor pediu à Maria para ler a frase em voz alta.)","audio":"Read out","level":"A2","module":"Module 12: Information, Learning & Studies"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Fill out / Fill in","secondary":"Preencher um formulário ou ficha","desc":"Completar os campos vazios de um documento impresso ou digital.","context":"Ex: \"Please fill out this registration form.\" (Por favor, preencha esta ficha de inscrição.)","audio":"Fill out / Fill in","level":"A2","module":"Module 12: Information, Learning & Studies"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Figure out","secondary":"Compreender / Encontrar a solução de um problema","desc":"Usar o raciocínio mental até entender a resposta de uma questão difícil.","context":"Ex: \"I can't figure out how to solve this math equation.\" (Não consigo descobrir/entender como resolver esta equação de matemática.)","audio":"Figure out","level":"B1","module":"Module 13: Problem Solving & Decision Making"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Work out","secondary":"Resolver com sucesso / Dar certo um plano","desc":"Chegar a uma solução negociada ou dar um bom resultado final.","context":"Ex: \"Don't worry, everything will work out in the end.\" (Não se preocupe, tudo vai dar certo no final.)","audio":"Work out","level":"B1","module":"Module 13: Problem Solving & Decision Making"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Find out","secondary":"Descobrir uma informação novidade","desc":"Tomar conhecimento de um fato novo que você não sabia antes.","context":"Ex: \"She found out that her friend was moving away.\" (Ela descobriu que o amigo dela estava se mudando.)","audio":"Find out","level":"B1","module":"Module 13: Problem Solving & Decision Making"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Sort out","secondary":"Organizar / Resolver uma confusão","desc":"Organizar um mal-entendido ou colocar em ordem papéis bagunçados.","context":"Ex: \"We have to sort out these billing issues today.\" (Nós temos que resolver estes problemas de cobrança hoje.)","audio":"Sort out","level":"B1","module":"Module 13: Problem Solving & Decision Making"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Deal with","secondary":"Lidar com um problema ou pessoa difícil","desc":"Assumir a responsabilidade para gerenciar ou resolver uma complicação.","context":"Ex: \"As a manager, she deals with customer complaints daily.\" (Como gerente, ela lida com reclamações de clientes diariamente.)","audio":"Deal with","level":"B1","module":"Module 13: Problem Solving & Decision Making"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Rule out","secondary":"Descartar uma possibilidade","desc":"Excluir uma opção por ser inviável ou impossível.","context":"Ex: \"The doctor ruled out any heart problems after the tests.\" (O médico descartou quaisquer problemas cardíacos após os exames.)","audio":"Rule out","level":"B1","module":"Module 13: Problem Solving & Decision Making"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Turn out","secondary":"Acontecer que / Resultar no final","desc":"Ter um desfecho ou revelar-se de determinada maneira no final.","context":"Ex: \"The party turned out to be amazing despite the rain.\" (A festa acabou sendo incrível apesar da chuva.)","audio":"Turn out","level":"B1","module":"Module 14: Events, Changes & Occurrences"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Come about","secondary":"Acontecer / Ocorrer (como resultado de algo)","desc":"Como um evento ou mudança veio a existir ou acontecer.","context":"Ex: \"How did this misunderstanding come about?\" (Como esse mal-entendido veio a acontecer?)","audio":"Come about","level":"B1","module":"Module 14: Events, Changes & Occurrences"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Show up / Turn up","secondary":"Aparecer / Chegar a um compromisso","desc":"Chegar a um evento, festa ou reunião onde era esperado.","context":"Ex: \"He showed up two hours late for the interview.\" (Ele apareceu/chegou duas horas atrasado para a entrevista.)","audio":"Show up / Turn up","level":"B1","module":"Module 14: Events, Changes & Occurrences"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"End up","secondary":"Acabar por (fazer algo ou ir parar em lugar não planejado)","desc":"Terminar em uma situação ou local que não estava nos planos iniciais.","context":"Ex: \"We got lost and ended up in a different city.\" (Nós nos perdemos e acabamos em uma cidade diferente.)","audio":"End up","level":"B1","module":"Module 14: Events, Changes & Occurrences"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Wind up","secondary":"Encerrar um evento ou terminar em certo estado","desc":"Finalizar uma reunião ou acabar caindo em uma situação desagradável.","context":"Ex: \"Let's wind up this meeting by 5 PM.\" (Vamos encerrar esta reunião até as 17h.)","audio":"Wind up","level":"B1","module":"Module 14: Events, Changes & Occurrences"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Turn up","secondary":"Aparecer de repente (algo perdido)","desc":"Quando um objeto sumido é reencontrado inesperadamente.","context":"Ex: \"My lost keys turned up under the couch.\" (Minhas chaves perdidas apareceram debaixo do sofá.)","audio":"Turn up","level":"B1","module":"Module 14: Events, Changes & Occurrences"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Give up","secondary":"Desistir de algo ou parar um hábito","desc":"Abandonar uma tentativa por dificuldade ou parar de consumir algo (ex: fumar).","context":"Ex: \"Never give up on your dreams!\" (Nunca desista dos seus sonhos!)","audio":"Give up","level":"B1","module":"Module 15: Habits, Continuation & Quitting"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Keep on","secondary":"Continuar fazendo algo repetidamente","desc":"Manter uma ação continuamente sem parar.","context":"Ex: \"She kept on working even though she was tired.\" (Ela continuou trabalhando mesmo estando cansada.)","audio":"Keep on","level":"B1","module":"Module 15: Habits, Continuation & Quitting"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Carry on","secondary":"Dar continuidade a uma tarefa após interrupção","desc":"Prosseguir com o trabalho após uma pausa ou obstáculo.","context":"Ex: \"Please carry on with your reading while I answer the phone.\" (Por favor, continuem com a leitura de vocês enquanto atendo o telefone.)","audio":"Carry on","level":"B1","module":"Module 15: Habits, Continuation & Quitting"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Go on","secondary":"Acontecer / Prosseguir dizendo algo","desc":"Continuar falando ou indicar 'O que está acontecendo?'.","context":"Ex: \"What is going on here?\" (O que está acontecendo aqui?)","audio":"Go on","level":"B1","module":"Module 15: Habits, Continuation & Quitting"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Give in","secondary":"Ceder à pressão / Render-se","desc":"Parar de resistir a um pedido insistente de outra pessoa.","context":"Ex: \"The parents gave in and bought the toy for the child.\" (Os pais cederam e compraram o brinquedo para a criança.)","audio":"Give in","level":"B1","module":"Module 15: Habits, Continuation & Quitting"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Phase out","secondary":"Eliminar gradualmente um processo ou produto","desc":"Reduzir o uso de algo aos poucos até sua descontinuação total.","context":"Ex: \"The government plans to phase out plastic bags by next year.\" (O governo planeja eliminar gradualmente as sacolas plásticas até o ano que vem.)","audio":"Phase out","level":"B1","module":"Module 15: Habits, Continuation & Quitting"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Fill in for","secondary":"Substituir temporariamente um colega no trabalho","desc":"Assumir os deveres de um funcionário que se ausentou.","context":"Ex: \"Can you fill in for me while I'm on vacation?\" (Você pode me substituir enquanto eu estiver de férias?)","audio":"Fill in for","level":"B1","module":"Module 16: Workplace Basics & Office Tasks"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Take over","secondary":"Assumir o controle/comando de uma tarefa ou empresa","desc":"Ganhar o controle ou responsabilidade de uma gerência ou função.","context":"Ex: \"The new CEO will take over the company next month.\" (O novo CEO vai assumir a empresa no próximo mês.)","audio":"Take over","level":"B1","module":"Module 16: Workplace Basics & Office Tasks"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Hand in / Turn in","secondary":"Entregar um trabalho/relatório a um superior","desc":"Entregar fisicamente ou digitalmente um documento a um chefe ou professor.","context":"Ex: \"Please hand in your monthly reports by Friday afternoon.\" (Por favor, entreguem seus relatórios mensais até sexta à tarde.)","audio":"Hand in / Turn in","level":"B1","module":"Module 16: Workplace Basics & Office Tasks"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Lay off","secondary":"Demitir por razões econômicas / Corte de pessoal","desc":"Encerrar o contrato de trabalhadores por redução de custos da empresa.","context":"Ex: \"The factory laid off 200 workers due to poor sales.\" (A fábrica demitiu 200 trabalhadores devido às baixas vendas.)","audio":"Lay off","level":"B1","module":"Module 16: Workplace Basics & Office Tasks"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Set up","secondary":"Configurar / Agendar uma reunião ou estrutura","desc":"Montar equipamentos ou agendar um compromisso formal de negócios.","context":"Ex: \"Please set up a video call with the client for 3 PM.\" (Por favor, agende uma chamada de vídeo com o cliente para as 15h.)","audio":"Set up","level":"B1","module":"Module 16: Workplace Basics & Office Tasks"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Wrap up","secondary":"Concluir / Encerrar uma reunião ou trabalho","desc":"Finalizar os últimos detalhes de uma reunião ou projeto.","context":"Ex: \"Let's wrap up this meeting, we are out of time.\" (Vamos encerrar esta reunião, nosso tempo acabou.)","audio":"Wrap up","level":"B1","module":"Module 16: Workplace Basics & Office Tasks"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Look forward to","secondary":"Aguardar ansiosamente por algo positivo","desc":"Estar animado e na expectativa de um evento futuro agradável (exige verbo com -ing após 'to').","context":"Ex: \"I am looking forward to meeting you next week.\" (Estou aguardando ansiosamente por conhecê-lo na semana que vem.)","audio":"Look forward to","level":"B1","module":"Module 17: Tri-Prepositional Phrasal Verbs I"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Run out of","secondary":"Ficar sem / Esgotar o suprimento de algo","desc":"Quando o estoque de um item (café, dinheiro, tempo, gasolina) acaba completamente.","context":"Ex: \"We ran out of milk, so I need to go to the store.\" (Nós ficamos sem leite, então preciso ir ao mercado.)","audio":"Run out of","level":"B1","module":"Module 17: Tri-Prepositional Phrasal Verbs I"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Cut down on","secondary":"Reduzir o consumo ou frequência de algo","desc":"Diminuir a quantidade de algo ingerido ou feito por motivo de saúde ou orçamento.","context":"Ex: \"I need to cut down on eating fast food.\" (Preciso reduzir o consumo de fast food.)","audio":"Cut down on","level":"B1","module":"Module 17: Tri-Prepositional Phrasal Verbs I"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Come up with","secondary":"Ideia / Inventar ou propor uma solução inovadora","desc":"Criar de forma criativa um plano, resposta ou ideia técnica.","context":"Ex: \"She came up with a brilliant marketing strategy.\" (Ela teve/inventou uma estratégia de marketing brilhante.)","audio":"Come up with","level":"B1","module":"Module 17: Tri-Prepositional Phrasal Verbs I"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Face up to","secondary":"Encarar uma realidade difícil de frente","desc":"Aceitar a verdade dolorosa de uma situação em vez de ignorá-la.","context":"Ex: \"You must face up to your responsibilities.\" (Você deve encarar as suas responsabilidades de frente.)","audio":"Face up to","level":"B1","module":"Module 17: Tri-Prepositional Phrasal Verbs I"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Keep up with","secondary":"Acompanhar o ritmo de velocidade de alguém","desc":"Manter a mesma velocidade de caminhada, estudo ou atualização que outros.","context":"Ex: \"Slow down! I can't keep up with you!\" (Vá devagar! Não consigo acompanhar o seu ritmo!)","audio":"Keep up with","level":"B1","module":"Module 17: Tri-Prepositional Phrasal Verbs I"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Get away with","secondary":"Sair impune de uma infração / Livrar-se da culpa","desc":"Fazer algo errado ou ilegal sem sofrer punição ou consequência.","context":"Ex: \"He stole a candy and thought he could get away with it.\" (Ele roubou um doce e achou que sairia impune.)","audio":"Get away with","level":"B1","module":"Module 18: Tri-Prepositional Phrasal Verbs II"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Put up with","secondary":"Tolerar / Aturar uma pessoa ou barulho chato","desc":"Aguentar uma situação incômoda sem reclamar.","context":"Ex: \"I cannot put up with your constant complaining anymore!\" (Eu não consigo mais aturar a sua reclamação constante!)","audio":"Put up with","level":"B1","module":"Module 18: Tri-Prepositional Phrasal Verbs II"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Stand up for","secondary":"Defender com firmeza os direitos de alguém","desc":"Lutar ou expressar defesa em favor de si mesmo ou dos fracos.","context":"Ex: \"You must stand up for your rights at work.\" (Você deve defender os seus direitos no trabalho com firmeza.)","audio":"Stand up for","level":"B1","module":"Module 18: Tri-Prepositional Phrasal Verbs II"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Look down on","secondary":"Menosprezar / Olhar com superioridade","desc":"Considerar-se superior a alguém por motivos econômicos ou sociais.","context":"Ex: \"It's wrong to look down on people who have less money.\" (É errado menosprezar as pessoas que têm menos dinheiro.)","audio":"Look down on","level":"B1","module":"Module 18: Tri-Prepositional Phrasal Verbs II"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Catch up on","secondary":"Colocar atraso em dia (sono/trabalho)","desc":"Dedicar tempo para recuperar trabalho, leitura ou sono pendente.","context":"Ex: \"I need to catch up on sleep this weekend.\" (Preciso colocar o meu sono em dia neste fim de semana.)","audio":"Catch up on","level":"B1","module":"Module 18: Tri-Prepositional Phrasal Verbs II"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Make up for","secondary":"Compensar uma falha ou atraso com algo bom","desc":"Oferecer algo bom para reequilibrar um erro ou ausência passada.","context":"Ex: \"He bought her flowers to make up for being late.\" (Ele comprou flores para ela para compensar o atraso.)","audio":"Make up for","level":"B1","module":"Module 18: Tri-Prepositional Phrasal Verbs II"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Piece of cake","secondary":"Mamão com açúcar (muito fácil)","desc":"Metáfora para descrever uma tarefa ou teste extremamente fácil de fazer.","context":"Ex: \"Don't worry about the exam, it was a piece of cake!\" (Não se preocupe com a prova, foi um mamão com açúcar!)","audio":"Piece of cake","level":"B1","module":"Module 19: Essential Everyday Idioms I (Conversational)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Break a leg","secondary":"Boa sorte! (Desejo tradicional)","desc":"Forma cultural de desejar sorte antes de uma apresentação pública ou teatro.","context":"Ex: \"You're going on stage now? Break a leg!\" (Você vai subir ao palco agora? Boa sorte!)","audio":"Break a leg","level":"B1","module":"Module 19: Essential Everyday Idioms I (Conversational)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Under the weather","secondary":"Sentir-se indisposto / Um pouco doente","desc":"Estar com mal-estar leve, gripe ou cansaço sem ser algo grave.","context":"Ex: \"I won't come to work today because I feel under the weather.\" (Não irei trabalhar hoje porque me sinto um pouco indisposto.)","audio":"Under the weather","level":"B1","module":"Module 19: Essential Everyday Idioms I (Conversational)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Hit the sack / Hit the hay","secondary":"Ir para a cama dormir","desc":"Expressão informal muito comum para dizer que vai dormir por estar exausto.","context":"Ex: \"I am exhausted, I am going to hit the sack.\" (Estou exausto, vou para a cama dormir.)","audio":"Hit the sack / Hit the hay","level":"B1","module":"Module 19: Essential Everyday Idioms I (Conversational)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Speak of the devil","secondary":"Falando no mau (olha quem chega!)","desc":"Dito quando a pessoa de quem se estava falando aparece de repente no local.","context":"Ex: \"Speak of the devil! We were just talking about you, John!\" (Falando no mau! Estávamos justamente falando de você, John!)","audio":"Speak of the devil","level":"B1","module":"Module 19: Essential Everyday Idioms I (Conversational)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Once in a blue moon","secondary":"Raramente / Uma vez a cada morte de bispo","desc":"Evento que acontece com frequência extremamente baixa.","context":"Ex: \"I only eat fast food once in a blue moon.\" (Eu só como fast food muito raramente.)","audio":"Once in a blue moon","level":"B1","module":"Module 19: Essential Everyday Idioms I (Conversational)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Bite the bullet","secondary":"Encarar uma decisão difícil com coragem","desc":"Enfrentar uma situação dolorosa ou inevitável sem mais procrastinar.","context":"Ex: \"I decided to bite the bullet and pay for the expensive car repair.\" (Decidi encarar a realidade e pagar pelo conserto caro do carro.)","audio":"Bite the bullet","level":"B1","module":"Module 20: Essential Everyday Idioms II (Decisions & Action)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Hit the nail on the head","secondary":"Acertar na mosca / Falar a verdade exata","desc":"Descrever com precisão exata a causa de um problema ou raciocínio.","context":"Ex: \"Your analysis hit the nail on the head!\" (Sua análise acertou na mosca!)","audio":"Hit the nail on the head","level":"B1","module":"Module 20: Essential Everyday Idioms II (Decisions & Action)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Call it a day","secondary":"Encerrar o expediente de trabalho","desc":"Decidir parar de trabalhar pelo resto do dia atual.","context":"Ex: \"We have worked for nine hours, let's call it a day.\" (Trabalhamos por nove horas, vamos encerrar o expediente por hoje.)","audio":"Call it a day","level":"B1","module":"Module 20: Essential Everyday Idioms II (Decisions & Action)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Spill the beans","secondary":"Dar com a língua nos dentes / Contar um segredo","desc":"Revelar informações confidenciais não intencionalmente ou por fofoca.","context":"Ex: \"Don't spill the beans about the surprise party!\" (Não dê com a língua nos dentes sobre a festa surpresa!)","audio":"Spill the beans","level":"B1","module":"Module 20: Essential Everyday Idioms II (Decisions & Action)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Burn the midnight oil","secondary":"Trabalhar/estudar até de madrugada","desc":"Estender a jornada de estudo ou trabalho noite adentro.","context":"Ex: \"She is burning the midnight oil to prepare for final exams.\" (Ela está estudando até de madrugada para se preparar para as provas finais.)","audio":"Burn the midnight oil","level":"B1","module":"Module 20: Essential Everyday Idioms II (Decisions & Action)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Beat around the bush","secondary":"Fazer rodeios / Enrolar sem ir ao ponto","desc":"Evitar falar do assunto principal por vergonha ou desconforto.","context":"Ex: \"Stop beating around the bush and tell me what happened!\" (Pare de fazer rodeios e me diga o que aconteceu!)","audio":"Beat around the bush","level":"B1","module":"Module 20: Essential Everyday Idioms II (Decisions & Action)"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Touch base (with)","secondary":"Fazer um contato rápido para alinhamento","desc":"Entrar em contato brevemente com um colega ou cliente para atualizar o status.","context":"Ex: \"I will touch base with you after the client meeting.\" (Farei um contato rápido com você após a reunião com o cliente.)","audio":"Touch base (with)","level":"B2","module":"Module 21: Executive Business & Work Communication"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Follow up (on)","secondary":"Acompanhar o andamento de um processo/e-mail","desc":"Dar continuidade ou verificar se uma tarefa anterior foi cumprida.","context":"Ex: \"I am writing to follow up on my previous email.\" (Estou escrevendo para acompanhar o andamento do meu e-mail anterior.)","audio":"Follow up (on)","level":"B2","module":"Module 21: Executive Business & Work Communication"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Bring up","secondary":"Trazer um assunto à tona em reunião","desc":"Mencionar ou introduzir um novo tema durante uma discussão de negócios.","context":"Ex: \"He brought up the issue of salary increases during the conference.\" (Ele trouxe o assunto de aumentos salariais à tona durante a conferência.)","audio":"Bring up","level":"B2","module":"Module 21: Executive Business & Work Communication"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Carry out","secondary":"Executar/Realizar uma tarefa ou pesquisa","desc":"Executar rigorosamente um plano, experimento, pesquisa ou instrução.","context":"Ex: \"The team carried out extensive market research.\" (A equipe realizou uma extensa pesquisa de mercado.)","audio":"Carry out","level":"B2","module":"Module 21: Executive Business & Work Communication"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Back up","secondary":"Fazer cópia de segurança / Apoiar uma ideia","desc":"Fazer cópia de arquivos de computador ou dar suporte moral/evidência a um colega.","context":"Ex: \"Always back up your files before updating the software.\" (Sempre faça backup dos seus arquivos antes de atualizar o software.)","audio":"Back up","level":"B2","module":"Module 21: Executive Business & Work Communication"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Roll out","secondary":"Lançar um produto ou sistema oficialmente","desc":"Apresentar ou disponibilizar uma novidade tecnológica ou serviço para o mercado público.","context":"Ex: \"The company plans to roll out the new software feature nationwide.\" (A empresa planeja lançar o novo recurso do software em todo o país.)","audio":"Roll out","level":"B2","module":"Module 21: Executive Business & Work Communication"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Turn down","secondary":"Recusar uma proposta ou convite","desc":"Rejeitar formalmente uma oferta de emprego, proposta financeira ou pedido.","context":"Ex: \"She turned down the job offer because the salary was too low.\" (Ela recusou a oferta de emprego porque o salário era muito baixo.)","audio":"Turn down","level":"B2","module":"Module 22: Negotiation, Strategy & Rejection"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Back off","secondary":"Recuar em uma exigência / Dar um passo atrás","desc":"Ceder ou afastar-se de uma postura de pressão em negociações agressivas.","context":"Ex: \"The union backed off from their strike threat.\" (O sindicato recuou de sua ameaça de greve.)","audio":"Back off","level":"B2","module":"Module 22: Negotiation, Strategy & Rejection"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Stand firm / Stand ground","secondary":"Manter-se firme na negociação sem ceder","desc":"Manter a posição negociada apesar de fortes pressões externas.","context":"Ex: \"Our team stood firm on the price terms.\" (Nossa equipe manteve-se firme nos termos de preço.)","audio":"Stand firm / Stand ground","level":"B2","module":"Module 22: Negotiation, Strategy & Rejection"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Weigh up","secondary":"Ponderar prós e contras de uma decisão","desc":"Avaliar detalhadamente vantagens e desvantagens antes de optar.","context":"Ex: \"We need to weigh up the risks against the benefits.\" (Precisamos ponderar os riscos em relação aos benefícios.)","audio":"Weigh up","level":"B2","module":"Module 22: Negotiation, Strategy & Rejection"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Compromise on","secondary":"Fazer concessões mútuas para fechar acordo","desc":"Ceder em alguns pontos para chegar a um consenso benéfico para ambas as partes.","context":"Ex: \"Both parties had to compromise on the final price.\" (Ambas as partes tiveram que fazer concessões no preço final.)","audio":"Compromise on","level":"B2","module":"Module 22: Negotiation, Strategy & Rejection"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Hammer out","secondary":"Chegar a um acordo após longas discussões","desc":"Forjar e finalizar os termos de um contrato difícil após horas de debates.","context":"Ex: \"Lawyers managed to hammer out a settlement agreement.\" (Advogados conseguiram forjar e finalizar um acordo de conciliação.)","audio":"Hammer out","level":"B2","module":"Module 22: Negotiation, Strategy & Rejection"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Bail out","secondary":"Socorrer financeiramente uma empresa prestes a falir","desc":"Injetar capital financeiro para salvar uma instituição em colapso.","context":"Ex: \"The government decided to bail out the struggling bank.\" (O governo decidiu socorrer financeiramente o banco em crise.)","audio":"Bail out","level":"B2","module":"Module 23: Finance, Markets & Corporate Strategy"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Write off","secondary":"Dar um débito/dívida como perdido no balanço","desc":"Reconhecer contabilmente que uma dívida não será recuperada.","context":"Ex: \"The company wrote off $2 million in bad debts.\" (A empresa deu baixa em US$ 2 milhões em dívidas perdidas.)","audio":"Write off","level":"B2","module":"Module 23: Finance, Markets & Corporate Strategy"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Cash in on","secondary":"Lucrar em cima de uma oportunidade ou tendência","desc":"Aproveitar comercialmente um momento para obter altos ganhos financeiros.","context":"Ex: \"Many tech firms cashed in on the demand for remote tools.\" (Muitas empresas de tecnologia lucraram em cima da demanda por ferramentas remotas.)","audio":"Cash in on","level":"B2","module":"Module 23: Finance, Markets & Corporate Strategy"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Scale up","secondary":"Expandir o tamanho/escala de operações de um negócio","desc":"Aumentar a capacidade produtiva e de mercado de uma startup ou fábrica.","context":"Ex: \"The startup received funding to scale up its production.\" (A startup recebeu financiamento para expandir a sua produção em escala.)","audio":"Scale up","level":"B2","module":"Module 23: Finance, Markets & Corporate Strategy"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Branch out","secondary":"Diversificar ramos de atuação de uma empresa","desc":"Expandir os negócios para novos setores ou linhas de produtos não tradicionais.","context":"Ex: \"The publisher is branching out into digital audiobooks.\" (A editora está se diversificando para o ramo de audiolivros digitais.)","audio":"Branch out","level":"B2","module":"Module 23: Finance, Markets & Corporate Strategy"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Float on / Go public","secondary":"Lançar ações na bolsa de valores (abrir capital)","desc":"Realizar uma Oferta Pública Inicial (IPO) de ações do mercado financeiro.","context":"Ex: \"The company was floated on the London Stock Exchange.\" (A empresa teve suas ações lançadas na Bolsa de Valores de Londres.)","audio":"Float on / Go public","level":"B2","module":"Module 23: Finance, Markets & Corporate Strategy"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Stem from","secondary":"Derivar de / Ter sua causa raiz em","desc":"Explicar a origem primária de um comportamento ou problema social.","context":"Ex: \"His lack of confidence stems from childhood experiences.\" (A falta de confiança dele deriva de experiências da infância.)","audio":"Stem from","level":"B2","module":"Module 24: Advanced Figurative Verbs & Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Give rise to","secondary":"Dar origem a / Desencadear","desc":"Causar o aparecimento de novas circunstâncias ou controvérsias.","context":"Ex: \"The new tax policy gave rise to widespread public protests.\" (A nova política fiscal deu origem a protestos públicos generalizados.)","audio":"Give rise to","level":"B2","module":"Module 24: Advanced Figurative Verbs & Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Serve as (a catalyst)","secondary":"Servir como (um catalisador / elemento impulsionador)","desc":"Atuar no papel de um fator acelerador de transformações.","context":"Ex: \"The crisis served as a catalyst for political reform.\" (A crise serviu como um catalisador para a reforma política.)","audio":"Serve as (a catalyst)","level":"B2","module":"Module 24: Advanced Figurative Verbs & Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Fall short of","secondary":"Ficar aquém de (metas/expectativas)","desc":"Não atingir um padrão ou objetivo numérico previamente exigido.","context":"Ex: \"The company's quarterly revenue fell short of target by 5%.\" (A receita trimestral da empresa ficou 5% aquém da meta.)","audio":"Fall short of","level":"B2","module":"Module 24: Advanced Figurative Verbs & Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Single out","secondary":"Destacar / Selecionar alguém individualmente","desc":"Separar uma pessoa ou item de um grupo para elogiar ou criticar.","context":"Ex: \"The teacher singled out John for his excellent essay.\" (O professor destacou o John por sua excelente redação.)","audio":"Single out","level":"B2","module":"Module 24: Advanced Figurative Verbs & Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Gloss over","secondary":"Passar por cima de um erro / Encobrir superficiavelmente","desc":"Tratar um assunto sério de forma superficial para esconder falhas.","context":"Ex: \"The report glossed over the security vulnerabilities.\" (O relatório passou por cima das vulnerabilidades de segurança.)","audio":"Gloss over","level":"B2","module":"Module 24: Advanced Figurative Verbs & Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Smooth over","secondary":"Acalmar / Suavizar um mal-entendido ou atrito","desc":"Tentar resolver divergências de forma conciliadora para manter a paz.","context":"Ex: \"He tried to smooth over the disagreement between the two departments.\" (Ele tentou suavizar o desentendimento entre os dois departamentos.)","audio":"Smooth over","level":"B2","module":"Module 25: Diplomatic Communication & Persuasion"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Talk into","secondary":"Convencer / Persuadir alguém a fazer algo","desc":"Usar a fala persuasiva para fazer outra pessoa concordar com um plano.","context":"Ex: \"She talked me into joining the new project.\" (Ela me convenceu a me juntar ao novo projeto.)","audio":"Talk into","level":"B2","module":"Module 25: Diplomatic Communication & Persuasion"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Soften up","secondary":"Amaciar alguém antes de fazer um pedido difícil","desc":"Tratar alguém com agrados ou elogios prévios para facilitar um favor.","context":"Ex: \"They took the client to an expensive dinner to soften him up.\" (Eles levaram o cliente para um jantar caro para amaciá-lo.)","audio":"Soften up","level":"B2","module":"Module 25: Diplomatic Communication & Persuasion"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Win over","secondary":"Conquistar a simpatia ou apoio de alguém hesitante","desc":"Converter a opinião desfavorável de uma pessoa ao seu lado.","context":"Ex: \"His passionate presentation won over the skeptical investors.\" (Sua apresentação apaixonada conquistou o apoio dos investidores céticos.)","audio":"Win over","level":"B2","module":"Module 25: Diplomatic Communication & Persuasion"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Play down","secondary":"Minimizar a gravidade de um problema em público","desc":"Tentar fazer com que uma crise ou falha pareça menos importante do que é.","context":"Ex: \"The spokesperson played down the impact of the data leak.\" (O porta-voz minimizou a gravidade do impacto do vazamento de dados.)","audio":"Play down","level":"B2","module":"Module 25: Diplomatic Communication & Persuasion"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Iron out","secondary":"Eliminar pequenos detalhes ou divergências de um plano","desc":"Resolver pendências menores e deixar um contrato ou estratégia impecável.","context":"Ex: \"We need another meeting to iron out the remaining contract details.\" (Precisamos de outra reunião para eliminar os últimos detalhes do contrato.)","audio":"Iron out","level":"B2","module":"Module 25: Diplomatic Communication & Persuasion"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Ahead of the curve","secondary":"À frente do seu tempo / Inovador em relação à concorrência","desc":"Estar mais avançado ou preparado do que os concorrentes do mercado.","context":"Ex: \"To stay ahead of the curve, our company invests heavily in R&D.\" (Para ficar à frente da concorrência, nossa empresa investe pesado em P&D.)","audio":"Ahead of the curve","level":"B2","module":"Module 26: Advanced Business & Leadership Idioms"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"The ball is in your court","secondary":"A decisão/próximo passo é com você","desc":"Metáfora do tênis para dizer que agora é a vez da outra pessoa agir.","context":"Ex: \"We made our final offer; now the ball is in their court.\" (Fizemos nossa oferta final; agora a decisão é deles.)","audio":"The ball is in your court","level":"B2","module":"Module 26: Advanced Business & Leadership Idioms"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Behind the scenes","secondary":"Bastidores / Nos bastidores (sem alarde público)","desc":"Trabalho ou negociações feitas em ambiente reservado longe dos holofotes.","context":"Ex: \"A lot of hard work happens behind the scenes in event management.\" (Muito trabalho duro acontece nos bastidores na gestão de eventos.)","audio":"Behind the scenes","level":"B2","module":"Module 26: Advanced Business & Leadership Idioms"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Raise the bar","secondary":"Elevar o nível / Elevar os padrões de exigência","desc":"Aumentar os padrões de qualidade esperados para superar limites.","context":"Ex: \"The new iPhone model really raised the bar for smartphone cameras.\" (O novo modelo de iPhone realmente elevou o nível para câmeras de celular.)","audio":"Raise the bar","level":"B2","module":"Module 26: Advanced Business & Leadership Idioms"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Cutting-edge / Game changer","secondary":"Tecnologia de ponta / Algo que muda o jogo completamente","desc":"Uso das tecnologias mais avançadas ou inovações revolucionárias.","context":"Ex: \"This medical facility uses cutting-edge technology.\" (Este centro médico usa tecnologia de ponta.)","audio":"Cutting-edge / Game changer","level":"B2","module":"Module 26: Advanced Business & Leadership Idioms"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Touch and go","secondary":"Situação incerta / Na corda bamba com risco de falha","desc":"Momento crítico de risco em que o resultado positivo não é garantido.","context":"Ex: \"The surgery was touch and go for a few hours, but he recovered.\" (A cirurgia esteve na corda bamba por algumas horas, mas ele se recuperou.)","audio":"Touch and go","level":"B2","module":"Module 26: Advanced Business & Leadership Idioms"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Binge-watch","secondary":"Maratonar séries ou filmes sem parar","desc":"Assistir a múltiplos episódios de uma série de TV de uma só vez.","context":"Ex: \"I binge-watched the entire season of Stranger Things in one weekend.\" (Eu maratonei a temporada inteira de Stranger Things em um único fim de semana.)","audio":"Binge-watch","level":"B2","module":"Module 27: Native Slang & Informal Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Catch on","secondary":"Virar moda / Entender uma piada sutil","desc":"Tornar-se muito popular ou perceber o sentido de algo após um tempo.","context":"Ex: \"This new social media trend is catching on quickly among teenagers.\" (Esta nova tendência de rede social está virando moda rapidamente entre os adolescentes.)","audio":"Catch on","level":"B2","module":"Module 27: Native Slang & Informal Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Bail on","secondary":"Dar o cano em alguém / Furar um compromisso","desc":"Desistir de um encontro combinado com amigos na última hora.","context":"Ex: \"I can't believe he bailed on us at the last minute!\" (Não acredito que ele deu o cano na gente no último minuto!)","audio":"Bail on","level":"B2","module":"Module 27: Native Slang & Informal Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Chill out","secondary":"Relaxar / Ficar de boa","desc":"Acalmar-se ou passar tempo descansando sem estresse.","context":"Ex: \"Chill out! Everything is going to be fine.\" (Relaxe / Fique de boa! Tudo vai ficar bem.)","audio":"Chill out","level":"B2","module":"Module 27: Native Slang & Informal Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Flake out / Flake","secondary":"Ser uma pessoa não confiável que sempre fura compromissos","desc":"Ação de alguém que constantemente cancela planos em cima da hora.","context":"Ex: \"She always flakes out when we plan a trip.\" (Ela sempre fura quando planejamos uma viagem.)","audio":"Flake out / Flake","level":"B2","module":"Module 27: Native Slang & Informal Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Hyped up","secondary":"Empolgado / Entusiasmado ao extremo","desc":"Estar em estado de grande expectativa e energia por um evento futuro.","context":"Ex: \"The fans are hyped up for the new album release.\" (Os fãs estão eufóricos/empolgados para o lançamento do novo álbum.)","audio":"Hyped up","level":"B2","module":"Module 27: Native Slang & Informal Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Convey a sense of","secondary":"Transmitir a sensação / atmosfera de algo no texto","desc":"Utilizar palavras para evocar um sentimento de saudade, tensão ou alegria na literatura.","context":"Ex: \"The author uses vivid descriptions to convey a sense of solitude.\" (O autor usa descrições vivas para transmitir uma sensação de solidão.)","audio":"Convey a sense of","level":"B2","module":"Module 28: B2 Master Mastery - Literature & Media Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Underlying theme","secondary":"Tema subjacente / Mensagem nas entrelinhas de uma obra","desc":"A mensagem filosófica oculta por trás da narrativa da história.","context":"Ex: \"The underlying theme of the novel is the conflict between tradition and modernity.\" (O tema subjacente do romance é o conflito entre tradição e modernidade.)","audio":"Underlying theme","level":"B2","module":"Module 28: B2 Master Mastery - Literature & Media Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Employ metaphors","secondary":"Empregar / Fazer uso de metáforas expressivas","desc":"Uso consciente de figuras de linguagem em discursos ou ensaios acadêmicos.","context":"Ex: \"The poet employs metaphors of nature to represent human emotions.\" (O poeta emprega metáforas da natureza para representar emoções humanas.)","audio":"Employ metaphors","level":"B2","module":"Module 28: B2 Master Mastery - Literature & Media Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Stark contrast / Set in contrast","secondary":"Contraste nítido e gritante entre duas ideias","desc":"Destacar a diferença marcante e oposta entre dois conceitos.","context":"Ex: \"Her quiet personality is in stark contrast to her loud brother.\" (A personalidade quieta dela está em contraste nítido com seu irmão barulhento.)","audio":"Stark contrast / Set in contrast","level":"B2","module":"Module 28: B2 Master Mastery - Literature & Media Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Set the stage (for)","secondary":"Preparar o terreno para um evento futuro histórico","desc":"Criar as condições que viabilizam um grande acontecimento subsequente.","context":"Ex: \"The agreement set the stage for economic recovery.\" (O acordo preparou o terreno para a recuperação econômica.)","audio":"Set the stage (for)","level":"B2","module":"Module 28: B2 Master Mastery - Literature & Media Nuances"},{"cat":"phrasal","catLabel":"PHRASAL VERB","primary":"Master Capstone Project","secondary":"Projeto de maestria B2 concluído com sucesso","desc":"Atingimento da proficiência Upper-Intermediate completa no curso.","context":"Ex: \"Congratulations! You have completed the Master Capstone of B2 Phrasal Verbs & Idioms!\" (Parabéns! Você concluiu o Projeto Master Capstone de Phrasal Verbs e Idiomas B2!)","audio":"Master Capstone Project","level":"B2","module":"Module 28: B2 Master Mastery - Literature & Media Nuances"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"/iː/ vs /ɪ/ & /uː/ vs /ʊ/","secondary":"1. Vogais Curtas vs Longas Essenciais (/iː/ vs /ɪ/ & /uː/ vs /ʊ/)","desc":"Em inglês, a duração e a tensão dos lábios mudam o significado da palavra. Diferencie o 'ee' sorridente do 'i' curto e relaxado.","context":"Som /iː/ (Long EE): Estique os lábios firmemente como um sorriso (ex: Sheep, Feet, Beach).","audio":"Sheep","level":"A1","module":"🔵 Level A1: Fundamentos dos Sons & Articulação Inicial"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"/h/, /w/, /v/","secondary":"2. Consoantes Iniciais Críticas (H Aspirado vs Mudo, W vs V)","desc":"Aprenda a soprar o 'H' inicial, o som suave do 'W' e a vibração labiodental do 'V'.","context":"Som /h/ Aspirado: Sopro suave na garganta (ex: House, Hello, Happy, Hotel).","audio":"Wine","level":"A1","module":"🔵 Level A1: Fundamentos dos Sons & Articulação Inicial"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"/ðə/ vs /ðiː/, /oʊ/","secondary":"3. Pronúncia de Números & Artigos ('0' = Oh, 'The' /ðə/ vs /ðiː/)","desc":"Aprenda as convenções fonéticas nativas para números e para o artigo definido 'The'.","context":"Dígito Zero em telefones: Pronuncia-se como a letra 'Oh' (/oʊ/) em vez de 'Zero' (ex: 555-0192 ➔ 'five-five-five, oh-one-nine-two').","audio":"The book","level":"A1","module":"🔵 Level A1: Fundamentos dos Sons & Articulação Inicial"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"Trava Consoante Final","secondary":"4. Vício A1 a Eliminar: A Epêntese do 'I' Final","desc":"Elimine o hábito brasileiro de adicionar um som de 'i' no final de palavras terminadas em consoante.","context":"Vício Comum: Pronunciar 'stopi', 'likey', 'facebooki', 'biggi'.","audio":"Stop","level":"A1","module":"🔵 Level A1: Fundamentos dos Sons & Articulação Inicial"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"/æ/ vs /ʌ/","secondary":"5. Vogal Aberta vs Neutra (/æ/ vs /ʌ/ - 'Cat' vs 'Cut')","desc":"Aprenda a diferenciar o som de 'A' sorridente e aberto (Cat) do som de 'A/Â' curto e relaxado vindo da garganta (Cut).","context":"Som /æ/ (Cat, Bad, Hat): Abra bem a boca na vertical e estique levemente os lábios. É um som intermediário entre 'É' e 'Á'.","audio":"Cat","level":"A1","module":"🔵 Level A1: Fundamentos dos Sons & Articulação Inicial"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"/t/, /d/, /ɪd/","secondary":"1. Regra Definitiva do Sufixo -ED no Passado Regular (/t/, /d/, /ɪd/)","desc":"O sufixo -ED no passado NÃO se pronuncia sempre como 'ed'. Existem 3 sons distintos dependendo do som final do verbo base.","context":"Som /t/ (Voz Desativada): Após consoantes surdas p, k, f, s, sh, ch (ex: Walked /wɔːkt/, Stopped /stɒpt/, Liked /laɪkt/).","audio":"Walked","level":"A2","module":"🟢 Level A2: Flexões Gramaticais, Plurais & O Som TH"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"/s/, /z/, /ɪz/","secondary":"2. Sufixo de Plural e 3ª Pessoa -S / -ES (/s/, /z/, /ɪz/)","desc":"A terminação -S pode soar como 'S' seco, 'Z' vibrado ou adicionar a sílaba 'IZ'.","context":"Som /s/: Após consoantes surdas p, t, k, f (ex: Cats /kæts/, Books /bʊks/, Cups /kʌps/).","audio":"Cats","level":"A2","module":"🟢 Level A2: Flexões Gramaticais, Plurais & O Som TH"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"/θ/ e /ð/","secondary":"3. Domínio do Som TH (/θ/ Desvozeado vs /ð/ Vozeado)","desc":"Coloque a ponta da língua levemente entre os dentes superiores e inferiores.","context":"Som /θ/ (Desvozeado): Sem vibração nas cordas vocais, apenas sopro de ar (ex: Think, Three, Thank, Bath, Math, Teeth).","audio":"Think","level":"A2","module":"🟢 Level A2: Flexões Gramaticais, Plurais & O Som TH"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"/ə/","secondary":"4. O Som Schwa (/ə/) em Sílabas Átonas","desc":"O Schwa é o som vocálico mais comum do inglês. É um som neutro e relaxado que ocorre em sílabas não acentuadas.","context":"Qualquer vogal (a, e, i, o, u) pode virar Schwa quando não recebe o estresse da palavra.","audio":"About","level":"A2","module":"🟢 Level A2: Flexões Gramaticais, Plurais & O Som TH"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"Silent Letters & Informal Contractions","secondary":"5. Letras Mudas Clássicas & Reduções Informais (Gonna, Wanna)","desc":"Identifique consoantes que não devem ser pronunciadas e domines as reduções mais usadas do dia a dia.","context":"B Mudo (após M): Não pronuncie o B final em palavras como Climb (/klaɪm/), Comb (/koʊm/), Doubt (/daʊt/).","audio":"Walk","level":"A2","module":"🟢 Level A2: Flexões Gramaticais, Plurais & O Som TH"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"C + V Linking","secondary":"1. Connected Speech I (Fusão Consoante + Vogal)","desc":"Na fala fluida, a consoante final de uma palavra junta-se diretamente à vogal inicial da palavra seguinte.","context":"Pick it up ➔ Pronuncia-se como 'Pi-ki-táp' (/pɪ.kɪ.tʌp/).","audio":"Pick it up","level":"B1","module":"🟡 Level B1: Fala Conectada, Ritmo & Homófonos"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"[ɾ] e [ʔ]","secondary":"2. O Flap T / Flap D ([ɾ]) & Glottal Stop ([ʔ])","desc":"No inglês americano, o 'T' entre vogais transforma-se em um som rápido de 'R' brando, ou é travado na garganta.","context":"Flap T ([ɾ]): O T/DD entre vogais soa como o R de 'caro' (ex: Water ➔ 'Wá-rer', City ➔ 'Sí-ri', Better ➔ 'Bé-rer').","audio":"Water","level":"B1","module":"🟡 Level B1: Fala Conectada, Ritmo & Homófonos"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"ˈˈˈ Word Stress","secondary":"3. Sílaba Tônica (Word Stress: Substantivo vs Verbo)","desc":"A posição da sílaba tônica em palavras de duas sílabas pode alterar totalmente a função gramatical.","context":"Substantivo ➔ Estresse na 1ª sílaba (ex: REcord /ˈrek.ɚd/ = o disco/registro).","audio":"REcord (Substantivo)","level":"B1","module":"🟡 Level B1: Fala Conectada, Ritmo & Homófonos"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"Homophones","secondary":"4. Guia Completo de Homófonos (Sons Idênticos, Grafias Diferentes)","desc":"Palavras com escrita e significados totalmente diferentes, mas que possuem a mesma pronúncia exata.","context":"There / Their / They're ➔ Todas pronunciadas /ðɛər/.","audio":"There","level":"B1","module":"🟡 Level B1: Fala Conectada, Ritmo & Homófonos"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"[ɫ] vs [l]","secondary":"5. O Som do Dark L ([ɫ]) vs Light L ([l])","desc":"Elimine o vício de transformar o 'L' final no som da vogal 'U' do português.","context":"Light L (Início de sílaba): Ponta da língua toca os dentes superiores frontais (ex: Light, Like, Lemon).","audio":"Milk","level":"B1","module":"🟡 Level B1: Fala Conectada, Ritmo & Homófonos"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"Assimilation & Elision","secondary":"1. Connected Speech II (Assimilação, Elisão & Intrusion)","desc":"Fenômenos fonéticos avançados que fundem ou deletam sons na fala rápida nativa.","context":"Assimilação: 'Did you' vira 'Didja' (/dɪdʒə/); 'Would you' vira 'Wouldja' (/wʊdʒə/).","audio":"Did you","level":"B2","module":"🔴 Level B2: Fluidez Nativa Avançada, Entonação & Nuances"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"Intonation ↗ ↘","secondary":"2. Padrões de Entonação & Ênfase de Contraste","desc":"A entonação expressa a atitude do falante. Mudar a palavra enfatizada altera o foco da frase.","context":"Entonação Ascendente (Rising ↗): Perguntas de Sim/Não (ex: 'Are you coming? ↗').","audio":"Are you coming? ↗","level":"B2","module":"🔴 Level B2: Fluidez Nativa Avançada, Entonação & Nuances"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"Homographs & /aɪ, eɪ, ɔɪ.../","secondary":"3. Homógrafos & Os 8 Diftongos do Inglês","desc":"Diferencie palavras com a mesma escrita e domine as vogais deslizadas duplas.","context":"Homógrafos: Live /lɪv/ (morar) vs Live /laɪv/ (ao vivo); Read /riːd/ (presente) vs Read /red/ (passado).","audio":"Live (Verbo)","level":"B2","module":"🔴 Level B2: Fluidez Nativa Avançada, Entonação & Nuances"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"US vs UK & Brands","secondary":"4. Inglês Americano vs Britânico & Marcas Globais","desc":"Entenda a rotacidade do 'R' e pronuncie marcas internacionais corretamente.","context":"Rotacidade do 'R': Inglês Americano pronuncia o R pós-vocálico (Car /kɑːr/, Park /pɑːrk/); o Britânico omite o R (Car /kɑː/, Park /pɑːk/).","audio":"Car (US)","level":"B2","module":"🔴 Level B2: Fluidez Nativa Avançada, Entonação & Nuances"},{"cat":"phonetics","catLabel":"FONÉTICA","primary":"Strong /æ, ɑː, uː/ vs Weak /ə, ɪ/","secondary":"5. Weak Forms & Redução Vocálica em Palavras Gramaticais","desc":"Nativos raramente usam a pronúncia 'forte' de palavras como AND, FOR, CAN e TO dentro de frases. Aprenda a reduzir essas estruturas para alcançar o ritmo nativo.","context":"CAN: Forma Forte /kæn/ (usada só em respostas curtas) ➔ Forma Fraca /kən/ ou /kn/ na frase (ex: 'I can do it' ➔ /aɪ kən duː ɪt/).","audio":"I CAN do it (Forte - Ênfase)","level":"B2","module":"🔴 Level B2: Fluidez Nativa Avançada, Entonação & Nuances"}]);

